const sections: PrayerSection[] = [{"id":"preparatory-prayers-modeh-ani","heading":"Modeh Ani","group":"Preparatory Prayers","lines":[{"he":"ָמוֹדֶה אֲנִי לְפָנֶיךָ, מֶלֶךְ חַי וְקַיָּם, שֶׁהֶחֱזַרְתָּ בִּי נִשְׁמָתִי בְּחֶמְלָה, רַבָּה אֱמוּנָתֶךָ","en":"Mo-deh ani l'fan-e-cha"}]},{"id":"preparatory-prayers-netilat-yadayim","heading":"Netilat Yadayim","group":"Preparatory Prayers","lines":[{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְותָיו וְצִוָּנוּ עַל נְטִילַת יָדַיּם:"}]},{"id":"preparatory-prayers-asher-yatzar","heading":"Asher Yatzar","group":"Preparatory Prayers","lines":[{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם אֲשֶׁר יָצַר אֶת הָאָדָם בְּחָכְמָה וּבָרָא בו נְקָבִים נְקָבִים חֲלוּלִים חֲלוּלִים. גָּלוּי וְיָדוּעַ לִפְנֵי כִסֵּא כְבודֶךָ שֶׁאִם יִפָּתֵחַ אֶחָד מֵהֶם או יִסָּתֵם אֶחָד מֵהֶם אִי אֶפְשַׁר לְהִתְקַיֵּם וְלַעֲמוד לְפָנֶיךָ אֲפִילוּ שָׁעָה אֶחָת:"},{"he":"בָּרוּךְ אַתָּה ה' רופֵא כָל בָּשר וּמַפְלִיא לַעֲשות:"}]},{"id":"preparatory-prayers-elokai-neshama","heading":"Elokai Neshama","group":"Preparatory Prayers","lines":[{"he":"אֱלהַי. נְשָׁמָה שֶׁנָּתַתָּ בִּי טְהורָה הִיא. אַתָּה בְרָאתָהּ. אַתָּה יְצַרְתָּהּ. אַתָּה נְפַחְתָּהּ בִּי. וְאַתָּה מְשַׁמְּרָהּ בְּקִרְבִּי. וְאַתָּה עָתִיד לִטְּלָהּ מִמֶּנִּי. וּלְהַחֲזִירָהּ בִּי לֶעָתִיד לָבוא. כָּל זְמַן שֶׁהַנְּשָׁמָה בְּקִרְבִּי מודֶה אֲנִי לְפָנֶיךָ ה' אֱלהַי וֵאלהֵי אֲבותַי. רִבּון כָּל הַמַּעֲשים אֲדון כָּל הַנְּשָׁמות:"},{"he":"בָּרוּךְ אַתָּה ה' הַמַּחֲזִיר נְשָׁמות לִפְגָרִים מֵתִים:"}]},{"id":"preparatory-prayers-tzitzit","heading":"Tzitzit","group":"Preparatory Prayers","lines":[{"he":"בָּרוּךְ אַתָּה ה'. אֱלהֵינוּ מֶלֶךְ הָעולָם. אֲשֶׁר קִדְּשָׁנוּ בְּמִצְותָיו וְצִוָּנוּ עַל מִצְוַת צִיצִית:"},{"he":"יְהִי רָצון מִלְּפָנֶיךָ. ה' אֱלהַי וֵאלהֵי אֲבותַי. שֶׁתְּהֵא חֲשׁוּבָה מִצְוַת צִיצִית לְפָנֶיךָ כְּאִלּוּ קִיַּמְתִּיהָ בְּכָל פְּרָטֶיהָ וְדִקְדּוּקֶיהָ וְכַוָּנותֶיהָ. וְתַרְיַ\"ג מִצְות הַתְּלוּיִם בָּהּ. אָמֵן סֶלָה:"},{"he":"מִצְוַת ה' בָּרָה מְאִירַת עֵינָיִם:"}]},{"id":"preparatory-prayers-tallit","heading":"Tallit","group":"Preparatory Prayers","lines":[{"he":"בָּרְכִי נַפְשִׁי אֶת ה'. ה' אֱלהַי גָּדַלְתָּ מְאד. הוד וְהָדָר לָבָשְׁתָּ:"},{"he":"עוטֶה אור כַּשּלְמָה. נוטֶה שָׁמַיִם כַּיְרִיעָה:"},{"he":"לְשֵׁם יִחוּד קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּהּ. בִּדְחִילוּ וּרְחִימוּ. לְיַחֵד שֵׁם י\"ה בו\"ה בְּיִחוּדָא שְׁלִים בְּשֵׁם כָּל יִשרָאֵל:"},{"he":"הֲרֵינִי מִתְעַטֵּף גּוּפִי בַּצִּיצִית. כֵּן תִּתְעַטֵּף נִשְׁמָתִי וּרְמַ\"ח אֵיבָרַי וּשְׁסָ\"ה גִידַי בְּאור הַצִּיצִית הָעולֶה תַרְיַ\"ג. וּכְשֵׁם שֶׁאֲנִי מִתְכַּסֶּה בְּטַלִּית בָּעולָם הַזֶּה. כַּךְ אֶזְכֶּה לַחֲלוּקָא דְרַבָּנָן. וּלְטַלִּית נָאֶה לָעולָם הַבָּא בְּגַן עֵדֶן. וְעַל יְדֵי מִצְוַת צִיצִית. תִּנָּצֵל נַפְשִׁי וְרוּחִי וְנִשְׁמָתִי וּתפילתי מִן הַחִיצונִים. וְהַטַּלִּית יִפְרוש כְּנָפָיו עֲלֵיהֶם. וְיַצִּילֵם כְּנֶשֶׁר יָעִיר קִנּו עַל גּוזָלָיו יְרַחֵף. וּתְהֵא חֲשׁוּבָה מִצְוַת צִיצִית לִפְנֵי הַקָּדושׁ בָּרוּךְ הוּא. כְּאִלּוּ קִיַּמְתִּיהָ בְּכָל פְּרָטֶיהָ וְדִקְדּוּקֶיהָ וְכַוָּנותֶיהָ. וְתַרְיַ\"ג מִצְות הַתְּלוּיִם בָּהּ. אָמֵן סֶלָה:"},{"he":"אוחז את הטלית בשתי ידיו ויברך מעומד להתעטף בציצית:"},{"he":"בָּרוּךְ אַתָּה ה'. אֱלהֵינוּ מֶלֶךְ הָעולָם. אֲשֶׁר קִדְּשָׁנוּ בְּמִצְותָיו. וְצִוָּנוּ לְהִתְעַטֵּף בַּצִיצִית:"},{"he":"מַה יָּקָר חַסְדְּךָ אֱלהִים. וּבְנֵי אָדָם בְּצֵל כְּנָפֶיךָ יֶחֱסָיוּן:"},{"he":"יִרְוְיֻן מִדֶּשֶׁן בֵּיתֶךָ וְנַחַל עֲדָנֶיךָ תַשְׁקֵם:"},{"he":"כִּי עִמְּךָ מְקור חַיִּים. בְּאורְךָ נִרְאֶה אור:"},{"he":"מְשׁוךְ חַסְדְּךָ לְידְעֶיךָ וְצִדְקָתְךָ לְיִשְׁרֵי לֵב:"}]},{"id":"preparatory-prayers-ma-tovu","heading":"Ma Tovu","group":"Preparatory Prayers","lines":[{"he":"מַה טּבוּ אהָלֶיךָ יַעֲקב מִשְׁכְּנתֶיךָ יִשרָאֵל:"},{"he":"וַאֲנִי בְּרב חַסְדְּךָ אָבא בֵיתֶךָ אֶשְׁתַּחֲוֶה אֶל הֵיכַל קָדְשְׁךָ בְּיִרְאָתֶךָ:"},{"he":"ה' אָהַבְתִּי מְעון בֵּיתֶךָ וּמְקום מִשְׁכַּן כְּבודֶךָ:"},{"he":"וַאֲנִי אֶשְׁתַּחֲוֶה וְאֶכְרָעָה אֶבְרְכָה לִפְנֵי ה' עשי:"},{"he":"וַאֲנִי תפילתי לְךָ ה' עֵת רָצון אֱלהִים בְּרָב חַסְדֶּךָ עֲנֵנִי בֶּאֱמֶת יִשְׁעֶךָ:"}]},{"id":"preparatory-prayers-adon-olam","heading":"Adon Olam","group":"Preparatory Prayers","lines":[{"he":"אֲדון עולָם אֲשֶׁר מָלַךְ. בְּטֶרֶם כָּל יְצִיר נִבְרָא:"},{"he":"לְעֵת נַעֲשה בְחֶפְצו כּל. אֲזַי מֶלֶךְ שְׁמו נִקְרָא:"},{"he":"וְאַחֲרֵי כִּכְלות הַכּל. לְבַדּו יִמְלךְ נורָא:"},{"he":"וְהוּא הָיָה. וְהוּא הוֶה. וְהוּא יִהְיֶה בְּתִפְאָרָה:"},{"he":"וְהוּא אֶחָד וְאֵין שֵׁנִי. לְהַמְשִׁיל לו לְהַחְבִּירָה:"},{"he":"בְּלִי רֵאשִׁית בְּלִי תַכְלִית. וְלו הָעז וְהַמִּשרָה:"},{"he":"וְהוּא אֵלִי וְחַי גואֲלִי. וְצוּר חֶבְלִי בְּעֵת צָרָה:"},{"he":"וְהוּא נִסִּי וּמָנוס לִי. מְנָת כּוסִי בְּיום אֶקְרָא:"},{"he":"בְּיָדו אַפְקִיד רוּחִי. בְּעֵת אִישָׁן וְאָעִירָה:"},{"he":"וְעִם רוּחִי גְּוִיָּתִי. ה' לִי וְלא אִירָא:"}]},{"id":"preparatory-prayers-yigdal","heading":"Yigdal","group":"Preparatory Prayers","lines":[{"he":"יִגְדַּל אֱלהִים חַי וְיִשְׁתַּבַּח, נִמְצָא וְאֵין עֵת אֶל מְצִיאוּתו. אֶחָד וְאֵין יָחִיד כְּיִחוּדו, נֶעְלָם וְגַם אֵין סוף לְאַחְדוּתו. אֵין לו דְמוּת הַגּוּף וְאֵינו גוּף, לא נַעֲרךְ אֵלָיו קְדֻשָּׁתו. קַדְמון לְכָל דָּבָר אֲשֶׁר נִבְרָא, רִאשׁון וְאֵין רֵאשִׁית לְרֵאשִׁיתו. הִנּו אֲדון עולָם לְכָל נוצָר, יורֶה גְדֻלָּתו וּמַלְכוּתו. שֶׁפַע נְבוּאָתו נְתָנו, אֶל אַנְשֵׁי סְגֻלָּתו וְתִפְאַרְתּו. לא קָם בְּיִשרָאֵל כְּמשֶׁה עוד, נָבִיא וּמַבִּיט אֶת תְּמוּנָתו. תּורַת אֱמֶת נָתַן לְעַמּו אֵל, עַל יַד נְבִיאו נֶאֱמַן בֵּיתו. לא יַחֲלִיף הָאֵל וְלא יָמִיר דָּתו, לְעולָמִים לְזוּלָתו. צופֶה וְיודֵעַ סְתָרֵינוּ, מַבִּיט לְסוף דָּבָר בְּקַדְמוּתו. גּומֵל לְאִישׁ חֶסֶד כְּמִפְעָלו, נותֵן לְרָשָׁע רַע כְּרִשְׁעָתו. יִשְׁלַח לְקֵץ הַיָּמִין מְשִׁיחֵנוּ, לִפְדּות מְחַכֵּי קֵץ יְשׁוּעָתו. מֵתִים יְחַיֶּה אֵל בְּרב חַסְדּו, בָּרוּךְ עֲדֵי עַד שֵׁם תְּהִלָּתו:"}]},{"id":"preparatory-prayers-morning-blessings","heading":"Morning Blessings","group":"Preparatory Prayers","lines":[{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. אֲשֶׁר נָתַן לַשּכְוִי בִינָה לְהַבְחִין בֵּין יום וּבֵין לָיְלָה:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. שֶׁלּא עָשנִי גּוי:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. שֶׁלּא עָשנִי עָבֶד:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. שֶׁלּא עָשנִי אִשָּׁה:"},{"he":"נשים מברכות - בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. שֶׁעָשנִי כִּרְצונו:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. פּוקֵחַ עִוְרִים:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. מַלְבִּישׁ עֲרֻמִּים:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. מַתִּיר אֲסוּרִים:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. זוקֵף כְּפוּפִים:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. רוקַע הָאָרֶץ עַל הַמָּיִם:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. הַמֵּכִין מִצְעֲדֵי גָבֶר:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. שֶׁעָשה לִּי כָּל צָרְכִּי:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. אוזֵר יִשרָאֵל בִּגְבוּרָה:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. עוטֵר יִשרָאֵל בְּתִפְאָרָה:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. הַנּותֵן לַיָּעֵף כּחַ:"},{"he":"אין לענות אמן אחר ותנומה מעפעפי כי הכל ברכה אחת עד לעמו ישראל דה\"ח:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. הַמַּעֲבִיר שֵׁנָה מֵעֵינָי וּתְנוּמָה מֵעַפְעַפָּי:"},{"he":"וִיהִי רָצון מִלְּפָנֶיךָ ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ שֶׁתַּרְגִּילֵנוּ בְּתורָתֶךָ. וְדַבְּקֵנוּ בְּמִצְותֶיךָ. וְאַל תְּבִיאֵנוּ לא לִידֵי חֵטְא. וְלא לִידֵי עֲבֵרָה וְעָון. וְלא לִידֵי נִסָּיון. וְלא לִידֵי בִזָּיון. וְאַל יִשְׁלט בָּנוּ יֵצֶר הָרָע. וְהַרְחִיקֵנוּ מֵאָדָם רָע וּמֵחָבֵר רָע. וְדַבְּקֵנוּ בְּיֵצֶר הַטוב וּבְמַעֲשים טובִים. וְכף אֶת יִצְרֵנוּ לְהִשְׁתַּעְבֶּד לָךְ. וּתְנֵנוּ הַיּום וּבְכָל יום לְחֵן וּלְחֶסֶד וּלְרַחֲמִים בְּעֵינֶיךָ וּבְעֵינֵי כָל רואֵינוּ. וְתִגְמְלֵנוּ חֲסָדִים טובִים."},{"he":"בָּרוּךְ אַתָּה ה' הַגּומֵל חֲסָדִים טובִים לְעַמּו יִשרָאֵל:"},{"he":"יְהִי רָצון מִלְּפָנֶיךָ ה' אֱלהַי וֵאלהֵי אֲבותַי שֶׁתַּצִּילֵנִי הַיּום וּבְכָל יום מֵעַזֵּי פָנִים וּמֵעַזּוּת פָּנִים. מֵאָדָם רָע. מִיֵּצֶר רָע. וּמֵחָבֵר רָע. וּמִשָּׁכֵן רָע. וּמִפֶּגַע רָע. מֵעַיִן הָרָע. מִלָּשׁון הָרָע. מִמַּלְשִׁינוּת. מֵעֵדוּת שֶׁקֶר. מִשּנְאַת הַבְּרִיּות. מֵעֲלִילָה. מִמִּיתָה מְשֻׁנָּה. מֵחֳלָיִם רָעִים. מִמִּקְרִים רָעִים וּמִשּטָן הַמַּשְׁחִית. מִדִּין קָשֶׁה וּמִבַּעַל דִּין קָשֶׁה. בֵּין שֶׁהוּא בֶן בְּרִית וּבֵין שֶׁאֵינו בֶן בְּרִית. וּמִדִּינָהּ שֶׁל גֵּיהִנּם:"}]},{"id":"preparatory-prayers-akedah","heading":"Akedah","group":"Preparatory Prayers","lines":[{"he":"וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וְהָאֱלהִים נִסָּה אֶת אַבְרָהָם וַיּאמֶר אֵלָיו אַבְרָהָם וַיּאמֶר הִנֵּנִי:"},{"he":"וַיּאמֶר קַח נָא אֶת בִּנְךָ אֶת יְחִידְךָ אֲשֶׁר אָהַבְתָּ אֶת יִצְחָק וְלֶךְ לְךָ אֶל אֶרֶץ הַמּרִיָּה וְהַעֲלֵהוּ שָׁם לְעלָה עַל אַחַד הֶהָרִים אֲשֶׁר אמַר אֵלֶיךָ:"},{"he":"וַיַּשְׁכֵּם אַבְרָהָם בַּבּקֶר וַיַּחֲבשׁ אֶת חֲמרו וַיִּקַּח אֶת שְׁנֵי נְעָרָיו אִתּו וְאֵת יִצְחָק בְּנו וַיְבַקַּע עֲצֵי עלָה וַיָּקָם וַיֵּלֶךְ אֶל הַמָּקום אֲשֶׁר אָמַר לו הָאֱלהִים:"},{"he":"בַּיּום הַשְּׁלִישִׁי וַיִּשּא אַבְרָהָם אֶת עֵינָיו וַיַּרְא אֶת הַמָּקום מֵרָחוק:"},{"he":"וַיּאמֶר אַבְרָהָם אֶל נְעָרָיו שְׁבוּ לָכֶם פּה עִם הַחֲמור וַאֲנִי וְהַנַּעַר נֵלְכָה עַד כּה וְנִשְׁתַּחֲוֶה וְנָשׁוּבָה אֲלֵיכֶם:"},{"he":"וַיִּקַּח אַבְרָהָם אֶת עֲצֵי הָעלָה וַיָּשם עַל יִצְחָק בְּנו וַיִּקַּח בְּיָדו אֶת הָאֵשׁ וְאֶת הַמַּאֲכֶלֶת וַיֵּלְכוּ שְׁנֵיהֶם יַחְדָּו:"},{"he":"וַיּאמֶר יִצְחָק אֶל אַבְרָהָם אָבִיו וַיּאמֶר אָבִי וַיּאמֶר הִנֶּנִּי בְנִי וַיּאמֶר הִנֵּה הָאֵשׁ וְהָעֵצִים וְאַיֵּה הַשּה לְעלָה:"},{"he":"וַיּאמֶר אַבְרָהָם אֱלהִים יִרְאֶה לּו הַשּה לְעלָה בְּנִי וַיֵּלְכוּ שְׁנֵיהֶם יַחְדָּו:"},{"he":"וַיָּבאוּ אֶל הַמָּקום אֲשֶׁר אָמַר לו הָאֱלהִים וַיִּבֶן שָׁם אַבְרָהָם אֶת הַמִּזְבֵּחַ וַיַּעֲרךְ אֶת הָעֵצִים וַיַּעֲקד אֶת יִצְחָק בְּנו וַיָּשם אתו עַל הַמִּזְבֵּחַ מִמַּעַל לָעֵצִים:"},{"he":"וַיִּשְׁלַח אַבְרָהָם אֶת יָדו וַיִּקַּח אֶת הַמַּאֲכֶלֶת לִשְׁחט אֶת בְּנו:"},{"he":"וַיִּקְרָא אֵלָיו מַלְאַךְ ה' מִן הַשָּׁמַיִם וַיּאמֶר אַבְרָהָם אַבְרָהָם וַיּאמֶר הִנֵּנִי:"},{"he":"וַיּאמֶר אַל תִּשְׁלַח יָדְךָ אֶל הַנַּעַר וְאַל תַּעַש לו מְאוּמָה כִּי עַתָּה יָדַעְתִּי כִּי יְרֵא אֱלהִים אַתָּה וְלא חָשכְתָּ אֶת בִּנְךָ אֶת יְחִידְךָ מִמֶּנִּי:"},{"he":"וַיִּשּא אַבְרָהָם אֶת עֵינָיו וַיַּרְא וְהִנֵּה אַיִל אַחַר נֶאֱחַז בַּסְּבַךְ בְּקַרְנָיו וַיֵּלֶךְ אַבְרָהָם וַיִּקַּח אֶת הָאַיִל וַיַּעֲלֵהוּ לְעלָה תַּחַת בְּנו:"},{"he":"וַיִּקְרָא אַבְרָהָם שֵׁם הַמָּקום הַהוּא ה' יִרְאֶה אֲשֶׁר יֵאָמֵר הַיּום בְּהַר ה' יֵרָאֶה:"},{"he":"וַיִּקְרָא מַלְאַךְ ה' אֶל אַבְרָהָם שֵׁנִית מִן הַשָּׁמָיִם:"},{"he":"וַיּאמֶר בִּי נִשְׁבַּעְתִּי נְאֻם ה' כִּי יַעַן אֲשֶׁר עָשיתָ אֶת הַדָּבָר הַזֶּה וְלא חָשכְתָּ אֶת בִּנְךָ אֶת יְחִידֶךָ:"},{"he":"כִּי בָרֵךְ אֲבָרֶכְךָ וְהַרְבָּה אַרְבֶּה אֶת זַרְעֲךָ כְּכוכְבֵי הַשָּׁמַיִם וְכַחול אֲשֶׁר עַל שפַת הַיָּם וְיִרַשׁ זַרְעֲךָ אֵת שַׁעַר איְבָיו:"},{"he":"וְהִתְבָּרֲכוּ בְזַרְעֲךָ כּל גּויֵי הָאָרֶץ עֵקֶב אֲשֶׁר שָׁמַעְתָּ בְּקלִי:"},{"he":"וַיָּשָׁב אַבְרָהָם אֶל נְעָרָיו וַיָּקֻמוּ וַיֵּלְכוּ יַחְדָּו אֶל בְּאֵר שָׁבַע וַיֵּשֶׁב אַבְרָהָם בִּבְאֵר שָׁבַע:"}]},{"id":"preparatory-prayers-sovereignty-of-heaven","heading":"Sovereignty of Heaven","group":"Preparatory Prayers","lines":[{"he":"לְעולָם יְהֵא אָדָם יְרֵא שָׁמַיִם בַּסֵּתֶר וּבַגָּלוּי וּמודֶה עַל הָאֱמֶת וְדובֵר אֱמֶת בִּלְבָבו וְיַשְׁכֵּם וְיאמַר:"},{"he":"רִבּון כָּל הָעולָמִים וַאֲדונֵי הָאֲדונִים. לא עַל צִדְקותֵינוּ אֲנַחְנוּ מַפִּילִים תַּחֲנוּנֵינוּ לְפָנֶיךָ כִּי עַל רַחֲמֶיךָ הָרַבִּים. מָה אָנוּ מֶה חַיֵּינוּ מֶה חַסְדֵּנוּ מַה צִּדְקותֵינוּ מַה יְשׁוּעָתֵנוּ מַה כּחֵנוּ מַה גְּבוּרָתֵנוּ. מַה נּאמַר לְפָנֶיךָ ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ הֲלא כָל הַגִּבּורִים כְּאַיִן לְפָנֶיךָ וְאַנְשֵׁי הַשֵּׁם כְּלא הָיוּ וַחֲכָמִים כִּבְלִי מַדָּע וּנְבונִים כִּבְלִי הַשכֵּל כִּי רוב מַעֲשיהֶם תּהוּ וִימֵי חַיֵּיהֶם הֶבֶל לְפָנֶיךָ. וּמותַר הָאָדָם מִן הַבְּהֵמָה אָיִן כִּי הַכּל הָבֶל:"},{"he":"לְבַד הַנְּשָׁמָה הַטְּהורָה שֶׁהִיא עֲתִידָה לִתֵּן דִּין וְחֶשְׁבּון לִפְנֵי כִסֵּא כְבודֶךָ:"},{"he":"וְכָל הַגּויִם כְּאַיִן נֶגְדֶּךָ. שֶׁנֶּאֱמַר הֵן גּויִם כְּמַר מִדְּלִי וּכְשַׁחַק מאזְנַיִם נֶחְשָׁבוּ הֵן אִיִּים כַּדַּק יִטּל:"},{"he":"אֲבָל אֲנַחְנוּ עַמְּךָ בְּנֵי בְרִיתֶךָ. בְּנֵי אַבְרָהָם אהַבְךָ שֶׁנִּשְׁבַּעְתָּ לּו בְּהַר הַמּורִיָּה. זֶרַע יִצְחָק יְחִידו. שֶׁנֶּעֱקַד עַל גַּבֵּי הַמִּזְבֵּחַ. עֲדַת יַעֲקב בִּנְךָ בְּכורֶךָ. שֶׁמֵּאַהֲבָתְךָ שֶׁאָהַבְתָּ אותו וּמִשּמְחָתְךָ שֶׁשּמַחְתָּ בּו. קָרָאתָ אֶת שְׁמו יִשרָאֵל וִישֻׁרוּן:"},{"he":"לְפִיכָךְ אֲנַחְנוּ חַיָּבִים לְהודות לְךָ וּלְשַׁבֵּחֲךָ וּלְפָאֶרְךָ וּלְבָרֵךְ וּלְקַדֵּשׁ וְלִתֵּן שֶׁבַח וְהודָיָה לִשְׁמֶךָ:"},{"he":"אַשְׁרֵינוּ מַה טּוב חֶלְקֵנוּ וּמַה נָּעִים גּורָלֵנוּ וּמַה יָּפָה יְרֻשָּׁתֵנוּ:"},{"he":"אַשְׁרֵינוּ כְּשֶׁאָנוּ מַשְׁכִּימִים וּמַעֲרִיבִים בְּבָתֵּי כְנֵסִיּות וּבְבָתֵּי מִדְרָשׁות וּמְיַחֲדִים שִׁמְךָ בְּכָל יום תָּמִיד וְאומְרִים פַּעֲמַיִם בְּאַהֲבָה:"},{"he":"שְׁמַע יִשרָאֵל ה' אֱלהֵינוּ ה' אֶחָד:"},{"he":"בלחש - בָּרוּךְ שֵׁם כְּבוד מַלְכוּתו לְעולָם וָעֶד:"},{"he":"וְאָהַבְתָּ אֵת ה' אֱלהֶיךָ בְּכָל לְבָבְךָ וּבְכָל נַפְשְׁךָ וּבְכָל מְאדֶךָ:"},{"he":"וְהָיוּ הַדְּבָרִים הָאֵלֶּה אֲשֶׁר אָנכִי מְצַוְּךָ הַיּום עַל לְבָבֶךָ:"},{"he":"וְשִׁנַּנְתָּם לְבָנֶיךָ וְדִבַּרְתָּ בָּם בְּשִׁבְתְּךָ בְּבֵיתֶךָ וּבְלֶכְתְּךָ בַדֶּרֶךְ וּבְשָׁכְבְּךָ וּבְקוּמֶךָ:"},{"he":"וּקְשַׁרְתָּם לְאות עַל יָדֶךָ וְהָיוּ לְטטָפת בֵּין עֵינֶיךָ:"},{"he":"וּכְתַבְתָּם עַל מְזֻזות בֵּיתֶךָ וּבִשְׁעָרֶיךָ:"},{"he":"אַתָּה הוּא עַד שֶׁלּא נִבְרָא הָעולָם אַתָּה הוּא מִשֶּׁנִּבְרָא הָעולָם. אַתָּה הוּא בָּעולָם הַזֶּה וְאַתָּה הוּא לָעולָם הַבָּא:"},{"he":"קַדֵּשׁ אֶת שִׁמְךָ עַל מַקְדִּישֵׁי שְׁמֶךָ וְקַדֵּשׁ אֶת שִׁמְךָ בְּעולָמֶךָ. וּבִישׁוּעָתְךָ תָּרִים וְתַגְבִּיהַּ קַרְנֵנוּ לְמַעְלָה. וְהושִׁיעֵנוּ בְּקָרוב לְמַעַן שְׁמֶךָ:"},{"he":"בָּרוּךְ הַמְקַדֵּשׁ שְׁמו בָּרַבִּים:"},{"he":"אַתָּה הוּא ה' אֱלהֵינוּ בַּשָּׁמַיִם וּבָאָרֶץ וּבִשְׁמֵי הַשָּׁמַיִם הָעֶלְיונִים. אֱמֶת אַתָּה הוּא רִאשׁון וְאַתָּה הוּא אַחֲרון וּמִבַּלְעָדֶיךָ אֵין אֱלהִים:"},{"he":"קַבֵּץ נְפוּצות קוֶיךָ מֵאַרְבַּע כַּנְפות הָאָרֶץ. יַכִּירוּ וְיֵדְעוּ כָּל בָּאֵי עולָם כִּי אַתָּה הוּא הָאֱלהִים לְבַדְּךָ עֶלְיון לְכל מַמְלְכות הָאָרֶץ:"},{"he":"אַתָּה עָשיתָ אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ אֶת הַיָּם וְאֶת כָּל אֲשֶׁר בָּם וּמִי בְּכָל מַעֲשה יָדֶיךָ בָּעֶלְיונִים או בַתַּחְתּונִים שֶׁיּאמַר לְךָ מַה תַּעֲשה וּמַה תִּפְעָל:"},{"he":"אָבִינוּ שֶׁבַּשָּׁמַיִם חַי וְקַיָּם עֲשה עִמָּנוּ צְדָקָה וָחֶסֶד בַּעֲבוּר שִׁמְךָ הַגָּדול הַגִּבּור וְהַנּורָא שֶׁנִּקְרָא עָלֵינוּ. וְקַיֶּם לָנוּ ה' אֱלהֵינוּ מַה שֶׁכָּתוּב אֶת הַדָּבָר שֶׁהִבְטַחְתָּנוּ עַל יְדֵי צְפַנְיָה חוזָךְ. כָּאָמוּר בָּעֵת הַהִיא אָבִיא אֶתְכֶם וּבָעֵת קַבְּצִי אֶתְכֶם. כִּי אֶתֵּן אֶתְכֶם לְשֵׁם וְלִתְהִלָּה בְּכל עַמֵּי הָאָרֶץ. בְּשׁוּבִי אֶת שְׁבוּתֵיכֶם לְעֵינֵיכֶם. אָמַר ה':"}]},{"id":"preparatory-prayers-korbanot-kiyor","heading":"Kiyor","group":"Preparatory Prayers · Korbanot","lines":[{"he":"וַיְדַבֵּר ה' אֶל משֶׁה לֵּאמר:"},{"he":"וְעָשיתָ כִּיּור נְחשֶׁת וְכַנּו נְחשֶׁת לְרָחְצָה. וְנָתַתָּ אתו בֵּין אהֶל מועֵד וּבֵין הַמִּזְבֵּחַ. וְנָתַתָּ שָׁמָּה מָיִם:"},{"he":"וְרָחֲצוּ אַהֲרן וּבָנָיו מִמֶּנּוּ אֶת יְדֵיהֶם וְאֶת רַגְלֵיהֶם:"},{"he":"בְּבאָם אֶל אהֶל מועֵד יִרְחֲצוּ מַיִם וְלא יָמֻתוּ. או בְגִשְׁתָּם אֶל הַמִּזְבֵּחַ לְשָׁרֵת. לְהַקְטִיר אִשֶּׁה לה':"},{"he":"וְרָחֲצוּ יְדֵיהֶם וְרַגְלֵיהֶם וְלא יָמֻתוּ. וְהָיְתָה לָהֶם חָק עולָם. לו וּלְזַרְעו לְדרתָם:"}]},{"id":"preparatory-prayers-korbanot-terumat-hadeshen","heading":"Terumat HaDeshen","group":"Preparatory Prayers · Korbanot","lines":[{"he":"וַיְדַבֵּר ה' אֶל משֶׁה לֵּאמר:"},{"he":"צַו אֶת אַהֲרן וְאֶת בָּנָיו לֵאמר זאת תּורַת הָעלָה הִוא הָעלָה עַל מוקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה עַד הַבּקֶר וְאֵשׁ הַמִּזְבֵּחַ תּוּקַד בּו:"},{"he":"וְלָבַשׁ הַכּהֵן מִדּו בַד וּמִכְנְסֵי בַד יִלְבַּשׁ עַל בְּשרו וְהֵרִים אֶת הַדֶּשֶׁן אֲשֶׁר תּאכַל הָאֵשׁ אֶת הָעלָה עַל הַמִּזְבֵּחַ וְשמו אֵצֶל הַמִּזְבֵּחַ:"},{"he":"וּפָשַׁט אֶת בְּגָדָיו וְלָבַשׁ בְּגָדִים אֲחֵרִים וְהוצִיא אֶת הַדֶּשֶׁן אֶל מִחוּץ לַמַּחֲנֶה אֶל מָקום טָהור:"},{"he":"וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּו לא תִכְבֶּה וּבִעֵר עָלֶיהָ הַכּהֵן עֵצִים בַּבּקֶר בַּבּקֶר וְעָרַךְ עָלֶיהָ הָעלָה וְהִקְטִיר עָלֶיהָ חֶלְבֵי הַשְּׁלָמִים:"},{"he":"אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לא תִכְבֶּה:"}]},{"id":"preparatory-prayers-korbanot-korban-hatamid","heading":"Korban HaTamid","group":"Preparatory Prayers · Korbanot","lines":[{"he":"וַיְדַבֵּר ה' אֶל משֶׁה לֵּאמר:"},{"he":"צַו אֶת בְּנֵי יִשרָאֵל וְאָמַרְתָּ אֲלֵהֶם. אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי רֵיחַ נִיחחִי. תִּשְׁמְרוּ לְהַקְרִיב לִי"},{"he":"בְּמועֲדו: וְאָמַרְתָּ לָהֶם. זֶה הָאִשֶּׁה אֲשֶׁר תַּקְרִיבוּ לה'. כְּבָשים בְּנֵי שָׁנָה תְמִימִים. שְׁנַיִם לַיּום עלָה תָמִיד: אֶת הַכֶּבֶש אֶחָד תַּעֲשה בַבּקֶר. וְאֵת הַכֶּבֶש הַשֵּׁנִי תַּעֲשה בֵּין הָעַרְבָּיִם:"},{"he":"וַעֲשירִית הָאֵיפָה סלֶת לְמִנְחָה. בְּלוּלָה בְּשֶׁמֶן כָּתִית רְבִיעִת הַהִין:"},{"he":"עלַת תָּמִיד הָעֲשיָה בְּהַר סִינַי. לְרֵיחַ נִיחחַ אִשֶּׁה לה':"},{"he":"וְנִסְכּו רְבִיעִת הַהִין לַכֶּבֶש הָאֶחָד. בַּקּדֶשׁ הַסֵּךְ נֶסֶךְ שֵׁכָר לה':"},{"he":"וְאֵת הַכֶּבֶש הַשֵּׁנִי תַּעֲשה בֵּין הָעַרְבָּיִם. כְּמִנְחַת הַבּקֶר וּכְנִסְכּו תַּעֲשה. אִשֵּׁה רֵיחַ נִיחחַ לה':"},{"he":"וְשָׁחַט אתו עַל יֶרֶךְ הַמִּזְבֵּחַ צָפנָה לִפְנֵי ה'. וְזָרְקוּ בְּנֵי אַהֲרן הַכּהֲנִים אֶת דָּמו עַל הַמִּזְבֵּחַ סָבִיב:"},{"he":"יְהִי רָצון מִלְּפָנֶיךָ, ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ, שֶׁתְּהֵא אֲמִירָה זוּ חֲשׁוּבָה וּמְקֻבֶּלֶת וּמְרֻצָּה לְפָנֶיךָ כְּאִלּוּ הִקְרַבְנוּ קָרְבַּן הַתָּמִיד בְּמועֲדו וּבִמְקומו וּכְהִלְכָתו:"}]},{"id":"preparatory-prayers-korbanot-ketoret","heading":"Ketoret","group":"Preparatory Prayers · Korbanot","lines":[{"he":"אַתָּה הוּא ה' אֱלהֵינוּ שֶׁהִקְטִירוּ אֲבותֵינוּ לְפָנֶיךָ אֶת קְטרֶת הַסַּמִּים בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ הָיָה קַיָּם. כַּאֲשֶׁר צִוִּיתָ אותָם עַל יַד משֶׁה נְבִיאֶךָ כַּכָּתוּב בְּתורָתֶךָ:"},{"he":"וַיּאמֶר ה' אֶל משֶׁה קַח לְךָ סַמִּים נָטָף וּשְׁחֵלֶת וְחֶלְבְּנָה סַמִּים וּלְבנָה זַכָּה בַּד בְּבַד יִהְיֶה:"},{"he":"וְעָשיתָ אתָהּ קְטרֶת רקַח מַעֲשה רוקֵחַ מְמֻלָּח טָהור קדֶשׁ:"},{"he":"וְשָׁחַקְתָּ מִמֶּנָּה הָדֵק וְנָתַתָּה מִמֶּנָּה לִפְנֵי הָעֵדֻת בְּאהֶל מועֵד אֲשֶׁר אִוָּעֵד לְךָ שָׁמָּה קדֶשׁ קָדָשִׁים תִּהְיֶה לָכֶם:"},{"he":"וְנֶאֱמַר וְהִקְטִיר עָלָיו אַהֲרן קְטרֶת סַמִּים בַּבּקֶר בַּבּקֶר בְּהֵיטִיבו אֶת הַנֵּרות יַקְטִירֶנָּה:"},{"he":"וּבְהַעֲלת אַהֲרן אֶת הַנֵּרות בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה קְטרֶת תָּמִיד לִפְנֵי ה' לְדרתֵיכֶם:"},{"he":"תָּנוּ רַבָּנָן פִּטּוּם הַקְּטרֶת כֵּיצַד שְׁלשׁ מֵאות וְשִׁשִּׁים וּשְׁמונָה מָנִים הָיוּ בָהּ. שְׁלשׁ מֵאות וְשִׁשִּׁים וַחֲמִשָּׁה כְּמִנְיַן יְמות הַחַמָּה. מָנֶה לְכָל יום. פְּרַס בְּשַׁחֲרִית וּפְרַס בֵּין הָעַרְבָּיִם. וּשְׁלשָׁה מָנִים יְתֵרִים שֶׁמֵּהֶם מַכְנִיס כּהֵן גָּדול מְלא חָפְנָיו בְּיום הַכִּפּוּרִים. וּמַחֲזִירָן לְמַכְתֶּשֶׁת בְּעֶרֶב יום הַכִּפּוּרִים. וְשׁוחֲקָן יָפֶה יָפֶה כְּדֵי שֶׁתְּהֵא דַקָּה מִן הַדַּקָּה:"},{"he":"וְאַחַד עָשר סַמָּנִים הָיוּ בָהּ. וְאֵלּוּ הֵן."},{"he":"א הַצֳּרִי ב וְהַצִּפּרֶן ג הַחֶלְבְּנָה ד וְהַלְּבונָה מִשְׁקַל שִׁבְעִים שִׁבְעִים מָנֶה. ה מר ו וּקְצִיעָה ז שִׁבּלֶת נֵרְדְּ ח וְכַרְכּם מִשְׁקַל שִׁשָּׁה עָשר שִׁשָּׁה עָשר מָנֶה. ט הַקּשְׁטְ שְׁנֵים עָשר. י וְקִלּוּפָה שְׁלשָׁה. יא וְקִנָּמון תִּשְׁעָה.","note":true},{"he":"בּורִית כַּרְשִׁינָה תִּשְׁעָה קַבִּין. יֵין קַפְרִיסִין סְאִין תְּלָתָא וְקַבִּין תְּלָתָא. וְאִם לא מָצָא יֵין קַפְרִיסִין מֵבִיא חֲמַר חִוַּרְיָן עַתִּיק. מֶלַח סְדומִית רובַע מַעֲלֶה עָשָׁן כָּל שֶׁהוּא. רַבִּי נָתָן הַבַּבְלִי אומֵר אַף כִּפַּת הַיַּרְדֵּן כָּל שֶׁהוּא וְאִם נָתַן בָּהּ דְּבַשׁ פְּסָלָהּ. וְאִם חִסַּר אַחַת מִכָּל סַמָּנֶיהָ חַיָּב מִיתָה:"},{"he":"רַבָּן שִׁמְעון בֶּן גַּמְלִיאֵל אומֵר הַצֳּרִי אֵינו אֶלָּא שרָף הַנּוטֵף מֵעֲצֵי הַקְּטָף. בּרִית כַּרְשִׁינָה לָמָה הִיא בָאָה, כְּדֵי לְיַפּות בָּהּ אֶת הַצִּפּרֶן כְּדֵי שֶׁתְּהֵא נָאָה. יֵין קַפְרִיסִין לָמָה הוּא בָא כְּדֵי לִשְׁרות בּו אֶת הַצִּפּרֶן כְּדֵי שֶׁתְּהֵא עַזָּה. וַהֲלא מֵי רַגְלַיִם יָפִין לָהּ אֶלָּא שֶׁאֵין מַכְנִיסִין מֵי רַגְלַיִם בַּמִּקְדָּשׁ מִפְּנֵי הַכָּבוד:"},{"he":"תַּנְיָא רַבִּי נָתָן אומֵר כְּשֶׁהוּא שׁוחֵק אומֵר. הָדֵק הֵיטֵב הֵיטֵב הָדֵק. מִפְּנֵי שֶׁהַקּול יָפֶה לַבְּשמִים. פִּטְּמָהּ לַחֲצָאִין כְּשֵׁרָה. לִשְׁלִישׁ וְלִרְבִיעַ לא שָׁמַעְנוּ:"},{"he":"אָמַר רַבִּי יְהוּדָה זֶה הַכְּלָל. אִם כְּמִדָּתָהּ כְּשֵׁרָה לַחֲצָאִין. וְאִם חִסַּר אַחַת מִכָּל סַמָּנֶיהָ חַיָּב מִיתָה:"},{"he":"תַּנְיָא בַּר קַפָּרָא אומֵר. אַחַת לְשִׁשִּׁים או לְשִׁבְעִים שָׁנָה הָיְתָה בָאָה שֶׁל שִׁירַיִם לַחֲצָאִין:"},{"he":"וְעוד תָּנֵי בַּר קַפָּרָא אִלּוּ הָיָה נותֵן בָּהּ קורְטוב שֶׁל דְּבַשׁ אֵין אָדָם יָכול לַעֲמד מִפְּנֵי רֵיחָהּ. וְלָמָה אֵין מְעָרְבִין בָּהּ דְּבַשׁ. מִפְּנֵי שֶׁהַתּורָה אָמְרָה כִּי כָל שאר וְכָל דְּבַשׁ לא תַקְטִירוּ מִמֶּנּוּ אִשֶּׁה לה':"},{"he":"ג\"פ - ה' צְבָאות עִמָּנוּ מִשגָּב לָנוּ אֱלהֵי יַעֲקב סֶלָה:"},{"he":"ג\"פ - ה' צְבָאות אַשְׁרֵי אָדָם בּוטֵחַ בָּךְ:"},{"he":"ג\"פ - ה' הושִׁיעָה הַמֶּלֶךְ יַעֲנֵנוּ בְיום קָרְאֵנוּ:"},{"he":"אַתָּה סֵתֶר לִי מִצַּר תִּצְּרֵנִי רָנֵּי פַלֵּט תְּסובְבֵנִי סֶלָה:"},{"he":"וְעָרְבָה לה' מִנְחַת יְהוּדָה וִירוּשָׁלָיִם כִּימֵי עולָם וּכְשָׁנִים קַדְמונִיּות:"},{"he":"אַבַּיֵּי הֲוָה מְסַדֵּר סֵדֶר הַמַּעֲרָכָה מִשְּׁמָא דִּגְמָרָא וְאַלִּבָּא דְאַבָּא שָׁאוּל. מַעֲרָכָה גְדולָה קודֶמֶת לְמַעֲרָכָה שְׁנִיָּה שֶׁל קְטרֶת. וּמַעֲרָכָה שְׁנִיָּה שֶׁל קְטרֶת קודֶמֶת לְסִדּוּר שְׁנֵי גִזְרֵי עֵצִים. וְסִדּוּר שְׁנֵי גִזְרֵי עֵצִים קודֶם לְדִשּׁוּן מִזְבֵּחַ הַפְּנִימִי. וְדִשּׁוּן מִזְבֵּחַ הַפְּנִימִי קודֶם לַהֲטָבַת חָמֵשׁ נֵרות. וַהֲטָבַת חָמֵשׁ נֵרות קודֶמֶת לְדַם הַתָּמִיד. וְדַם הַתָּמִיד קודֶם לַהֲטָבַת שְׁתֵּי נֵרות. וַהֲטָבַת שְׁתֵּי נֵרות קודֶמֶת לִקְטרֶת. וּקְטרֶת קודֶמֶת לְאֵבָרִים. וְאֵבָרִים לְמִנְחָה. וּמִנְחָה לַחֲבִתִּין. וַחֲבִתִּין לִנְסָכִין. וּנְסָכִין לְמוּסָפִין. וּמוּסָפִין לְבָזִיכִין. וּבָזִיכִין קודְמִין לְתָמִיד שֶׁל בֵּין הָעַרְבָּיִם. שֶׁנֶּאֱמַר. וְעָרַךְ עָלֶיהָ הָעלָה וְהִקְטִיר עָלֶיהָ חֶלְבֵי הַשְּׁלָמִים. עָלֶיהָ הַשְׁלֵם כָּל הַקָּרְבָּנות כֻּלָּם:"}]},{"id":"preparatory-prayers-korbanot-baraita-of-rabbi-yishmael","heading":"Baraita of Rabbi Yishmael","group":"Preparatory Prayers · Korbanot","lines":[{"he":"רַבִּי יִשְׁמָעֵאל אומֵר. בִּשְׁלשׁ עֶשרֵה מִדּות הַתּורָה נִדְרֶשֶׁת בָּהֵן:"},{"he":"א מִקַּל וָחמֶר","note":true},{"he":"ב וּמִגְּזֵרָה שָׁוָה.","note":true},{"he":"ג מִבִּנְיַן אָב מִכָּתוּב אֶחָד. וּמִבִּנְיַן אָב מִשְּׁנֵי כְתוּבִים.","note":true},{"he":"ד מִכְּלָל וּפְרָט.","note":true},{"he":"ה וּמִפְּרָט וּכְלָל.","note":true},{"he":"ו כְּלָל וּפְרָט וּכְלָל. אִי אַתָּה דָן אֶלָּא כְּעֵין הַפְּרָט.","note":true},{"he":"ז מִכְּלָל שֶׁהוּא צָרִיךְ לִפְרָט. וּמִפְּרָט שֶׁהוּא צָרִיךְ לִכְלָל.","note":true},{"he":"ח כָּל דָּבָר שֶׁהָיָה בִּכְלָל וְיָצָא מִן הַכְּלָל לְלַמֵּד. לא לְלַמֵּד עַל עַצְמו יָצָא. אֶלָּא לְלַמֵּד עַל הַכְּלָל כֻּלּו יָצָא.","note":true},{"he":"ט כָּל דָּבָר שֶׁהָיָה בִּכְלָל וְיָצָא לִטְעון טועַן אֶחָד שֶׁהוּא כְעִנְיָנו. יָצָא לְהָקֵל וְלא לְהַחֲמִיר.","note":true},{"he":"י כָּל דָּבָר שֶׁהָיָה בִּכְלָל וְיָצָא לִטְעון טועַן אַחֵר שֶׁלּא כְעִנְיָנו. יָצָא לְהָקֵל וּלְהַחֲמִיר.","note":true},{"he":"יא כָּל דָּבָר שֶׁהָיָה בִּכְלָל וְיָצָא לִדּון בַּדָּבָר הֶחָדָשׁ. אִי אַתָּה יָכול לְהַחֲזִירו לִכְלָלו עַד שֶׁיַּחֲזִירֶנּוּ הַכָּתוּב לִכְלָלו בְּפֵרוּשׁ.","note":true},{"he":"יב דָּבָר הַלָּמֵד מֵעִנְיָנו. וְדָבָר הַלָּמֵד מִסּופו.","note":true},{"he":"יג וְכֵן נ\"א וְכַאן שְׁנֵי כְתוּבִים הַמַּכְחִישִׁים זֶה אֶת זֶה. עַד שֶׁיָּבוא הַכָּתוּב הַשְּׁלִישִׁי וְיַכְרִיעַ בֵּינֵיהֶם:","note":true},{"he":"יְהִי רָצון מִלְּפָנֶיךָ ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ בִּמְהֵרָה בְיָמֵינוּ. וְתֵן חֶלְקֵנוּ בְּתורָתֶךָ: וְשָׁם נַעֲבָדְךָ בְּיִרְאָה כִּימֵי עולָם וּכְשָׁנִים קַדְמונִיּות:"}]},{"id":"preparatory-prayers-korbanot-kaddish-derabbanan","heading":"Kaddish DeRabbanan","group":"Preparatory Prayers · Korbanot","lines":[{"he":"יִתְגַּדַּל וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. אמן:"},{"he":"בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵהּ וְיַצְמַח פֻּרְקָנֵהּ וִיקָרֵב מְשִׁיחֵהּ. אמן:"},{"he":"בְּחַיֵּיכון וּבְיומֵיכון וּבְחַיֵּי דְכָל בֵּית יִשרָאֵל בַּעֲגָלָא וּבִזְמַן קָרִיב. וְאִמְרוּ אָמֵן:"},{"he":"יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא:"},{"he":"יִתְבָּרַךְ. וְיִשְׁתַּבַּח וְיִתְפָּאֵר וְיִתְרומֵם וְיִתְנַשּא וְיִתְהַדָּר וְיִתְעַלֶּה וְיִתְהַלָּל שְׁמֵהּ דְקֻדְשָׁא בְּרִיךְ הוּא. לְעֵלָּא מִן כָּל בעשי\"ת וּלְעֵלָּא מִכָּל בִּרְכָתָא וְשִׁירָתָא תֻּשְׁבְּחָתָא וְנֶחֱמָתָא דַּאֲמִירָן בְּעָלְמָא. וְאִמְרוּ אָמֵן:"},{"he":"עַל יִשרָאֵל וְעַל רַבָּנָן. וְעַל תַּלְמִידֵיהון וְעַל כָּל תַּלְמִידֵי תַלְמִידֵיהון. וְעַל כָּל מַאן דְּעָסְקִין בְּאורַיְתָא. דִּי בְאַתְרָא קַדִּישָׁא הָדֵין וְדִי בְכָל אֲתַר וַאֲתַר. יְהֵא לְהון וּלְכון שְׁלָמָא רַבָּא חִנָּא וְחִסְדָּא וְרַחֲמֵי וְחַיֵּי אֲרִיכֵי וּמְזונֵי רְוִיחֵי וּפֻרְקָנָא מִן קֳדָם אֲבוּהון דִּי בִשְׁמַיָּא וְאַרְעָא וְאִמְרוּ אָמֵן:"},{"he":"יְהֵא שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טובִים עָלֵינוּ וְעַל כָּל יִשרָאֵל. וְאִמְרוּ אָמֵן:"},{"he":"עושה שָׁלום בעשי\"ת הַשָּׁלום בִּמְרומָיו הוּא בְּרַחֲמָיו יַעֲשה שָׁלום עָלֵינוּ וְעַל כָּל יִשרָאֵל וְאִמְרוּ אָמֵן:"}]},{"id":"pesukei-dezimra-mizmor-shir","heading":"Mizmor Shir","group":"Pesukei Dezimra","lines":[{"he":"מִזְמור שִׁיר חֲנֻכַּת הַבַּיִת לְדָוִד: אֲרומִמְךָ ה' כִּי דִלִּיתָנִי. וְלא שמַּחְתָּ איְבַי לִי: ה' אֱלהָי. שִׁוַּעְתִּי אֵלֶיךָ וַתִּרְפָּאֵנִי: ה' הֶעֱלִיתָ מִן שְׁאול נַפְשִׁי. חִיִּיתַנִי מִיָּרְדִי בור: זַמְּרוּ לה' חֲסִידָיו. וְהודוּ לְזֵכֶר קָדְשׁו: כִּי רֶגַע בְּאַפּו חַיִּים בִּרְצונו. בָּעֶרֶב יָלִין בֶּכִי וְלַבּקֶר רִנָּה: וַאֲנִי אָמַרְתִּי בְשַׁלְוִי. בַּל אֶמּוט לְעולָם: ה' בִּרְצונְךָ הֶעֱמַדְתָּה לְהַרְרִי עז. הִסְתַּרְתָּ פָנֶיךָ הָיִיתִי נִבְהָל: אֵלֶיךָ ה' אֶקְרָא וְאֶל אֲדנָי אֶתְחַנָּן: מַה בֶּצַע בְּדָמִי בְּרִדְתִּי אֶל שָׁחַת. הֲיודְךָ עָפָר הֲיַגִּיד אֲמִתֶּךָ: שְׁמַע ה' וְחָנֵּנִי ה' הֱיֵה עזֵר לִי: הָפַכְתָּ מִסְפְּדִי לְמָחול לִי פִּתַּחְתָּ שקִּי וַתְּאַזְּרֵנִי שמְחָה: לְמַעַן יְזַמֶּרְךָ כָבוד וְלא יִדּם. ה' אֱלהַי לְעולָם אודֶךָּ:"}]},{"id":"pesukei-dezimra-mourner-s-kaddish","heading":"Mourner's Kaddish","group":"Pesukei Dezimra","lines":[{"he":"קדיש יתום: אבל: יִתְגַּדַּל וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. [קהל: אמן] בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵהּ בְּחַיֵּיכון וּבְיומֵיכון וּבְחַיֵּי דְכָל בֵּית יִשרָאֵל בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן: [קהל: אמן] קהל ואבל: יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא: אבל: יִתְבָּרַךְ וְיִשְׁתַּבַּח וְיִתְפָּאַר וְיִתְרומַם וְיִתְנַשּא וְיִתְהַדָּר וְיִתְעַלֶּה וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא. בְּרִיךְ הוּא. [קהל: בריך הוא:] לְעֵלָּא מִן כָּל בִּרְכָתָא בעשי”ת: לְעֵלָּא לְעֵלָּא מִכָּל וְשִׁירָתָא תֻּשְׁבְּחָתָא וְנֶחֱמָתָא דַּאֲמִירָן בְּעָלְמָא. וְאִמְרוּ אָמֵן: [קהל: אמן] יְהֵא שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים עָלֵינוּ וְעַל כָּל יִשרָאֵל. וְאִמְרוּ אָמֵן: [קהל: אמן] עושה שָׁלום בעשי”ת: הַשָּׁלום בִּמְרומָיו הוּא יַעֲשה שָׁלום עָלֵינוּ וְעַל כָּל יִשרָאֵל וְאִמְרוּ אָמֵן: [קהל: אמן]","note":true}]},{"id":"pesukei-dezimra-barukh-she-amar","heading":"Barukh She'amar","group":"Pesukei Dezimra","lines":[{"he":"בָּרוּךְ שֶׁאָמַר וְהָיָה הָעולָם. בָּרוּךְ הוּא. בָּרוּךְ עושה בְרֵאשִׁית. בָּרוּךְ אומֵר וְעושה. בָּרוּךְ גּוזֵר וּמְקַיֵּם. בָּרוּךְ מְרַחֵם עַל הָאָרֶץ. בָּרוּךְ מְרַחֵם עַל הַבְּרִיּות. בָּרוּךְ מְשַׁלֵּם שכָר טוב לִירֵאָיו. בָּרוּךְ חַי לָעַד וְקַיָּם לָנֶצַח. בָּרוּךְ פּודֶה וּמַצִּיל. בָּרוּךְ שְׁמו:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. הָאֵל, הָאָב הָרַחֲמָן הַמְהֻלָּל בְּפִי עַמּו. מְשֻׁבָּח וּמְפאָר בִּלְשׁון חֲסִידָיו וַעֲבָדָיו. וּבְשִׁירֵי דָוִד עַבְדֶּךָ. נְהַלֶּלְךָ ה' אֱלהֵינוּ בִּשְׁבָחות וּבִזְמִרות. וּנְגַדֶּלְךָ וּנְשַׁבֵּחֲךָ וּנְפָאֶרְךָ, וְנַזְכִּיר שִׁמְךָ מַלְכֵּנוּ אֱלהֵינוּ. יָחִיד חֵי הָעולָמִים. מֶלֶךְ מְשֻׁבָּח וּמְפאָר עֲדֵי עַד שְׁמו הַגָּדול: בָּרוּךְ אַתָּה ה' מֶלֶךְ מְהֻלָּל בַּתִּשְׁבָּחות:"}]},{"id":"pesukei-dezimra-hodu","heading":"Hodu","group":"Pesukei Dezimra","lines":[{"he":"הודוּ לה' קִרְאוּ בִשְׁמו. הודִיעוּ בָעַמִּים עֲלִילותָיו: שִׁירוּ לו זַמְּרוּ לו. שיחוּ בְּכָל נִפְלְאותָיו: הִתְהַלְלוּ בְּשֵׁם קָדְשׁו. יִשמַח לֵב מְבַקְשֵׁי ה': דִּרְשׁוּ ה' וְעֻזּו. בַּקְּשׁוּ פָנָיו תָּמִיד: זִכְרוּ נִפְלְאותָיו אֲשֶׁר עָשה. מפְתָיו וּמִשְׁפְּטֵי פִיהוּ: זֶרַע יִשרָאֵל עַבְדּו. בְּנֵי יַעֲקב בְּחִירָיו: הוּא ה' אֱלהֵינוּ. בְּכָל הָאָרֶץ מִשְׁפָּטָיו: זִכְרוּ לְעולָם בְּרִיתו. דָּבָר צִוָּה לְאֶלֶף דּור: אֲשֶׁר כָּרַת אֶת אַבְרָהָם. וּשְׁבוּעָתו לְיִצְחָק: וַיַּעֲמִידֶהָ לְיַעֲקב לְחק. לְיִשרָאֵל בְּרִית עולָם: לֵאמר. לְךָ אֶתֵּן אֶרֶץ כְּנָעַן. חֶבֶל נַחֲלַתְכֶם: בִּהְיותְכֶם מְתֵי מִסְפָּר. כִּמְעַט וְגָרִים בָּהּ: וַיִּתְהַלְּכוּ מִגּוי אֶל גּוי. וּמִמַּמְלָכָה אֶל עַם אַחֵר: לא הִנִּיחַ לְאִישׁ לְעָשְׁקָם. וַיּוכַח עֲלֵיהֶם מְלָכִים: אַל תִּגְּעוּ בִּמְשִׁיחָי וּבִנְבִיאַי אַל תָּרֵעוּ: שִׁירוּ לה' כָּל הָאָרֶץ. בַּשּרוּ מִיּום אֶל יום יְשׁוּעָתו: סַפְּרוּ בַגּויִם אֶת כְּבודו. בְּכָל הָעַמִּים נִפְלְאתָיו: כִּי גָדול ה' וּמְהֻלָּל מְאד. וְנורָא הוּא עַל כָּל אֱלהִים: כִּי כָּל אֱלהֵי הָעַמִּים אֱלִילִים כאן צריך להפסיק וה' שָׁמַיִם עָשה: הוד וְהָדָר לְפָנָיו. עז וְחֶדְוָה בִּמְקומו: הָבוּ לה' מִשְׁפְּחות עַמִּים. הָבוּ לה' כָּבוד וָעז: הָבוּ לה' כְּבוד שְׁמו. שאוּ מִנְחָה וּבאוּ לְפָנָיו. הִשְׁתַּחֲווּ לה' בְּהַדְרַת קדֶשׁ: חִילוּ מִלְּפָנָיו כָּל הָאָרֶץ. אַף תִּכּון תֵּבֵל בַּל תִּמּוט: יִשמְחוּ הַשָּׁמַיִם וְתָגֵל הָאָרֶץ. וְיאמְרוּ בַגּויִם ה' מָלָךְ: יִרְעַם הַיָּם וּמְלאו. יַעֲלץ הַשּדֶה וְכָל אֲשֶׁר בּו: אָז יְרַנְּנוּ עֲצֵי הַיָּעַר מִלִּפְנֵי ה'. כִּי בָא לִשְׁפּוט אֶת הָאָרֶץ: הודוּ לה'. כִּי טוב. כִּי לְעולָם חַסְדּו: וְאִמְרוּ. הושִׁיעֵנוּ אֱלהֵי יִשְׁעֵנוּ. וְקַבְּצֵנוּ וְהַצִּילֵנוּ מִן הַגּויִם. לְהדות לְשֵׁם קָדְשֶׁךָ. לְהִשְׁתַּבֵּחַ בִּתְהִלָּתֶךָ: בָּרוּךְ ה' אֱלהֵי יִשרָאֵל מִן הָעולָם וְעַד הָעולָם וַיּאמְרוּ כָל הָעָם אָמֵן וְהַלֵּל לה': רומְמוּ ה' אֱלהֵינוּ וְהִשְׁתַּחֲווּ לַהֲדם רַגְלָיו. קָדושׁ הוּא: רומְמוּ ה' אֱלהֵינוּ וְהִשְׁתַּחֲווּ לְהַר קָדְשׁו. כִּי קָדושׁ ה' אֱלהֵינוּ: וְהוּא רַחוּם יְכַפֵּר עָון וְלא יַשְׁחִית. וְהִרְבָּה לְהָשִׁיב אַפּו וְלא יָעִיר כָּל חֲמָתו: אַתָּה ה' לא תִכְלָא רַחֲמֶיךָ מִמֶּנִּי. חַסְדְּךָ וַאֲמִתְּךָ תָּמִיד יִצְּרוּנִי: זְכר רַחֲמֶיךָ ה'. וַחֲסָדֶיךָ. כִּי מֵעולָם הֵמָּה: תְּנוּ עז לֵאלהִים עַל יִשרָאֵל גַּאֲוָתו. וְעֻזּו בַּשְּׁחָקִים: נורָא אֱלהִים מִמִּקְדָּשֶׁיךָ. אֵל יִשרָאֵל. הוּא נותֵן עז וְתַעֲצֻמות לָעָם. בָּרוּךְ אֱלהִים: אֵל נְקָמות ה'. אֵל נְקָמות הופִיעַ: הִנָּשא שׁפֵט הָאָרֶץ הָשֵׁב גְּמוּל עַל גֵּאִים: לה' הַיְשׁוּעָה. עַל עַמְּךָ בִרְכָתֶךָ סֶּלָה: ה' צְבָאות עִמָּנוּ. מִשגָּב לָנוּ אֱלהֵי יַעֲקב סֶלָה: ה' צְבָאות. אַשְׁרֵי אָדָם בּטֵחַ בָּךְ: ה'. הושִׁיעָה. הַמֶּלֶךְ יַעֲנֵנוּ בְיום קָרְאֵנוּ: הושִׁיעָה אֶת עַמֶּךָ וּבָרֵךְ אֶת נַחֲלָתֶךָ. וּרְעֵם וְנַשּאֵם עַד הָעולָם: נַפְשֵׁנוּ חִכְּתָה לה'. עֶזְרֵנוּ וּמָגִנֵּנוּ הוּא: כִּי בו יִשמַח לִבֵּנוּ. כִּי בְשֵׁם קָדְשׁו בָטָחְנוּ: יְהִי חַסְדְּךָ ה' עָלֵינוּ. כַּאֲשֶׁר יִחַלְנוּ לָךְ: הַרְאֵנוּ ה' חַסְדֶּךָ. וְיֶשְׁעֲךָ תִּתֶּן לָנוּ: קוּמָה עֶזְרָתָה לָנוּ. וּפְדֵנוּ לְמַעַן חַסְדֶּךָ: אָנכִי ה' אֱלהֶיךָ הַמַּעַלְךָ מֵאֶרֶץ מִצְרָיִם. הַרְחֶב פִּיךָ וַאֲמַלְאֵהוּ: אַשְׁרֵי הָעָם שֶׁכָּכָה לּו. אַשְׁרֵי הָעָם שֶׁה' אֱלהָיו: וַאֲנִי בְּחַסְדְּךָ בָטַחְתִּי. יָגֵל לִבִּי בִּישׁוּעָתֶךָ. אָשִׁירָה לה' כִּי גָמַל עָלָי:"}]},{"id":"pesukei-dezimra-psalm-19","heading":"Psalm 19","group":"Pesukei Dezimra","lines":[{"he":"לַמְנַצֵּחַ מִזְמור לְדָוִד: הַשָּׁמַיִם מְסַפְּרִים כְּבוד אֵל. וּמַעֲשה יָדָיו מַגִּיד הָרָקִיעַ: יום לְיום יַבִּיעַ אמֶר. וְלַיְלָה לְלַיְלָה יְחַוֶּה דָּעַת: אֵין אמֶר וְאֵין דְּבָרִים. בְּלִי נִשְׁמָע קולָם: בְּכָל הָאָרֶץ יָצָא קַוָּם. וּבִקְצֵה תֵבֵל מִלֵּיהֶם. לַשֶּׁמֶשׁ שם אהֶל בָּהֶם: וְהוּא כְּחָתָן יצֵא מֵחֻפָּתו. יָשיש כְּגִבּור לָרוּץ ארַח: מִקְצֵה הַשָּׁמַיִם מוצָאו וּתְקוּפָתו עַל קְצותָם. וְאֵין נִסְתָּר מֵחַמָּתו: תּורַת ה' תְּמִימָה מְשִׁיבַת נָפֶשׁ. עֵדוּת ה' נֶאֱמָנָה מַחְכִּימַת פֶּתִי: פִּקּוּדֵי ה' יְשָׁרִים מְשמְּחֵי לֵב. מִצְוַת ה' בָּרָה מְאִירַת עֵינָיִם: יִרְאַת ה' טְהורָה עומֶדֶת לָעַד. מִשְׁפְּטֵי ה' אֱמֶת צָדְקוּ יַחְדָּו: הַנֶחֱמָדִים מִזָּהָב וּמִפָּז רָב. וּמְתוּקִים מִדְּבַשׁ וְנפֶת צוּפִים: גַּם עַבְדְּךָ נִזְהָר בָּהֶם. בְּשָׁמְרָם עֵקֶב רָב: שְׁגִיאות מִי יָבִין מִנִּסְתָּרות נַקֵּנִי: גַּם מִזֵּדִים חֲשךְ עַבְדֶּךָ. אַל יִמְשְׁלוּ בִי אָז אֵיתָם. וְנִקֵּיתִי מִפֶּשַׁע רָב: יִהְיוּ לְרָצון אִמְרֵי פִי וְהֶגְיון לִבִּי. לְפָנֶיךָ ה' צוּרִי וְגאֲלִי:"}]},{"id":"pesukei-dezimra-psalm-34","heading":"Psalm 34","group":"Pesukei Dezimra","lines":[{"he":"לְדָוִד בְּשַׁנּותו אֶת טַעְמו לִפְנֵי אֲבִימֶלֶךְ. וַיְגָרְשֵׁהוּ וַיֵּלַךְ: אֲבָרְכָה אֶת ה' בְּכָל עֵת. תָּמִיד תְּהִלָּתו בְּפִי: בה' תִּתְהַלֵּל נַפְשִׁי. יִשְׁמְעוּ עֲנָוִים וְיִשמָחוּ: גַדְּלוּ לה' אִתִּי. וּנְרומְמָה שְׁמו יַחְדָּו: דָּרַשְׁתִּי אֶת ה' וְעָנָנִי. וּמִכָּל מְגוּרותַי הִצִּילָנִי: הִבִּיטוּ אֵלָיו וְנָהָרוּ. וּפְנֵיהֶם אַל יֶחְפָּרוּ: זֶה עָנִי קָרָא וה' שָׁמֵעַ. וּמִכָּל צָרותָיו הושִׁיעו: חונֶה מַלְאַךְ ה' סָבִיב לִירֵאָיו וַיְחַלְּצֵם: טַעֲמוּ וּרְאוּ כִּי טוב ה'. אַשְׁרֵי הַגֶּבֶר יֶחֱסֶה בּו: יְראוּ אֶת ה' קְדושָׁיו. כִּי אֵין מַחְסור לִירֵאָיו: כְּפִירִים רָשׁוּ וְרָעֵבוּ. וְדורְשֵׁי ה' לא יַחְסְרוּ כָל טוב: לְכוּ בָנִים שִׁמְעוּ לִי. יִרְאַת ה' אֲלַמֶּדְכֶם: מִי הָאִישׁ הֶחָפֵץ חַיִּים. אהֵב יָמִים לִרְאות טוב: נְצור לְשׁונְךָ מֵרָע. וּשפָתֶיךָ מִדַּבֵּר מִרְמָה: סוּר מֵרָע וַעֲשה טוב. בַּקֵּשׁ שָׁלום וְרָדְפֵהוּ: עֵינֵי ה' אֶל צַדִּיקִים. וְאָזְנָיו אֶל שַׁוְעָתָם: פְּנֵי ה' בְּעושי רָע. לְהַכְרִית מֵאֶרֶץ זִכְרָם: צָעֲקוּ וה' שָׁמֵעַ. וּמִכָּל צָרותָם הִצִּילָם: קָרוב ה' לְנִשְׁבְּרֵי לֵב. וְאֶת דַּכְּאֵי רוּחַ יושִׁיעַ: רַבּות רָעות צַדִּיק. וּמִכֻּלָּם יַצִּילֶנּוּ ה': שׁמֵר כָּל עַצְמותָיו. אַחַת מֵהֵנָּה לא נִשְׁבָּרָה: תְּמותֵת רָשָׁע רָעָה. וְשנְאֵי צַדִּיק יֶאְשָׁמוּ: פּודֶה ה' נֶפֶשׁ עֲבָדָיו. וְלא יֶאְשְׁמוּ כָּל הַחוסִים בּו:","en":"Of David when he disguised his sancitity before Avimelech, who drove him out, and he left."}]},{"id":"pesukei-dezimra-psalm-90","heading":"Psalm 90","group":"Pesukei Dezimra","lines":[{"he":"תְּפִלָּה לְמשֶׁה אִישׁ הָאֱלהִים. אֲדנָי מָעון אַתָּה הָיִיתָ לָּנוּ. בְּדור וָדר: בְּטֶרֶם הָרִים יֻלָּדוּ וַתְּחולֵל אֶרֶץ וְתֵבֵל. וּמֵעולָם עַד עולָם אַתָּה אֵל: תָּשֵׁב אֱנושׁ עַד דַּכָּא. וַתּאמֶר שׁוּבוּ בְנֵי אָדָם: כִּי אֶלֶף שָׁנִים בְּעֵינֶיךָ כְּיום אֶתְמול כִּי יַעֲבר. וְאַשְׁמוּרָה בַלָּיְלָה: זְרַמְתָּם שֵׁנָה יִהְיוּ. בַּבּקֶר כֶּחָצִיר יַחֲלף: בַּבּקֶר יָצִיץ וְחָלָף. לָעֶרֶב יְמולֵל וְיָבֵשׁ: כִּי כָלִינוּ בְאַפֶּךָ. וּבַחֲמָתְךָ נִבְהָלְנוּ: שַׁתָּה עֲונותֵינוּ לְנֶגְדֶּךָ. עֲלֻמֵנוּ לִמְאור פָּנֶיךָ: כִּי כָל יָמֵינוּ פָּנוּ בְעֶבְרָתֶךָ. כִּלִּינוּ שָׁנֵינוּ כְּמו הֶגֶה: יְמֵי שְׁנותֵינוּ בָּהֶם שִׁבְעִים שָׁנָה. וְאִם בִּגְבוּרת שְׁמונִים שָׁנָה. וְרָהְבָּם עָמָל וָאָוֶן. כִּי גָז חִישׁ וַנָּעֻפָה: מִי יודֵעַ עז אַפֶּךָ. וּכְיִרְאָתְךָ עֶבְרָתֶךָ: לִמְנות יָמֵינוּ כֵּן הודַע. וְנָבִיא לְבַב חָכְמָה: שׁוּבָה ה' עַד מָתָי. וְהִנָּחֵם עַל עֲבָדֶיךָ: שבְּעֵנוּ בַבּקֶר חַסְדֶּךָ. וּנְרַנְּנָה וְנִשמְחָה בְּכָל יָמֵינוּ: שמְּחֵנוּ כִּימות עִנִּיתָנוּ. שְׁנות רָאִינוּ רָעָה: יֵרָאֶה אֶל עֲבָדֶיךָ פָעֳלֶךָ. וַהֲדָרְךָ עַל בְּנֵיהֶם: וִיהִי נעַם אֲדנָי אֱלהֵינוּ עָלֵינוּ. וּמַעֲשה יָדֵינוּ כּונְנָה עָלֵינוּ. וּמַעֲשה יָדֵינוּ כּונְנֵהוּ:"}]},{"id":"pesukei-dezimra-psalm-91","heading":"Psalm 91","group":"Pesukei Dezimra","lines":[{"he":"ישֵׁב בְּסֵתֶר עֶלְיון. בְּצֵל שַׁדַּי יִתְלונָן: אמַר לה' מַחְסִי וּמְצוּדָתִי. אֱלהַי אֶבְטַח בּו: כִּי הוּא יַצִּילְךָ מִפַּח יָקוּשׁ. מִדֶּבֶר הַוּות: בְּאֶבְרָתו יָסֶךְ לָךְ. וְתַחַת כְּנָפָיו תֶּחְסֶה. צִנָּה וְסוחֵרָה אֲמִתּו: לא תִירָא מִפַּחַד לָיְלָה. מֵחֵץ יָעוּף יומָם: מִדֶּבֶר בָּאפֶל יַהֲלךְ. מִקֶּטֶב יָשׁוּד צָהֳרָיִם: יִפּל מִצִּדְּךָ אֶלֶף וּרְבָבָה מִימִינֶךָ. אֵלֶיךָ לא יִגָּשׁ: רַק בְּעֵינֶיךָ תַבִּיט. וְשִׁלֻּמַת רְשָׁעִים תִּרְאֶה: כִּי אַתָּה ה' מַחְסִי. עֶלְיון שמְתָּ מְעונֶךָ: לא תְאֻנֶּה אֵלֶיךָ רָעָה. וְנֶגַע לא יִקְרַב בְּאָהֳלֶךָ: כִּי מַלְאָכָיו יְצַוֶּה לָּךְ. לִשְׁמָרְךָ בְּכָל דְּרָכֶיךָ: עַל כַּפַּיִם יִשּאוּנְךָ. פֶּן תִּגּוף בָּאֶבֶן רַגְלֶךָ: עַל שַׁחַל וָפֶתֶן תִּדְרוךְ. תִּרְמוס כְּפִיר וְתַנִּין: כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ. אֲשגְּבֵהוּ כִּי יָדַע שְׁמִי: יִקְרָאֵנִי וְאֶעֱנֵהוּ. עִמּו אָנכִי בְצָרָה. אֲחַלְּצֵהוּ וַאֲכַבְּדֵהוּ: ארֶךְ יָמִים אַשבִּיעֵהוּ. וְאַרְאֵהוּ בִּישׁוּעָתִי: ארֶךְ יָמִים אַשבִּיעֵהוּ. וְאַרְאֵהוּ בִּישׁוּעָתִי:"}]},{"id":"pesukei-dezimra-psalm-135","heading":"Psalm 135","group":"Pesukei Dezimra","lines":[{"he":"הַלְלוּיָהּ. הַלְלוּ אֶת שֵׁם ה'. הַלְלוּ עַבְדֵי ה': שֶׁעומְדִים בְּבֵית ה'. בְּחַצְרות בֵּית אֱלהֵינוּ: הַלְלוּיָהּ כִּי טוב ה'. זַמְּרוּ לִשְׁמו כִּי נָעִים: כִּי יַעֲקב בָּחַר לו יָהּ. יִשרָאֵל לִסְגֻלָּתו: כִּי אֲנִי יָדַעְתִּי כִּי גָּדול ה'. וַאֲדנֵינוּ מִכָּל אֱלהִים: כּל אֲשֶׁר חָפֵץ ה' עָשה. בַּשָּׁמַיִם וּבָאָרֶץ בַּיַּמִּים וְכָל תְּהמת: מַעֲלֶה נְשאִים מִקְצֵה הָאָרֶץ. בְּרָקִים לַמָּטָר עָשה. מוצֵא רוּחַ מֵאוצְרותָיו: שֶׁהִכָּה בְּכורֵי מִצְרָיִם. מֵאָדָם עַד בְּהֵמָה: שָׁלַח אותת וּמופְתִים בְּתוכֵכִי מִצְרָיִם. בְּפַרְעה וּבְכָל עֲבָדָיו: שֶׁהִכָּה גּויִם רַבִּים. וְהָרַג מְלָכִים עֲצוּמִים: לְסִיחון מֶלֶךְ הָאֱמרִי וּלְעוג מֶלֶךְ הַבָּשָׁן. וּלְכל מַמְלְכות כְּנָעַן: וְנָתַן אַרְצָם נַחֲלָה. נַחֲלָה לְיִשרָאֵל עַמּו: ה' שִׁמְךָ לְעולָם. ה' זִכְרְךָ לְדר וָדר: כִּי יָדִין ה' עַמּו. וְעַל עֲבָדָיו יִתְנֶחָם: עֲצַבֵּי הַגּויִם כֶּסֶף וְזָהָב. מַעֲשה יְדֵי אָדָם: פֶּה לָהֶם וְלא יְדַבֵּרוּ. עֵינַיִם לָהֶם וְלא יִרְאוּ: אָזְנַיִם לָהֶם וְלא יַאֲזִינוּ. אַף אֵין יֶשׁ רוּחַ בְּפִיהֶם: כְּמוהֶם יִהְיוּ עשיהֶם. כּל אֲשֶׁר בּטֵחַ בָּהֶם: בֵּית יִשרָאֵל בָּרְכוּ אֶת ה'. בֵּית אַהֲרן בָּרְכוּ אֶת ה': בֵּית הַלֵּוִי בָּרְכוּ אֶת ה'. יִרְאֵי ה' בָּרְכוּ אֶת ה': בָּרוּךְ ה' מִצִּיּון. שׁכֵן יְרוּשָׁלָיִם. הַלְלוּיָהּ:"}]},{"id":"pesukei-dezimra-psalm-136","heading":"Psalm 136","group":"Pesukei Dezimra","lines":[{"he":"הודוּ לה' כִּי טוב כִּי לְעולָם חַסְדּו: הודוּ לֵאלהֵי הָאֱלהִים כִּי לְעולָם חַסְדּו: הודוּ לַאֲדנֵי הָאֲדנִים כִּי לְעולָם חַסְדּו: לְעשה נִפְלָאות גְּדלות לְבַדּו כִּי לְעולָם חַסְדּו: לְעשה הַשָּׁמַיִם בִּתְבוּנָה כִּי לְעולָם חַסְדּו: לְרוקַע הָאָרֶץ עַל הַמָּיִם כִּי לְעולָם חַסְדּו: לְעשה אורִים גְּדלִים כִּי לְעולָם חַסְדּו: אֶת הַשֶּׁמֶשׁ לְמֶמְשֶׁלֶת בַּיּום כִּי לְעולָם חַסְדּו: אֶת הַיָּרֵחַ וְכוכָבִים לְמֶמְשְׁלות בַּלָּיְלָה כִּי לְעולָם חַסְדּו: לְמַכֵּה מִצְרַיִם בִּבְכורֵיהֶם כִּי לְעולָם חַסְדּו: וַיּוצֵא יִשרָאֵל מִתּוכָם כִּי לְעולָם חַסְדּו: בְּיָד חֲזָקָה וּבִזְרועַ נְטוּיָה כִּי לְעולָם חַסְדּו: לְגזֵר יַם סוּף לִגְזָרִים כִּי לְעולָם חַסְדּו: וְהֶעֱבִיר יִשרָאֵל בְּתוכו כִּי לְעולָם חַסְדּו: וְנִעֵר פַּרְעה וְחֵילו בְיַם סוּף כִּי לְעולָם חַסְדּו: לְמולִיךְ עַמּו בַּמִּדְבָּר כִּי לְעולָם חַסְדּו: לְמַכֵּה מְלָכִים גְּדלִים כִּי לְעולָם חַסְדּו: וַיַּהֲרג מְלָכִים אַדִּירִים כִּי לְעולָם חַסְדּו: לְסִיחון מֶלֶךְ הָאֱמרִי כִּי לְעולָם חַסְדּו: וּלְעוג מֶלֶךְ הַבָּשָׁן כִּי לְעולָם חַסְדּו: וְנָתַן אַרְצָם לְנַחֲלָה כִּי לְעולָם חַסְדּו: נַחֲלָה לְיִשרָאֵל עַבְדּו כִּי לְעולָם חַסְדּו: שֶׁבְּשִׁפְלֵנוּ זָכַר לָנוּ כִּי לְעולָם חַסְדּו: וַיִּפְרְקֵנוּ מִצָּרֵינוּ כִּי לְעולָם חַסְדּו: נותֵן לֶחֶם לְכָל בָּשר כִּי לְעולָם חַסְדּו: הודוּ לְאֵל הַשָּׁמָיִם כִּי לְעולָם חַסְדּו:"}]},{"id":"pesukei-dezimra-psalm-33","heading":"Psalm 33","group":"Pesukei Dezimra","lines":[{"he":"רַנְּנוּ צַדִּיקִים בה'. לַיְשָׁרִים נָאוָה תְהִלָּה: הודוּ לה' בְּכִנּור. בְּנֵבֶל עָשור זַמְּרוּ לו: שִׁירוּ לו שִׁיר חָדָשׁ. הֵיטִיבוּ נַגֵּן בִּתְרוּעָה: כִּי יָשָׁר דְבַר ה'. וְכָל מַעֲשהוּ בֶּאֱמוּנָה: אהֵב צְדָקָה וּמִשְׁפָּט. חֶסֶד ה' מָלְאָה הָאָרֶץ: בִּדְבַר ה' שָׁמַיִם נַעֲשוּ. וּבְרוּחַ פִּיו כָּל צְבָאָם: כּנֵס כַּנֵּד מֵי הַיָּם. נתֵן בְּאוצָרות תְּהומות: יִירְאוּ מה' כָּל הָאָרֶץ. מִמֶּנּוּ יָגוּרוּ כָּל ישְׁבֵי תֵבֵל: כִּי הוּא אָמַר וַיֶּהִי. הוּא צִוָּה וַיַּעֲמד: ה' הֵפִיר עֲצַת גּויִם. הֵנִיא מַחְשְׁבות עַמִּים: עֲצַת ה' לְעולָם תַּעֲמד. מַחְשְׁבות לִבּו לְדר וָדר: אַשְׁרֵי הַגּוי אֲשֶׁר ה' אֱלהָיו. הָעָם בָּחַר לְנַחֲלָה לו: מִשָּׁמַיִם הִבִּיט ה'. רָאָה אֶת כָּל בְּנֵי הָאָדָם: מִמְּכון שִׁבְתּו הִשְׁגִּיחַ אֶל כָּל ישְׁבֵי הָאָרֶץ: הַיּוצֵר יַחַד לִבָּם. הַמֵּבִין אֶל כָּל מַעֲשיהֶם: אֵין הַמֶּלֶךְ נושָׁע בְּרָב חָיִל. גִּבּור לא יִנָּצֵל בְּרָב כּחַ: שֶׁקֶר הַסּוּס לִתְשׁוּעָה. וּבְרב חֵילו לא יְמַלֵּט: הִנֵּה עֵין ה' אֶל יְרֵאָיו. לַמְיַחֲלִים לְחַסְדּו: לְהַצִּיל מִמָּוֶת נַפְשָׁם. וּלְחַיּותָם בָּרָעָב: נַפְשֵׁנוּ חִכְּתָה לה'. עֶזְרֵנוּ וּמָגִנֵּנוּ הוּא: כִּי בו יִשמַח לִבֵּנוּ. כִּי בְשֵׁם קָדְשׁו בָטָחְנוּ: יְהִי חַסְדְּךָ ה' עָלֵינוּ. כַּאֲשֶׁר יִחַלְנוּ לָךְ:"}]},{"id":"pesukei-dezimra-psalm-92","heading":"Psalm 92","group":"Pesukei Dezimra","lines":[{"he":"מִזְמור שִׁיר לְיום הַשַּׁבָּת: טוב לְהודות לה'. וּלְזַמֵּר לְשִׁמְךָ עֶלְיון: לְהַגִּיד בַּבּוקֶר חַסְדֶּךָ. וֶאֱמוּנָתְךָ בַּלֵּילות: עֲלֵי עָשור וַעֲלֵי נָבֶל. עֲלֵי הִגָּיון בְּכִנּור: כִּי שמַּחְתַּנִי ה' בְּפָעֳלֶךָ. בְּמַעֲשי יָדֶיךָ אֲרַנֵּן: מַה גָּדְלוּ מַעֲשיךָ ה'. מְאד עָמְקוּ מַחְשְׁבותֶיךָ: אִישׁ בַּעַר לא יֵדָע. וּכְסִיל לא יָבִין אֶת זאת: בִּפְרחַ רְשָׁעִים כְּמו עֵשב. וַיָּצִיצוּ כָּל פּעֲלֵי אָוֶן. לְהִשָּׁמְדָם עֲדֵי עַד: וְאַתָּה מָרום לְעולָם ה': כִּי הִנֵּה איְבֶיךָ ה'. כִּי הִנֵּה איְבֶיךָ יאבֵדוּ. יִתְפָּרְדוּ כָּל פּעֲלֵי אָוֶן: וַתָּרֶם כִּרְאֵים קַרְנִי. בַּלּתִי בְּשֶׁמֶן רַעֲנָן: וַתַּבֵּט עֵינִי בְּשׁוּרָי. בַּקָּמִים עָלַי מְרֵעִים תִּשְׁמַעְנָה אָזְנָי: צַדִּיק כַּתָּמָר יִפְרָח. כְּאֶרֶז בַּלְּבָנון יִשגֶּה: שְׁתוּלִים בְּבֵית ה'. בְּחַצְרות אֱלהֵינוּ יַפְרִיחוּ: עוד יְנוּבוּן בְּשיבָה. דְּשֵׁנִים וְרַעֲנַנִּים יִהְיוּ: לְהַגִּיד כִּי יָשָׁר ה'. צוּרִי וְלא עַוְלָתָה בּו:"}]},{"id":"pesukei-dezimra-psalm-93","heading":"Psalm 93","group":"Pesukei Dezimra","lines":[{"he":"ה' מָלָךְ גֵּאוּת לָבֵשׁ. לָבֵשׁ ה' עז הִתְאַזָּר. אַף תִּכּון תֵּבֵל בַּל תִּמּוט: נָכון כִּסְאֲךָ מֵאָז. מֵעולָם אָתָּה: נָשאוּ נְהָרות ה'. נָשאוּ נְהָרות קולָם. יִשאוּ נְהָרות דָּכְיָם: מִקּלות מַיִם רַבִּים אַדִּירִים מִשְׁבְּרֵי יָם. אַדִּיר בַּמָּרום ה': עֵדותֶיךָ נֶאֱמְנוּ מְאד. לְבֵיתְךָ נָאֲוָה קּדֶשׁ. ה' לְארֶךְ יָמִים:"}]},{"id":"pesukei-dezimra-yehi-chevod","heading":"Yehi Chevod","group":"Pesukei Dezimra","lines":[{"he":"יְהִי כְבוד ה' לְעולָם. יִשמַח ה' בְּמַעֲשיו: יְהִי שֵׁם ה' מְברָךְ. מֵעַתָּה וְעַד עולָם: מִמִּזְרַח שֶׁמֶשׁ עַד מְבואו. מְהֻלָּל שֵׁם ה': רָם עַל כָּל גּויִם ה'. עַל הַשָּׁמַיִם כְּבודו: ה' שִׁמְךָ לְעולָם. ה' זִכְרְךָ לְדור וָדור: ה' בַּשָׁמַיִם הֵכִין כִּסְאו. וּמַלְכוּתו בַּכּל מָשָׁלָה: יִשמְחוּ הַשָּׁמַיִם וְתָגֵל הָאָרֶץ. וְיאמְרוּ בַגּויִם ה' מָלָךְ: ה' מֶלֶךְ. ה' מָלָךְ. ה' יִמְלךְ לְעולָם וָעֶד: ה' מֶלֶךְ עולָם וָעֶד. אָבְדוּ גויִם מֵאַרְצו: ה' הֵפִיר עֲצַת גּויִם. הֵנִיא מַחְשְׁבות עַמִּים: רַבּות מַחֲשָׁבות בְּלֶב אִישׁ. וַעֲצַת ה' הִיא תָקוּם: עֲצַת ה' לְעולָם תַּעֲמוד. מַחְשְׁבות לִבּו לְדר וָדר: כִּי הוּא אָמַר וַיֶּהִי. הוּא צִוָּה וַיַּעֲמד: כִּי בָחַר ה' בְּצִיּון. אִוָּהּ לְמושָׁב לו: כִּי יַעֲקב בָּחַר לו יָהּ. יִשרָאֵל לִסְגֻלָּתו: כִּי לא יִטּשׁ ה' עַמּו. וְנַחֲלָתו לא יַעֲזב: וְהוּא רַחוּם יְכַפֵּר עָון וְלא יַשְׁחִית. וְהִרְבָּה לְהָשִׁיב אַפּו. וְלא יָעִיר כָּל חֲמָתו: ה' הושִׁיעָה. הַמֶּלֶךְ יַעֲנֵנוּ בְיום קָרְאֵנוּ:"}]},{"id":"pesukei-dezimra-ashrei","heading":"Ashrei","group":"Pesukei Dezimra","lines":[{"he":"אַשְׁרֵי יושְׁבֵי בֵיתֶךָ. עוד יְהַלְלוּךָ סֶּלָה: אַשְׁרֵי הָעָם שֶׁכָּכָה לּו. אַשְׁרֵי הָעָם שה' אֱלהָיו: תְּהִלָּה לְדָוִד. אֲרומִמְךָ אֱלוהַי הַמֶּלֶךְ. וַאֲבָרְכָה שִׁמְךָ לְעולָם וָעֶד: בְּכָל יום אֲבָרְכֶךָּ. וַאֲהַלְלָה שִׁמְךָ לְעולָם וָעֶד: גָּדול ה' וּמְהֻלָּל מְאד. וְלִגְדֻלָּתו אֵין חֵקֶר: דּור לְדור יְשַׁבַּח מַעֲשיךָ. וּגְבוּרתֶיךָ יַגִּידוּ: הֲדַר כְּבוד הודֶךָ. וְדִבְרֵי נִפְלְאתֶיךָ אָשיחָה: וֶעֱזוּז נורְאתֶיךָ יאמֵרוּ. וּגְדֻלָּתְךָ אֲסַפְּרֶנָּה: זֵכֶר רַב טוּבְךָ יַבִּיעוּ. וְצִדְקָתְךָ יְרַנֵּנוּ: חַנּוּן וְרַחוּם ה'. אֶרֶךְ אַפַּיִם וּגְדָל חָסֶד: טוב ה' לַכּל. וְרַחֲמָיו עַל כָּל מַעֲשיו: יודוּךָ ה' כָּל מַעֲשיךָ. וַחֲסִידֶיךָ יְבָרְכוּכָה: כְּבוד מַלְכוּתְךָ יאמֵרוּ. וּגְבוּרָתְךָ יְדַבֵּרוּ: לְהודִיעַ לִבְנֵי הָאָדָם גְּבוּרתָיו. וּכְבוד הֲדַר מַלְכוּתו: מַלְכוּתְךָ מַלְכוּת כָּל עולָמִים. וּמֶמְשַׁלְתְּךָ בְּכָל דּור וָדר: סומֵךְ ה' לְכָל הַנּפְלִים. וְזוקֵף לְכָל הַכְּפוּפִים: עֵינֵי כל אֵלֶיךָ יְשבֵּרוּ. וְאַתָּה נותֵן לָהֶם אֶת אָכְלָם בְּעִתּו: פּותֵחַ אֶת יָדֶךָ. וּמַשבִּיעַ לְכָל חַי רָצון: צַדִּיק ה' בְּכָל דְּרָכָיו. וְחָסִיד בְּכָל מַעֲשיו: קָרוב ה' לְכָל קרְאָיו. לְכל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת: רְצון יְרֵאָיו יַעֲשה. וְאֶת שַׁוְעָתָם יִשְׁמַע וְיושִׁיעֵם: שׁומֵר ה' אֶת כָּל אהֲבָיו. וְאֵת כָּל הָרְשָׁעִים יַשְׁמִיד: תְּהִלַּת ה' יְדַבֶּר פִּי. וִיבָרֵךְ כָּל בָּשר שֵׁם קָדְשׁו לְעולָם וָעֶד: וַאֲנַחְנוּ נְבָרֵךְ יָהּ מֵעַתָּה וְעַד עולָם. הַלְלוּיָהּ:"}]},{"id":"pesukei-dezimra-psalm-146","heading":"Psalm 146","group":"Pesukei Dezimra","lines":[{"he":"הַלְלוּיָהּ. הַלְלִי נַפְשִׁי אֶת ה': אֲהַלְלָה ה' בְּחַיָּי. אֲזַמְּרָה לֵאלהַי בְּעודִי: אַל תִּבְטְחוּ בִנְדִיבִים. בְּבֶן אָדָם שֶׁאֵין לו תְשׁוּעָה: תֵּצֵא רוּחו יָשֻׁב לְאַדְמָתו. בַּיּום הַהוּא אָבְדוּ עֶשְׁתּנתָיו: אַשְׁרֵי שֶׁאֵל יַעֲקב בְּעֶזְרו. שבְרו עַל ה' אֱלהָיו: עשה שָׁמַיִם וָאָרֶץ. אֶת הַיָּם וְאֶת כָּל אֲשֶׁר בָּם. הַשּׁמֵר אֱמֶת לְעולָם: עשה מִשְׁפָּט לַעֲשׁוּקִים. נתֵן לֶחֶם לָרְעֵבִים. ה' מַתִּיר אֲסוּרִים: ה' פּקֵחַ עִוְרִים. ה' זוקֵף כְּפוּפִים. ה' אהֵב צַדִּיקִים: ה' שׁמֵר אֶת גֵּרִים. יָתום וְאַלְמָנָה יְעודֵד. וְדֶרֶךְ רְשָׁעִים יְעַוֵּת: יִמְלךְ ה' לְעולָם. אֱלהַיִךְ צִיּון לְדר וָדר. הַלְלוּיָהּ:"}]},{"id":"pesukei-dezimra-psalm-147","heading":"Psalm 147","group":"Pesukei Dezimra","lines":[{"he":"הַלְלוּיָהּ. כִּי טוב זַמְּרָה אֱלהֵינוּ. כִּי נָעִים נָאוָה תְהִלָּה: בּונֵה יְרוּשָׁלַיִם ה'. נִדְחֵי יִשרָאֵל יְכַנֵּס: הָרופֵא לִשְׁבוּרֵי לֵב. וּמְחַבֵּשׁ לְעַצְּבותָם: מונֶה מִסְפָּר לַכּוכָבִים. לְכֻלָּם שֵׁמות יִקְרָא: גָּדול אֲדונֵינוּ וְרַב כּחַ. לִתְבוּנָתו אֵין מִסְפָּר: מְעודֵד עֲנָוִים ה'. מַשְׁפִּיל רְשָׁעִים עֲדֵי אָרֶץ: עֱנוּ לה' בְּתודָה. זַמְּרוּ לֵאלהֵינוּ בְכִנּור: הַמְכַסֶּה שָׁמַיִם בְּעָבִים. הַמֵּכִין לָאָרֶץ מָטָר. הַמַּצְמִיחַ הָרִים חָצִיר: נותֵן לִבְהֵמָה לַחְמָהּ. לִבְנֵי ערֵב אֲשֶׁר יִקְרָאוּ: לא בִגְבוּרַת הַסּוּס יֶחְפָּץ. לא בְשׁוקֵי הָאִישׁ יִרְצֶה: רוצֶה ה' אֶת יְרֵאָיו. אֶת הַמְיַחֲלִים לְחַסְדּו: שַׁבְּחִי יְרוּשָׁלַיִם אֶת ה'. הַלְלִי אֱלהַיִךְ צִיּון: כִּי חִזַּק בְּרִיחֵי שְׁעָרָיִךְ. בֵּרַךְ בָּנַיִךְ בְּקִרְבֵּךְ: הַשּם גְּבוּלֵךְ שָׁלום. חֵלֶב חִטִּים יַשבִּיעֵךְ: הַשּׁלֵחַ אִמְרָתו אָרֶץ. עַד מְהֵרָה יָרוּץ דְּבָרו: הַנּתֵן שֶׁלֶג כַּצָּמֶר. כְּפור כָּאֵפֶר יְפַזֵּר: מַשְׁלִיךְ קַרְחו כְפִתִּים. לִפְנֵי קָרָתו מִי יַעֲמד: יִשְׁלַח דְּבָרו וְיַמְסֵם. יַשֵּׁב רוּחו יִזְּלוּ מָיִם: מַגִּיד דְּבָרָיו לְיַעֲקב. חֻקָּיו וּמִשְׁפָּטָיו לְיִשרָאֵל: לא עָשה כֵן לְכָל גּוי. וּמִשְׁפָּטִים בַּל יְדָעוּם. הַלְלוּיָהּ:"}]},{"id":"pesukei-dezimra-psalm-148","heading":"Psalm 148","group":"Pesukei Dezimra","lines":[{"he":"הַלְלוּיָהּ. הַלְלוּ אֶת ה' מִן הַשָּׁמַיִם. הַלְלוּהוּ בַּמְּרומִים: הַלְלוּהוּ כָּל מַלְאָכָיו. הַלְלוּהוּ כָּל צְבָאָיו: הַלְלוּהוּ שֶׁמֶשׁ וְיָרֵחַ. הַלְלוּהוּ כָּל כּוכְבֵי אור: הַלְלוּהוּ שְׁמֵי הַשָּׁמָיִם. וְהַמַּיִם אֲשֶׁר מֵעַל הַשָּׁמָיִם יְהַלְלוּ אֶת שֵׁם ה'. כִּי הוּא צִוָּה וְנִבְרָאוּ: וַיַּעֲמִידֵם לָעַד לְעולָם. חָק נָתַן וְלא יַעֲבור: הַלְלוּ אֶת ה' מִן הָאָרֶץ. תַּנִּינִים וְכָל תְּהמות: אֵשׁ וּבָרָד שֶׁלֶג וְקִיטור. רוּחַ סְעָרָה עשה דְבָרו: הֶהָרִים וְכָל גְבָעות. עֵץ פְּרִי וְכָל אֲרָזִים: הַחַיָּה וְכָל בְּהֵמָה. רֶמֶש וְצִפּור כָּנָף: מַלְכֵי אֶרֶץ וְכָל לְאֻמִּים. שרִים וְכָל שׁפְטֵי אָרֶץ: בַּחוּרִים וְגַם בְּתוּלות. זְקֵנִים עִם נְעָרִים: יְהַלְלוּ אֶת שֵׁם ה'. כִּי נִשגָּב שְׁמו לְבַדּו. הודו עַל אֶרֶץ וְשָׁמָיִם: וַיָּרֶם קֶרֶן לְעַמּו. תְּהִלָּה לְכָל חֲסִידָיו. לִבְנֵי יִשרָאֵל עַם קְרבו. הַלְלוּיָהּ:"}]},{"id":"pesukei-dezimra-psalm-149","heading":"Psalm 149","group":"Pesukei Dezimra","lines":[{"he":"הַלְלוּיָהּ. שִׁירוּ לה' שִׁיר חָדָשׁ. תְּהִלָּתו בִּקְהַל חֲסִידִים: יִשמַח יִשרָאֵל בְּעשיו. בְּנֵי צִיּון יָגִילוּ בְמַלְכָּם: יְהַלְלוּ שְׁמו בְמָחול. בְּתף וְכִנּור יְזַמְּרוּ לו: כִּי רוצֶה ה' בְּעַמּו. יְפָאֵר עֲנָוִים בִּישׁוּעָה: יַעְלְזוּ חֲסִידִים בְּכָבוד. יְרַנְּנוּ עַל מִשְׁכְּבותָם: רומְמות אֵל בִּגְרונָם. וְחֶרֶב פִּיפִיּות בְּיָדָם: לַעֲשות נְקָמָה בַגּויִם. תּוכֵחות בַּלְאֻמִּים: לֶאְסר מַלְכֵיהֶם בְּזִקִּים. וְנִכְבְּדֵיהֶם בְּכַבְלֵי בַרְזֶל: לַעֲשות בָּהֶם מִשְׁפָּט כָּתוּב. הָדָר הוּא לְכָל חֲסִידָיו. הַלְלוּיָהּ:"}]},{"id":"pesukei-dezimra-psalm-150","heading":"Psalm 150","group":"Pesukei Dezimra","lines":[{"he":"הַלְלוּיָהּ. הַלְלוּ אֵל בְּקָדְשׁו. הַלְלוּהוּ בִּרְקִיעַ עֻזּו: הַלְלוּהוּ בִּגְבוּרתָיו. הַלְלוּהוּ כְּרב גֻּדְלו: הַלְלוּהוּ בְּתֵקַע שׁופָר. הַלְלוּהוּ בְּנֵבֶל וְכִנּור: הַלְלוּהוּ בְּתף וּמָחול. הַלְלוּהוּ בְּמִנִּים וְעֻגָב: הַלְלוּהוּ בְּצִלְצְלֵי שָׁמַע. הַלְלוּהוּ בְּצִלְצְלֵי תְרוּעָה: כּל הַנְּשָׁמָה תְּהַלֵּל יָהּ. הַלְלוּיָהּ: כּל הַנְּשָׁמָה תְּהַלֵּל יָהּ. הַלְלוּיָהּ:"}]},{"id":"pesukei-dezimra-baruch-hashem","heading":"Baruch Hashem","group":"Pesukei Dezimra","lines":[{"he":"בָּרוּךְ ה' לְעולָם. אָמֵן וְאָמֵן: בָּרוּךְ ה' מִצִּיּון שׁכֵן יְרוּשָׁלָיִם. הַלְלוּיָהּ: בָּרוּךְ ה' אֱלהִים אֱלהֵי יִשרָאֵל. עשה נִפְלָאות לְבַדּו: וּבָרוּךְ שֵׁם כְּבודו לְעולָם. וְיִמָּלֵא כְבודו אֶת כָּל הָאָרֶץ. אָמֵן וְאָמֵן:"}]},{"id":"pesukei-dezimra-vayevarech-david","heading":"Vayevarech David","group":"Pesukei Dezimra","lines":[{"he":"וַיְבָרֶךְ דָּוִיד אֶת ה' לְעֵינֵי כָּל הַקָּהָל. וַיּאמֶר דָּוִיד. בָּרוּךְ אַתָּה ה' אֱלהֵי יִשרָאֵל אָבִינוּ. מֵעולָם וְעַד עולָם: לְךָ ה' הַגְּדֻלָּה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְהַנֵּצַח וְהַהוד. כִּי כל בַּשָּׁמַיִם וּבָאָרֶץ. לְךָ ה' הַמַּמְלָכָה. וְהַמִּתְנַשּא לְכל לְראשׁ: וְהָעשֶׁר וְהַכָּבוד מִלְּפָנֶיךָ. וְאַתָּה מושֵׁל בַּכּל. וּבְיָדְךָ כּחַ וּגְבוּרָה. וּבְיָדְךָ לְגַדֵּל וּלְחַזֵּק לַכּל: וְעַתָּה אֱלהֵינוּ מודִים אֲנַחְנוּ לָךְ. וּמְהַלְלִים לְשֵׁם תִּפְאַרְתֶּךָ:"},{"he":"אַתָּה הוּא ה' לְבַדֶּךָ. אַתָּה עָשיתָ אֶת הַשָּׁמַיִם. שְׁמֵי הַשָּׁמַיִם וְכָל צְבָאָם. הָאָרֶץ וְכָל אֲשֶׁר עָלֶיהָ. הַיַּמִּים וְכָל אֲשֶׁר בָּהֶם. וְאַתָּה מְחַיֶּה אֶת כֻּלָּם. וּצְבָא הַשָּׁמַיִם לְךָ מִשְׁתַּחֲוִים: אַתָּה הוּא ה' הָאֱלהִים. אֲשֶׁר בָּחַרְתָּ בְּאַבְרָם. וְהוצֵאתו מֵאוּר כַּשדִּים. וְשמְתָּ שְׁמו אַבְרָהָם: וּמָצָאתָ אֶת לְבָבו נֶאֱמָן לְפָנֶיךָ:"},{"he":"וְכָרות עִמּו הַבְּרִית לָתֵת אֶת אֶרֶץ הַכְּנַעֲנִי. הַחִתִּי הָאֱמרִי וְהַפְּרִזִּי וְהַיְבוּסִי וְהַגִּרְגָּשִׁי לָתֵת לְזַרְעו. וַתָּקֶם אֶת דְּבָרֶיךָ כִּי צַדִּיק אָתָּה: וַתֵּרֶא אֶת עֳנִי אֲבותֵינוּ בְּמִצְרָיִם. וְאֶת זַעֲקָתָם שָׁמַעְתָּ עַל יַם סוּף: וַתִּתֵּן אתת וּמפְתִים בְּפַרְעה וּבְכָל עֲבָדָיו וּבְכָל עַם אַרְצו. כִּי יָדַעְתָּ כִּי הֵזִידוּ עֲלֵיהֶם וַתַּעַש לְךָ שֵׁם כְּהַיּום הַזֶּה: וְהַיָּם בָּקַעְתָּ לִפְנֵיהֶם וַיַּעַבְרוּ בְתוךְ הַיָּם בַּיַּבָּשָׁה."},{"he":"וְאֶת רדְפֵיהֶם הִשְׁלַכְתָּ בִמְצולת כְּמו אֶבֶן. בְּמַיִם עַזִּים:"}]},{"id":"pesukei-dezimra-shirat-hayam","heading":"Shirat HaYam","group":"Pesukei Dezimra","lines":[{"he":"וַיּושַׁע ה' בַּיּום הַהוּא אֶת יִשְׂרָאֵל מִיַּד מִצְרָיִם. וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת. עַל שפַת הַיָּם: וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדלָה אֲשֶׁר עָשה ה' בְּמִצְרַיִם. וַיִּירְאוּ הָעָם אֶת ה'. וַיַּאֲמִינוּ בה' וּבְמשֶׁה עַבְדּו:"},{"he":"אָז יָשִׁיר משֶׁה וּבְנֵי יִשְׂרָאֵל אֶת הַשִּׁירָה הַזּאת לה’. וַיּאמְרוּ לֵאמר. אָשִׁירָה לה' כִּי גָּאה גָּאָה. סוּס וְרכְבו רָמָה בַיָּם: עָזִּי וְזִמְרָת יָהּ. וַיְהִי לִי לִישׁוּעָה. זֶה אֵלִי וְאַנְוֵהוּ. אֱלהֵי אָבִי וַאֲרמְמֶנְהוּ: ה' אִישׁ מִלְחָמָה. ה' שְׁמו: מַרְכְּבת פַּרְעה וְחֵילו יָרָה בַיָּם. וּמִבְחַר שָׁלִשָׁיו טֻבְּעוּ בְיַם סוּף: תְּהמת יְכַסְיֻמוּ. יָרְדוּ בִמְצולת כְּמו אָבֶן: יְמִינְךָ ה' נֶאְדָּרִי בַּכּחַ. יְמִינְךָ ה' תִּרְעַץ אויֵב: וּבְרב גְּאונְךָ תַּהֲרס קָמֶיךָ. תְּשַׁלַּח חֲרנְךָ יאכְלֵמו כַּקַּשׁ: וּבְרוּחַ אַפֶּיךָ נֶעֶרְמוּ מַיִם. נִצְּבוּ כְמו נֵד נזְלִים. קָפְאוּ תְהמת בְּלֶב יָם: אָמַר אויֵב אֶרְדּף אַשּיג אֲחַלֵּק שָׁלָל. תִּמְלָאֵמו נַפְשִׁי. אָרִיק חַרְבִּי. תּורִישֵׁמו יָדִי: נָשַׁפְתָּ בְרוּחֲךָ כִּסָּמו יָם. צָלֲלוּ כַּעופֶרֶת בְּמַיִם אַדִּירִים: מִי כָמֹכָה בָּאֵלִם יְהוָה מִי כָּמֹכָה נֶאְדָּר בַּקֹּדֶשׁ נוֹרָא תְהִלֹּת עֹשֵׂה פֶלֶא: נָטִיתָ יְמִינְךָ תִּבְלָעֵמו אָרֶץ: נָחִיתָ בְחַסְדְּךָ עַם זוּ גָּאָלְתָּ. נֵהַלְתָּ בְעָזְּךָ אֶל נְוֵה קָדְשֶׁךָ: שָׁמְעוּ עַמִּים יִרְגָּזוּן. חִיל אָחַז ישְׁבֵי פְּלָשֶׁת: אָז נִבְהֲלוּ אַלּוּפֵי אֱדום. אֵילֵי מואָב יאחֲזֵמו רָעַד. נָמגוּ כּל ישְׁבֵי כְנָעַן: תִּפּל עֲלֵיהֶם אֵימָתָה וָפַחַד. בִּגְדל זְרועֲךָ יִדְּמוּ כָּאָבֶן. עַד יַעֲבר עַמְּךָ ה'. עַד יַעֲבר עַם זוּ קָנִיתָ: תְּבִאֵמו וְתִטָּעֵמו בְּהַר נַחֲלָתְךָ. מָכון לְשִׁבְתְּךָ פָּעַלְתָּ ה'. מִקְּדָשׁ. אֲדנָי כּונְנוּ יָדֶיךָ: ה' יִמְלךְ לְעלָם וָעֶד: ה' יִמְלךְ לְעלָם וָעֶד: ה' מַלְכוּתֵהּ קָאֵם לְעָלַם וּלְעָלְמֵי עָלְמַיָּא: כִּי בָא סוּס פַּרְעה בְּרִכְבּו וּבְפָרָשָׁיו בַּיָּם. וַיָּשֶׁב ה' עֲלֵיהֶם אֶת מֵי הַיָּם. וּבְנֵי יִשְׂרָאֵל הָלְכוּ בַיַּבָּשָׁה בְּתוךְ הַיָּם: כִּי לה' הַמְּלוּכָה. וּמושֵׁל בַּגּויִם: וְעָלוּ מושִׁיעִים בְּהַר צִיּון לִשְׁפּט אֶת הַר עֵשו. וְהָיְתָה לה' הַמְּלוּכָה: וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ. בַּיּום הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמו אֶחָד:"}]},{"id":"pesukei-dezimra-nishmat-kol-chai","heading":"Nishmat Kol Chai","group":"Pesukei Dezimra","lines":[{"he":"נִשְׁמַת כָּל חַי תְּבָרֵךְ אֶת שִׁמְךָ ה' אֱלהֵינוּ. וְרוּחַ כָּל בָּשר תְּפָאֵר וּתְרומֵם זִכְרְךָ מַלְכֵּנוּ תָּמִיד: מִן הָעולָם וְעַד הָעולָם אַתָּה אֵל. וּמִבַּלְעָדֶיךָ אֵין לָנוּ מֶלֶךְ גּואֵל וּמושִׁיעַ. פּודֶה וּמַצִּיל וּמְפַרְנֵס וּמְרַחֵם בְּכָל עֵת צָרָה וְצוּקָה. אֵין לָנוּ מֶלֶךְ עוזֵר וְסומֵךְ אֶלָּא אָתָּה: אֱלהֵי הָרִאשׁונִים וְהָאַחֲרונִים. אֱלוהַּ כָּל בְּרִיות. אֲדון כָּל תּולָדות. הַמְּהֻלָּל בְּרוב הַתִּשְׁבָּחות. הַמְּנַהֵג עולָמו בְּחֶסֶד וּבְרִיּותָיו בְּרַחֲמִים: וה' לא יָנוּם וְלא יִישָׁן. הַמְעורֵר יְשֵׁנִים. וְהַמֵּקִיץ נִרְדָּמִים. וְהַמֵּשיחַ אִלְמִים. וְהַמַּתִּיר אֲסוּרִים. וְהַסּומֵךְ נופְלִים. וְהַזּוקֵף כְּפוּפִים. לְךָ לְבַדְּךָ אֲנַחְנוּ מודִים: אִלּוּ פִינוּ מָלֵא שִׁירָה כַּיָּם. וּלְשׁונֵנוּ רִנָּה כַּהֲמון גַּלָּיו. וְשפְתותֵינוּ שֶׁבַח כְּמֶרְחֲבֵי רָקִיעַ. וְעֵינֵינוּ מְאִירות כַּשֶּׁמֶשׁ וְכַיָּרֵחַ. וְיָדֵינוּ פְרוּשות כְּנִשְׁרֵי שָׁמָיִם. וְרַגְלֵינוּ קַלּות כָּאַיָּלות. אֵין אֲנַחְנוּ מַסְפִּיקִים לְהודות לְךָ ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ. וּלְבָרֵךְ אֶת שְׁמֶךָ עַל אַחַת מֵאֶלֶף אַלְפֵי אֲלָפִים וְרִבֵּי רְבָבות פְּעָמִים. הַטּובות שֶׁעָשיתָ עִם אֲבותֵינוּ וְעִמָּנוּ: מִמִּצְרַיִם גְּאַלְתָּנוּ ה' אֱלהֵינוּ. וּמִבֵּית עֲבָדִים פְּדִיתָנוּ. בְּרָעָב זַנְתָּנוּ. וּבְשבָע כִּלְכַּלְתָּנוּ. מֵחֶרֶב הִצַּלְתָּנוּ. וּמִדֶּבֶר מִלַּטְתָּנוּ. וּמֵחֳלָיִם רָעִים וְנֶאֱמָנִים דִּלִּיתָנוּ: עַד הֵנָּה עֲזָרוּנוּ רַחֲמֶיךָ. וְלא עֲזָבוּנוּ חֲסָדֶיךָ וְאַל תִּטְּשֵׁנוּ ה' אֱלהֵינוּ לָנֶצַח: עַל כֵּן אֵבָרִים שֶׁפִּלַּגְתָּ בָּנוּ. וְרוּחַ וּנְשָׁמָה שֶׁנָּפַחְתָּ בְּאַפֵּינוּ. וְלָשׁון אֲשֶׁר שמְתָּ בְּפִינוּ. הֵן הֵם. יודוּ וִיבָרְכוּ וִישַׁבְּחוּ וִיפָאֲרוּ וִירומְמוּ וְיַעֲרִיצוּ וְיַקְדִּישׁוּ וְיַמְלִיכוּ אֶת שִׁמְךָ מַלְכֵּנוּ: כִּי כָל פֶּה לְךָ יודֶה. וְכָל לָשׁון לְךָ תִשָּׁבַע. וְכָל בֶּרֶךְ לְךָ תִכְרַע. וְכָל קומָה לְפָנֶיךָ תִשְׁתַּחֲוֶה. וְכָל לְּבָבות יִירָאוּךָ. וְכָל קֶרֶב וּכְלָיות יְזַמְּרוּ לִשְׁמֶךָ. כַּדָּבָר שֶׁכָּתוּב. כָּל עַצְמותַי תּאמַרְנָה ה' מִי כָמוךָ. מַצִּיל עָנִי מֵחָזָק מִמֶּנּוּ. וְעָנִי וְאֶבְיון מִגּוזְלו. מִי יִדְמֶה לָּךְ. וּמִי יִשְׁוֶה לָּךְ. וּמִי יַעֲרָךְ לָךְ. הָאֵל הַגָּדול הַגִּבּור וְהַנּורָא אֵל עֶלְיון. קונֵה שָׁמַיִם וָאָרֶץ: נְהַלֶּלְךָ וּנְשַׁבֵּחֲךָ וּנְפָאֶרְךָ וּנְבָרֵךְ אֶת שֵׁם קָדְשֶׁךָ. כָּאָמוּר, לְדָוִד, בָּרְכִי נַפְשִׁי אֶת ה'. וְכָל קְרָבַי אֶת שֵׁם קָדְשׁו:"}]},{"id":"pesukei-dezimra-shochen-ad","heading":"Shochen Ad","group":"Pesukei Dezimra","lines":[{"he":"ביום טוב ינגן החזן \"האל בתעצומות”: הָאֵל בְּתַעֲצֻמות עֻזֶּךָ. הַגָּדול בִּכְבוד שְׁמֶךָ. הַגִּבּור לָנֶצַח וְהַנּורָא בְּנורְאותֶיךָ: הַמֶּלֶךְ הַיּושֵׁב עַל כִּסֵּא רָם וְנִשּא:","note":true},{"he":"בשבת מתחיל החזן \"שוכן עד”: שׁוכֵן עַד מָרום וְקָדושׁ שְׁמו. וְכָתוּב רַנְּנוּ צַדִּיקִים בה'. לַיְשָׁרִים נָאוָה תְהִלָּה:","note":true},{"he":"בְּפִי יְשָׁרִים תִּתְהַלָּל. וּבְדִבְרֵי צַדִּיקִים תִּתְבָּרַךְ. וּבִלְשׁון חֲסִידִים תִּתְרומָם. וּבְקֶרֶב קְדושִׁים תִּתְקַדָּשׁ:"},{"he":"וּבְמַקְהֲלות רִבְבות עַמְּךָ בֵּית יִשרָאֵל. בְּרִנָּה יִתְפָּאַר שִׁמְךָ מַלְכֵּנוּ בְּכָל דּור וָדור. שֶׁכֵּן חובַת כָּל הַיְצוּרִים. לְפָנֶיךָ ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ. לְהודות לְהַלֵּל לְשַׁבֵּחַ לְפָאֵר לְרומֵם לְהַדֵּר לְבָרֵךְ לְעַלֵּה וּלְקַלֵּס. עַל כָּל דִּבְרֵי שִׁירות וְתִשְׁבְּחות דָּוִד בֶּן יִשַׁי עַבְדְּךָ מְשִׁיחֶךָ:"}]},{"id":"pesukei-dezimra-yishtabach","heading":"Yishtabach","group":"Pesukei Dezimra","lines":[{"he":"יִשְׁתַּבַּח שִׁמְךָ לָעַד מַלְכֵּנוּ. הָאֵל הַמֶּלֶךְ הַגָּדול וְהַקָּדושׁ בַּשָּׁמַיִם וּבָאָרֶץ. כִּי לְךָ נָאֶה ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ שִׁיר וּשְׁבָחָה. הַלֵּל וְזִמְרָה. עוז וּמֶמְשָׁלָה. נֶצַח גְּדֻלָּה וּגְבוּרָה. תְּהִלָּה וְתִפְאֶרֶת. קְדֻשָּׁה וּמַלְכוּת: בְּרָכות וְהודָאות מֵעַתָּה וְעַד עולָם: בָּרוּךְ אַתָּה ה'. אֵל מֶלֶךְ גָּדול בַּתִּשְׁבָּחות אֵל הַהודָאות. אֲדון הַנִּפְלָאות. הַבּוחֵר בְּשִׁירֵי זִמְרָה. מֶלֶךְ אֵל חֵי הָעולָמִים:","en":"May your name be praised forever, O our king. Great and holy god-emperor over the heavens and the earth! For songs of praise are pleasant to you, O LORD our god and god of our forefathers, and hymns of exaltation, and power and sovereignty, great and powerful victory, awesome wonder, and holy kingship, and blessings and thanks, from now until forever. Blessed are you O LORD, great god-emperor of praises, god of thanks, master of wonders, who chose hymnal songs, king and living god of all the world."}]},{"id":"pesukei-dezimra-psalm-130","heading":"Psalm 130","group":"Pesukei Dezimra","lines":[{"he":"בשבת תשובה אומרים מזמור זה פסוק בפסוק: שִׁיר הַמַּעֲלות. מִמַּעֲמַקִּים קְרָאתִיךָ ה': אֲדנָי שִׁמְעָה בְקולִי. תִּהְיֶינָה אָזְנֶיךָ קַשֻּׁבות לְקול תַּחֲנוּנָי: אִם עֲונות תִּשְׁמָר יָהּ. אֲדנָי מִי יַעֲמוד: כִּי עִמְּךָ הַסְּלִיחָה לְמַעַן תִּוָּרֵא: קִוִּיתִי ה'. קִוְּתָה נַפְשִׁי. וְלִדְבָרו הוחָלְתִּי: נַפְשִׁי לַאדנָי. מִשּׁומְרִים לַבּקֶר שׁומְרִים לַבּקֶר: יַחֵל יִשרָאֵל אֶל ה'. כִּי עִם ה' הַחֶסֶד וְהַרְבֵּה עִמּו פְדוּת: וְהוּא יִפְדֶּה אֶת יִשרָאֵל מִכּל עֲונותָיו:","note":true}]},{"id":"pesukei-dezimra-half-kaddish","heading":"Half Kaddish","group":"Pesukei Dezimra","lines":[{"he":"חזן: יִתְגַּדַּל וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. [קהל: אמן] בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵהּ בְּחַיֵּיכון וּבְיומֵיכון וּבְחַיֵּי דְכָל בֵּית יִשרָאֵל בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן: [קהל: אמן] קהל וחזן: יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא: יִתְבָּרַךְ וְיִשְׁתַּבַּח וְיִתְפָּאַר וְיִתְרומַם וְיִתְנַשּא וְיִתְהַדָּר וְיִתְעַלֶּה וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא. בְּרִיךְ הוּא. [קהל: בריך הוא:] לְעֵלָּא בעשי\"ת לְעֵלָּא לְעֵלָּא מִכָּל מִן כָּל בִּרְכָתָא וְשִׁירָתָא תֻּשְׁבְּחָתָא וְנֶחֱמָתָא דַּאֲמִירָן בְּעָלְמָא. וְאִמְרוּ אָמֵן: [קהל: אמן]","note":true}]},{"id":"blessings-of-the-shema-barchu","heading":"Barchu","group":"Blessings of the Shema","lines":[{"he":"חזן: בָּרְכוּ אֶת ה' הַמְברָךְ:","note":true},{"he":"קו”ח: בָּרוּךְ ה' הַמְברָךְ לְעולָם וָעֶד: בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. יוצֵר אור וּבורֵא חשֶׁךְ. עשה שָׁלום וּבורֵא אֶת הַכּל:","note":true}]},{"id":"blessings-of-the-shema-first-blessing-before-shema","heading":"First Blessing before Shema","group":"Blessings of the Shema","lines":[{"he":"כשחל יום טוב ביום חול אומרים \"המאיר לארץ\" במקום \"הכל יודוך\":","note":true},{"he":"הַכּל יוֹדוּךָ. וְהַכּל יְשַׁבְּחוּךָ. וְהַכּל יֹאמְרוּ אֵין קָדושׁ כַּיהוָה: הַכֹּל יְרומְמוּךָ סֶּלָה יוצֵר הַכֹּל: הָאֵל הַפּוֹתֵחַ בְּכָל יוֹם דַּלְתות שַׁעֲרֵי מִזְרָח. וּבוֹקֵעַ חַלּונֵי רָקִיעַ. מוֹצִיא חַמָּה מִמְּקוֹמָהּ. וּלְבָנָה מִמְּכוֹן שִׁבְתָּהּ. וּמֵאִיר לָעוֹלָם כֻּלּו וּלְיוֹשְׁבָיו. שֶׁבָּרָא בְּמִדַּת הָרַחֲמִים: הַמֵּאִיר לָאָרֶץ וְלַדָּרִים עָלֶיהָ בְּרַחֲמִים. וּבְטוּבוֹ מְחַדֵּשׁ בְּכָל יוֹם תָּמִיד. מַעֲשֵׂה בְּרֵאשִׁית: הַמֶּלֶךְ הַמְּרוֹמָם לְבַדּו מֵאָז. הַמְּשֻׁבָּח וְהַמְּפֹאָר וְהַמִּתְנַשֵּׂא מִיְּמוֹת עוֹלָם: אֱלֹהֵי עוֹלָם. בְּרַחֲמֶיךָ הָרַבִּים רַחֵם עָלֵינוּ. אֲדון עֻזֵּנוּ. צוּר מִשְׂגַּבֵּנוּ. מָגֵן יִשְׁעֵנוּ. מִשְׂגָּב בַּעֲדֵנוּ: אֵין כְּעֶרְכֶּךָ. וְאֵין זוּלָתֶךָ. אֶפֶס בִּלְתֶּךָ וּמִי דּוֹמֶה לָּךְ. אֵין כְּעֶרְכֶּךָ ה' אֱלֹהֵינוּ בָּעוֹלָם הַזֶּה. וְאֵין זוּלָתְךָ מַלְכֵּנוּ לְחַיֵּי הָעולָם הַבָּא. אֶפֶס בִּלְתְּךָ גּוֹאֲלֵנוּ לִימות הַמָּשִׁיחַ. וְאֵין דּוֹמֶה לְּךָ מוֹשִׁיעֶנּוּ לִתְחִיַּת הַמֵּתִים:"},{"he":"אֵל אָדוֹן עַל כָּל הַמַּעֲשִׂים. בָּרוּךְ וּמְבֹרַךְ בְּפִי כָּל נְּשָׁמָה. גָּדְלוֹ וְטוּבוֹ לִפְנֵי עוֹלָם. דַּעַת וּתְבוּנָה סוֹבְבִים אוֹתוֹ: הַמִּתְגָּאֶה עַל חַיּוֹת הַקּדֶשׁ. וְנֶהְדָּר בְּכָבוֹד עַל הַמֶּרְכָּבָה. זְכוּת וּמִישׁור לִפְנֵי כִסְאו. חֶסֶד וְרַחֲמִים מָלֵא כְבוֹדוֹ: טוֹבִים מְאוֹרוֹת שֶׁבָּרָא אֱלֹהֵינוּ. יְצָרָם בְּדַעַת בְּבִינָה וּבְהַשְׂכֵּל. כֹּחַ וּגְבוּרָה נָתַן בָּהֶם. לִהְיוֹת מוֹשְׁלִים בְּקֶרֶב תֵּבֵל: מְלֵאִים זִיו וּמְפִיקִים נוֹגָהּ. נָאֶה זִיוָם בְּכָל הָעוֹלָם. שְׂמֵחִים בְּצֵאתָם וְשָׂשִׂים בְּבוֹאָם. עוֹשִׂים בְּאֵימָה רְצוֹן קוֹנָם: פְּאֵר וְכָבוֹד נוֹתְנִים לִשְׁמוֹ. צָהֳלָה וְרִנָּה לְזֵכֶר מַלְכוּתוֹ. קָרָא לַשֶּׁמֶשׁ וַיִּזְרַח אוֹר. רָאָה וְהִתְקִין צוּרַת הַלְּבָנָה: שֶׁבַח נוֹתְנִים לוֹ כָּל צְבָא מָרוֹם. תִּפְאֶרֶת וּגְדֻלָּה שְׂרָפִים וְאוֹפַנִּים וְחַיּוֹת הַקֹּדֶשׁ:","en":"O God, master of all creation/blessed by the mouth of every soul/whose grandeur and wonder existed before anything/knowledge and understanding surround his splendor. Who rides upon the holy chayos/and in glorious beauty upon the Chariot/merit and uprightness before his throne/charity and mercy filled with his glory. Good are the lamps which our god created/he made them with knowledge and understanding and skill/power and strength he gave to them/to rule in the vicinity of the Earth. Filled with shine and imbued with rays/lovely their shine throughout the world/happy in their rising and joyous in their setting/doing in awe the will of their creator. Wonder and glory they give to his name/joy and celebration to the stature of his kingship/He called out to the sun, and it shone with light/He saw, and fixed the shape of the moon. All the heavenly host gives him praise/ the seraphs and the ophans, wonder and grandeur."},{"he":"לָאֵל אֲשֶׁר שָׁבַת מִכָּל הַמַּעֲשִׂים. בַּיּוֹם הַשְּׁבִיעִי הִתְעַלָּה וְיָשַׁב עַל כִּסֵּא כְבוֹדוֹ. תִּפְאֶרֶת עָטָה לְיוֹם הַמְּנוּחָה. עֹנֶג קָרָא לְיוֹם הַשַּׁבָּת. זֶה שֶׁבַח שֶׁל יוֹם הַשְּׁבִיעִי. שֶׁבּו שָׁבַת אֶל מִכָּל מְלַאכְתּו: וְיום הַשְּׁבִיעִי מְשַׁבֵּחַ וְאומֵר. מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת. טוֹב לְהוֹדוֹת לַה': לְפִיכָךְ יְפָאֲרוּ וִיבָרְכוּ לָאֵל כָּל יְצוּרָיו. שֶׁבַח יְקָר וּגְדֻלָּה. יִתְּנוּ לָאֵל מֶלֶךְ יוֹצֵר כָּל. הַמַּנְחִיל מְנוּחָה לְעַמּו יִשרָאֵל בִּקְדֻשָּׁתו בְּיום שַׁבַּת קדֶשׁ: שִׁמְךָ ה' אֱלֹהֵינוּ יִתְקַדַּשׁ. וְזִכְרְךָ מַלְכֵּנוּ יִתְפָּאַר. בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת: תִּתְבָּרַךְ מוֹשִׁיעֶנּוּ עַל שֶׁבַח מַעֲשי יָדֶיךָ. וְעַל מְאוֹרֵי אוֹר שֶׁעָשיתָ יְפָאֲרוּךָ סֶלָה:"},{"he":"כְּשֶׁחָל יו\"ט בְּיוֹם חֹל אוֹמְרִים הַמֵּאִיר לָאָרֶץ בִּמְקוֹם \"הַכֹּל יוֹדוּךְ\": הַמֵּאִיר לָאָרֶץ וְלַדָּרִים עָלֶיהָ בְּרַחֲמִים. וּבְטוּבוֹ מְחַדֵּשׁ בְּכָל יוֹם תָּמִיד מַעֲשֵׂה בְרֵאשִׁית. מָה רַבּוּ מַעֲשֶׂיךָ ה'. כֻּלָּם בְּחָכְמָה עָשִׂיתָ. מָלְאָה הָאָרֶץ קִנְיָנֶךָ: הַמֶּלֶךְ הַמְרומָם לְבַדּוֹ מֵאָז. הַמְשֻׁבָּח וְהַמְּפֹאָר וְהַמִּתְנַשֵּׂא מִיְּמוֹת עוֹלָם: אֱלֹהֵי עוֹלָם. בְּרַחֲמֶיךָ הָרַבִּים רַחֵם עָלֵינוּ. אֲדוֹן עֻזֵּנוּ. צוּר מִשְׂגַּבֵּנוּ. מָגֵן יִשְׁעֵנוּ. מִשְׂגָּב בַּעֲדֵנוּ: אֶל בָּרוּךְ גְּדוֹל דֵּעָה. הֵכִין וּפָעַל זָהֳרֵי חַמָּה. טוֹב יָצַר כָּבוֹד לִשְׁמוֹ. מְאוֹרוֹת נָתַן סְבִיבוֹת עֻזּוֹ. פִּנּוֹת צְבָאָיו קְדושִׁים. רוֹמְמֵי שַׁדַּי. תָּמִיד מְסַפְּרִים כְּבוֹד אֶל וּקְדֻשָּׁתו:","note":true},{"he":"תִּתְבָּרַךְ ה' אֱלֹהֵינוּ בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת עַל שֶׁבַח מַעֲשֵׂי יָדֶיךָ. וְעַל מְאוֹרֵי אוֹר שֶׁעָשִׂיתָ יְפָאֲרוּךָ סֶלָה:"},{"he":"תִּתְבָּרַךְ צוּרֵנוּ מַלְכֵּנוּ וְגואֲלֵנוּ בּוֹרֵא קְדוֹשִׁים. יִשְׁתַּבַּח שִׁמְךָ לָעַד מַלְכֵּנוּ יוֹצֵר מְשָׁרְתִים וַאֲשֶׁר מְשָׁרְתָיו כֻּלָּם עוֹמְדִים בְּרוּם עוֹלָם. וּמַשְׁמִיעִים בְּיִרְאָה יַחַד בְּקוֹל. דִּבְרֵי אֱלֹהִים חַיִּים וּמֶלֶךְ עוֹלָם: כֻּלָּם אֲהוּבִים. כֻּלָּם בְּרוּרִים. כֻּלָּם גִּבּורִים. וְכֻלָּם עוֹשִׂים בְּאֵימָה וּבְיִרְאָה רְצוֹן קוֹנָם: וְכֻלָּם פּוֹתְחִים אֶת פִּיהֶם בִּקְדֻשָּׁה וּבְטָהֳרָה. בְּשִׁירָה וּבְזִמְרָה. וּמְבָרְכִים וּמְשַׁבְּחִים וּמְפָאֲרִים וּמַעֲרִיצִים וּמַקְדִּישִׁים וּמַמְלִיכִים:"},{"he":"אֶת שֵׁם הָאֵל, הַמֶּלֶךְ הַגָּדול הַגִּבּוֹר וְהַנּוֹרָא קָדוֹשׁ הוּא. וְכֻלָּם מְקַבְּלִים עֲלֵיהֶם עֹל מַלְכוּת שָׁמַיִם זֶה מִזֶּה. וְנוֹתְנִים רְשׁוּת זֶה לָזֶה לְהַקְדִּישׁ לְיוֹצְרָם בְּנַחַת רוּחַ. בְּשָׂפָה בְרוּרָה וּבִנְעִימָה. קְדֻשָׁה כֻּלָּם כְּאֶחָד. עוֹנִים וְאוֹמְרִים בְּיִרְאָה: קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ ה' צְבָאוֹת. מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ: וְהָאופַנִּים וְחַיּוֹת הַקֹּדֶשׁ בְּרַעַשׁ גָּדול מִתְנַשּאִים לְעֻמַּת שְׂרָפִים. לְעֻמָּתָם מְשַׁבְּחִים וְאוֹמְרִים: בָּרוּךְ כְּבוד ה' מִמְּקוֹמוֹ:"},{"he":"לְאֵל בָּרוּךְ נְעִימוֹת יִתֵּנוּ. לְמֶּלֶךְ אֶל חַי וְקַיָּם זְמִירוֹת יֹאמֵרוּ וְתִשְׁבָּחות יַשְׁמִיעוּ. כִּי הוּא לְבַדּוֹ פּועֵל גְּבוּרוֹת. עוֹשֶׂה חֲדָשׁוֹת. בַּעַל מִלְחָמוֹת. זורֵעַ צְדָקוֹת. מַצְמִיחַ יְשׁוּעוֹת. בּורֵא רְפוּאוֹת. נורָא תְּהִלּוֹת. אֲדוֹן הַנִּפְלָאוֹת: הַמְחַדֵּשׁ בְּטוּבוֹ בְּכָל יוֹם תָּמִיד מַעֲשֵׂה בְרֵאשִׁית. כָּאָמוּר לְעֹשֶׂה אוּרִים גְּדלִים. כִּי לְעולָם חַסְדּו: אוֹר חָדָשׁ עַל צִיּון תָּאִיר וְנִזְכֶּה כֻלָּנוּ מְהֵרָה לְאוֹרוֹ. בָּרוּךְ אַתָּה ה'. יוֹצֵר הַמְּאוֹרוֹת:"}]},{"id":"blessings-of-the-shema-second-blessing-before-shema","heading":"Second Blessing before Shema","group":"Blessings of the Shema","lines":[{"he":"אַהֲבָה רַבָּה אֲהַבְתָּנוּ ה' אֱלהֵינוּ. חֶמְלָה גְּדולָה וִיתֵרָה חָמַלְתָּ עָלֵינוּ: אָבִינוּ מַלְכֵּנוּ. בַּעֲבוּר אֲבותֵינוּ שֶׁבָּטְחוּ בְךָ. וַתְּלַמְּדֵם חֻקֵּי חַיִּים כֵּן תְּחָנֵּנוּ וּתְלַמְּדֵנוּ: אָבִינוּ הָאָב הָרַחֲמָן. הַמְרַחֵם. רַחֵם עָלֵינוּ. וְתֵן בְּלִבֵּנוּ לְהָבִין וּלְהַשכִּיל. לִשְׁמעַ. לִלְמד וּלְלַמֵּד. לִשְׁמר וְלַעֲשות וּלְקַיֵּם אֶת כָּל דִּבְרֵי תַלְמוּד תּורָתֶךָ בְּאַהֲבָה: וְהָאֵר עֵינֵינוּ בְּתורָתֶךָ. וְדַבֵּק לִבֵּנוּ בְּמִצְותֶיךָ. וְיַחֵד לְבָבֵנוּ לְאַהֲבָה וּלְיִרְאָה אֶת שְׁמֶךָ. וְלא נֵבושׁ לְעולָם וָעֶד: כִּי בְשֵׁם קָדְשְׁךָ הַגָּדול וְהַנּורָא בָּטָחְנוּ. נָגִילָה וְנִשמְחָה בִּישׁוּעָתֶךָ: וַהֲבִיאֵנוּ לְשָׁלום מֵאַרְבַּע כַּנְפות הָאָרֶץ. וְתולִיכֵנוּ קומְמִיּוּת לְאַרְצֵנוּ: כִּי אֵל פּועֵל יְשׁוּעות אָתָּה. וּבָנוּ בָחַרְתָּ מִכָּל עַם וְלָשׁון.וְקֵרַבְתָּנוּ לְשִׁמְךָ הַגָּדול סֶלָה בֶּאֱמֶת: לְהודות לְךָ וּלְיַחֶדְךָ בְּאַהֲבָה: בָּרוּךְ אַתָּה ה'. הַבּוחֵר בְּעַמּו יִשרָאֵל בְּאַהֲבָה:","en":"(1) [With] great love You have loved us, Lord, our God; [with] great and abundant compassion have You had compassion upon us. Our Parent, our Sovereign — for the sake of our ancestors who trusted in You, and whom You taught laws of life, so [too] be gracious to us and teach us. Our Parent, merciful Parent, Who acts with compassion, have compassion on us and put into our hearts [comprehension] to understand and to discern, to listen, to learn and to teach, to keep, to practice, and to fulfill all the words of the teachings in Your Torah with love. And enlighten our eyes with Your Torah, and attach our hearts to Your mitzvot, and unify our hearts to love and revere Your Name; and may we never be embarrassed, for in Your holy Name— [which is] great and awe-inspiring— have we trusted; may we delight and rejoice in Your deliverance. Bring us in peace [wholeness] from the four corners of the earth; and lead us upright to our land. Because, You are the Almighty, Who performs acts of deliverance, and You have chosen us from among all peoples and languages, and You have brought us close to Your great Name in truth; to thank You and unify You with love. Blessed are You, Lord, Who chooses the people Israel with love."}]},{"id":"blessings-of-the-shema-shema","heading":"Shema","group":"Blessings of the Shema","lines":[{"he":"יחיד אומר: אֵל מֶלֶךְ נֶאֱמָן:","note":true},{"he":"שְׁמַע יִשרָאֵל ה' אֱלהֵינוּ ה' אֶחָד:"},{"he":"בלחש - בָּרוּךְ שֵׁם כְּבוד מַלְכוּתו לְעולָם וָעֶד:","note":true},{"he":"וְאָהַבְתָּ אֵת ה' אֱלהֶיךָ בְּכָל לְבָבְךָ וּבְכָל נַפְשְׁךָ וּבְכָל מְאדֶךָ: וְהָיוּ הַדְּבָרִים הָאֵלֶּה אֲשֶׁר אָנכִי מְצַוְּךָ הַיּום עַל לְבָבֶךָ: וְשִׁנַּנְתָּם לְבָנֶיךָ וְדִבַּרְתָּ בָּם בְּשִׁבְתְּךָ בְּבֵיתֶךָ וּבְלֶכְתְּךָ בַדֶּרֶךְ וּבְשָׁכְבְּךָ וּבְקוּמֶךָ: וּקְשַׁרְתָּם לְאות עַל יָדֶךָ וְהָיוּ לְטטָפת בֵּין עֵינֶיךָ: וּכְתַבְתָּם עַל מְזֻזות בֵּיתֶךָ וּבִשְׁעָרֶיךָ:"},{"he":"וְהָיָה אִם שָׁמעַ תִּשְׁמְעוּ אֶל מִצְותַי אֲשֶׁר אָנכִי מְצַוֶּה אֶתְכֶם הַיּום לְאַהֲבָה אֶת ה' אֱלהֵיכֶם וּלְעָבְדו בְּכָל לְבַבְכֶם וּבְכָל נַפְשְׁכֶם: וְנָתַתִּי מְטַר אַרְצְכֶם בְּעִתּו יורֶה וּמַלְקושׁ וְאָסַפְתָּ דְגָנֶךָ וְתִירשְׁךָ וְיִצְהָרֶךָ: וְנָתַתִּי עֵשב בְּשדְךָ לִבְהֶמְתֶּךָ וְאָכַלְתָּ וְשָׂבָעְתָּ: הִשָּׁמְרוּ לָכֶם פֶּן יִפְתֶּה לְבַבְכֶם וְסַרְתֶּם וַעֲבַדְתֶּם אֱלהִים אֲחֵרִים וְהִשְׁתַּחֲוִיתֶם לָהֶם: וְחָרָה אַף ה' בָּכֶם וְעָצַר אֶת הַשָּׁמַיִם וְלא יִהְיֶה מָטָר וְהָאֲדָמָה לא תִתֵּן אֶת יְבוּלָהּ וַאֲבַדְתֶּם מְהֵרָה מֵעַל הָאָרֶץ הַטּבָה אֲשֶׁר ה' נתֵן לָכֶם: וְשמְתֶּם אֶת דְּבָרַי אֵלֶּה עַל לְבַבְכֶם וְעַל נַפְשְׁכֶם וּקְשַׁרְתֶּם אתָם לְאות עַל יֶדְכֶם וְהָיוּ לְטוטָפת בֵּין עֵינֵיכֶם: וְלִמַּדְתֶּם אתָם אֶת בְּנֵיכֶם לְדַבֵּר בָּם בְּשִׁבְתְּךָ בְּבֵיתֶךָ וּבְלֶכְתְּךָ בַדֶּרֶךְ וּבְשָׁכְבְּךָ וּבְקוּמֶךָ: וּכְתַבְתָּם עַל מְזוּזות בֵּיתֶךָ וּבִשְׁעָרֶיךָ: לְמַעַן יִרְבּוּ יְמֵיכֶם וִימֵי בְנֵיכֶם עַל הָאֲדָמָה אֲשֶׁר נִשְׁבַּע ה' לַאֲבתֵיכֶם לָתֵת לָהֶם כִּימֵי הַשָּׁמַיִם עַל הָאָרֶץ:"},{"he":"וַיּאמֶר ה' אֶל משֶׁה לֵּאמר: דַּבֵּר אֶל בְּנֵי יִשרָאֵל וְאָמַרְתָּ אֲלֵהֶם וְעָשוּ לָהֶם צִיצִת עַל כַּנְפֵי בִגְדֵיהֶם לְדרתָם וְנָתְנוּ עַל צִיצִת הַכָּנָף פְּתִיל תְּכֵלֶת: וְהָיָה לָכֶם לְצִיצִת וּרְאִיתֶם אתו וּזְכַרְתֶּם אֶת כָּל מִצְות ה' וַעֲשיתֶם אתָם וְלא תָתוּרוּ אַחֲרֵי לְבַבְכֶם וְאַחֲרֵי עֵינֵיכֶם אֲשֶׁר אַתֶּם זנִים אַחֲרֵיהֶם: לְמַעַן תִּזְכְּרוּ וַעֲשיתֶם אֶת כָּל מִצְותָי וִהְיִיתֶם קְדשִׁים לֵאלהֵיכֶם: אֲנִי ה' אֱלהֵיכֶם אֲשֶׁר הוצֵאתִי אֶתְכֶם מֵאֶרֶץ מִצְרַיִם לִהְיות לָכֶם לֵאלהִים אֲנִי ה' אֱלהֵיכֶם. אֱמֶת:"},{"he":"הש\"ץ חוזר ואומר: ה' אֱלהֵיכֶם אֱמֶת:","note":true}]},{"id":"blessings-of-the-shema-blessing-after-shema","heading":"Blessing after Shema","group":"Blessings of the Shema","lines":[{"he":"וְיַצִּיב וְנָכון וְקַיָּם וְיָשָׁר וְנֶאֱמָן וְאָהוּב וְחָבִיב וְנֶחְמָד וְנָעִים וְנורָא וְאַדִּיר וּמְתֻקָּן וּמְקֻבָּל וְטוב וְיָפֶה הַדָּבָר הַזֶּה עָלֵינוּ לְעולָם וָעֶד: אֱמֶת. אֱלהֵי עולָם מַלְכֵּנוּ. צוּר יַעֲקב מָגֵן יִשְׁעֵנוּ. לְדר וָדר הוּא קַיָּם וּשְׁמו קַיָּם. וְכִסְאו נָכון. וּמַלְכוּתו וֶאֱמוּנָתו לָעַד קַיָּמֶת: וּדְבָרָיו חָיִים וְקַיָּמִים. נֶאֱמָנִים וְנֶחֱמָדִים לָעַד וּלְעולְמֵי עולָמִים."},{"he":"עַל אֲבותֵינוּ וְעָלֵינוּ. עַל בָּנֵינוּ וְעַל דּורותֵינוּ. וְעַל כָּל דּורות זֶרַע יִשרָאֵל עֲבָדֶיךָ: עַל הָרִאשׁונִים וְעַל הָאַחֲרונִים. דָּבָר טוב וְקַיָּם לְעולָם וָעֶד. אֱמֶת וֶאֱמוּנָה. חק וְלא יַעֲבר. אֱמֶת שָׁאַתָּה הוּא ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ. מַלְכֵּנוּ מֶלֶךְ אֲבותֵינוּ. גּואֲלֵנוּ גּואֵל אֲבותֵינוּ. יוצְרֵנוּ צוּר יְשׁוּעָתֵנוּ. פּודֵנוּ וּמַצִּילֵנוּ מֵעולָם שְׁמֶךָ. אֵין אֱלהִים זוּלָתֶךָ:"},{"he":"עֶזְרַת אֲבותֵינוּ אַתָּה הוּא מֵעולָם. מָגֵן וּמושִׁיעַ לִבְנֵיהֶם אַחֲרֵיהֶם בְּכָל דּור וָדור. בְּרוּם עולָם מושָׁבֶךָ. וּמִשְׁפָּטֶיךָ וְצִדְקָתְךָ עַד אַפְסֵי אָרֶץ: אַשְׁרֵי אִישׁ שֶׁיִּשְׁמַע לְמִצְותֶיךָ וְתורָתְךָ וּדְבָרְךָ יָשים עַל לִבּו: אֱמֶת. אַתָּה הוּא אָדון לְעַמֶּךָ. וּמֶלֶךְ גִּבּור לָרִיב רִיבָם: אֱמֶת. אַתָּה הוּא רִאשׁון וְאַתָּה הוּא אַחֲרון. וּמִבַּלְעָדֶיךָ אֵין לָנוּ מֶלֶךְ גּואֵל וּמושִׁיעַ: מִמִּצְרַיִם גְּאַלְתָּנוּ ה' אֱלהֵינוּ. וּמִבֵּית עֲבָדִים פְּדִיתָנוּ. כָּל בְּכורֵיהֶם הָרָגְתָּ. וּבְכורְךָ גָּאָלְתָּ. וְיַם סוּף בָּקַעְתָּ. וְזֵדִים טִבַּעְתָּ. וִידִידִים הֶעֱבַרְתָּ. וַיְכַסּוּ מַיִם צָרֵיהֶם. אֶחָד מֵהֶם לא נותָר: עַל זאת שִׁבְּחוּ אֲהוּבִים וְרומְמוּ אֵל. וְנָתְנוּ יְדִידִים זְמִירות שִׁירות וְתִשְׁבָּחות. בְּרָכות וְהודָאות לְמֶּלֶךְ אֵל חַי וְקַיָּם: רָם וְנִשּא. גָּדול וְנורָא. מַשְׁפִּיל גֵּאִים. וּמַגְבִּיהַּ שְׁפָלִים. מוצִיא אֲסִירִים. וּפודֶה עֲנָוִים. וְעוזֵר דַּלִּים. וְעונֶה לְעַמּו בְּעֵת שַׁוְּעָם אֵלָיו: תְּהִלּות לְאֵל עֶלְיון. בָּרוּךְ הוּא וּמְברָךְ. משֶׁה וּבְנֵי יִשרָאֵל לְךָ עָנוּ שִׁירָה בְּשמְחָה רַבָּה. וְאָמְרוּ כֻלָּם: מִי כָמכָה בָּאֵלִים ה'. מִי כָּמכָה נֶאְדָּר בַּקּדֶשׁ. נורָא תְהִלּת. עשה פֶלֶא: שִׁירָה חֲדָשָׁה שִׁבְּחוּ גְאוּלִים לְשִׁמְךָ עַל שפַת הַיָּם. יַחַד כֻּלָּם הודוּ וְהִמְלִיכוּ וְאְָמְרוּ: ה' יִמְלךְ לְעולָם וָעֶד: צוּר יִשרָאֵל. קוּמָה בְּעֶזְרַת יִשרָאֵל. וּפְדֵה כִנְאֻמֶךָ יְהוּדָה וְיִשרָאֵל. גּאֲלֵנוּ ה' צְבָאות שְׁמו קְדושׁ יִשרָאֵל: בָּרוּךְ אַתָּה ה'. גָּאַל יִשרָאֵל:"}]},{"id":"amidah-patriarchs","heading":"Patriarchs","group":"Amidah","lines":[{"he":"אֲדנָי שפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךָ:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ. אֱלהֵי אַבְרָהָם. אֱלהֵי יִצְחָק. וֵאלהֵי יַעֲקב. הָאֵל הַגָּדול הַגִּבּור וְהַנּורָא אֵל עֶלְיון. גּומֵל חֲסָדִים טובִים. וְקונֵה הַכּל. וְזוכֵר חַסְדֵּי אָבות. וּמֵבִיא גואֵל לִבְנֵי בְנֵיהֶם לְמַעַן שְׁמו בְּאַהֲבָה:"},{"he":"בעשי”ת: זָכְרֵנוּ לְחַיִּים. מֶלֶךְ חָפֵץ בַּחַיִּים. וְכָתְבֵנוּ בְּסֵפֶר הַחַיִּים. לְמַעַנְךָ אֱלהִים חַיִּים:","note":true},{"he":"מֶלֶךְ עוזֵר וּמושִׁיעַ וּמָגֵן: בָּרוּךְ אַתָּה ה', מָגֵן אַבְרָהָם:"}]},{"id":"amidah-divine-might","heading":"Divine Might","group":"Amidah","lines":[{"he":"אַתָּה גִּבּור לְעולָם אֲדנָי. מְחַיֵּה מֵתִים אַתָּה רַב לְהושִׁיעַ:"},{"he":"בחורף: מַשִּׁיב הָרוּחַ וּמורִיד הַגָּשֶּׁם:","note":true},{"he":"מְכַלְכֵּל חַיִּים בְּחֶסֶד. מְחַיֶּה מֵתִים בְּרַחֲמִים רַבִּים. סומֵךְ נופְלִים. וְרופֵא חולִים וּמַתִּיר אֲסוּרִים. וּמְקַיֵּם אֱמוּנָתו לִישֵׁנֵי עָפָר. מִי כָמוךָ בַּעַל גְּבוּרות וּמִי דומֶה לָּךְ. מֶלֶךְ מֵמִית וּמְחַיֶּה וּמַצְמִיחַ יְשׁוּעָה:"},{"he":"בעשי”ת: מִי כָמוךָ אַב הָרַחֲמִים. זוכֵר יְצוּרָיו לְחַיִּים בְּרַחֲמִים:","note":true},{"he":"וְנֶאֱמָן אַתָּה לְהַחֲיות מֵתִים: בָּרוּךְ אַתָּה ה', מְחַיֵּה הַמֵּתִים:"}]},{"id":"amidah-kedushah","heading":"Kedushah","group":"Amidah","lines":[{"he":"לחזרת הש\"ץ","note":true},{"he":"נְקַדֵּשׁ אֶת שִׁמְךָ בָּעוֹלָם כְּשֵׁם שֶׁמַּקְדִּישִׁים אוֹתוֹ בִּשְׁמֵי מָרוֹם. כַּכָּתוּב עַל יַד נְבִיאֶֽךָ. וְקָרָא זֶה אֶל זֶה וְאָמַר: קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ יְהֹוָה צְבָאוֹת מְלֹא כָל־הָאָֽרֶץ כְּבוֹדוֹ: אָז בְּקוֹל רַֽעַשׁ גָּדוֹל אַדִּיר וְחָזָק מַשְׁמִיעִים קוֹל מִתְנַשְּׂאִים לְעֻמַּת שְׂרָפִים. לְעֻמָּתָם בָּרוּךְ יֹאמֵֽרוּ: בָּרוּךְ כְּבוֹד יְהֹוָה מִמְּקוֹמוֹ: מִמְּקוֹמְךָ מַלְכֵּֽנוּ תוֹפִֽיעַ וְתִמְלוֹךְ עָלֵֽינוּ כִּי מְחַכִּים אֲנַחְנוּ לָךְ מָתַי תִּמְלוֹךְ בְּצִיּוֹן בְּקָרוֹב בְּיָמֵֽינוּ לְעוֹלָם וָעֶד תִּשְׁכּוֹן: תִּתְגַּדַּל וְתִתְקַדַּשׁ בְּתוֹךְ יְרוּשָׁלַֽיִם עִירְךָ לְדוֹר וָדוֹר וּלְנֵֽצַח נְצָחִים: וְעֵינֵֽינוּ תִרְאֶֽינָה מַלְכוּתֶֽךָ כַּדָּבָר הָאָמוּר בְּשִׁירֵי עֻזֶּֽךָ עַל יְדֵי דָוִד מְשִֽׁיחַ צִדְקֶֽךָ: יִמְלֹךְ יְהֹוָה לְעוֹלָם אֱלֹהַֽיִךְ צִיּוֹן לְדֹר וָדֹר הַלְלוּיָהּ:","note":true},{"he":"לְדוֹר וָדוֹר נַגִּיד גָּדְלֶֽךָ וּלְנֵֽצַח נְצָחִים קְדֻשָּׁתְךָ נַקְדִּישׁ וְשִׁבְחֲךָ אֱלֹהֵֽינוּ מִפִּֽינוּ לֹא יָמוּשׁ לְעוֹלָם וָעֶד כִּי אֵל מֶֽלֶךְ גָּדוֹל וְקָדוֹשׁ אָֽתָּה: בָּרוּךְ אַתָּה ה', הָאֵל בעשי”ת: הַמֶּלֶךְ הַקָּדושׁ:","note":true},{"he":"אַתָּה קָדושׁ וְשִׁמְךָ קָדושׁ וּקְדושִׁים בְּכָל יום יְהַלְּלוּךָ סֶּלָה: בָּרוּךְ אַתָּה ה', הָאֵל בעשי”ת: הַמֶּלֶךְ הַקָּדושׁ:"}]},{"id":"amidah-sanctity-of-the-day","heading":"Sanctity of the Day","group":"Amidah","lines":[{"he":"יִשמַח משֶׁה בְּמַתְּנַת חֶלְקו. כִּי עֶבֶד נֶאֱמָן קָרָאתָ לּו. כְּלִיל תִּפְאֶרֶת בְּראשׁו נָתַתָּ. בְּעָמְדו לְפָנֶיךָ עַל הַר סִינַי. וּשְׁנֵי לֻחות אֲבָנִים הורִיד בְּיָדו. וְכָתוּב בָּהֶם שְׁמִירַת שַׁבָּת. וְכֵן כָּתוּב בְּתורָתֶךָ:","en":"Moses rejoiced in the gift of his portion, for \"trusted servant\" You called him. A crown of glory You placed on his head, as he stood before You on Mount Sinai. And two tablets of stone he brought down in his hand, and on them You wrote the keeping of Shabbat. And so it is written in your Torah:"},{"he":"וְשָׁמְרוּ בְנֵי יִשרָאֵל אֶת הַשַּׁבָּת. לַעֲשות אֶת הַשַּׁבָּת לְדרתָם בְּרִית עולָם: בֵּינִי וּבֵין בְּנֵי יִשרָאֵל אות הִיא לְעולָם. כִּי שֵׁשֶׁת יָמִים עָשה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. וּבַיּום הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ:"},{"he":"וְלא נְתַתּו ה' אֱלהֵינוּ לְגויֵי הָאֲרָצות. וְלא הִנְחַלְתּו מַלְכֵּנוּ לְעובְדֵי פְסִילִים. וְגַם בִּמְנוּחָתו לא יִשְׁכְּנוּ עֲרֵלִים. כִּי לְיִשרָאֵל עַמְּךָ נְתַתּו בְּאַהֲבָה. לְזֶרַע יַעֲקב אֲשֶׁר בָּם בָּחָרְתָּ: עַם מְקַדְּשֵׁי שְׁבִיעִי. כֻּלָּם יִשבְּעוּ וְיִתְעַנְּגוּ מִטּוּבֶךָ. וּבַשְּׁבִיעִי רָצִיתָ בּו וְקִדַּשְׁתּו. חֶמְדַת יָמִים אותו קָרָאתָ. זֵכֶר לְמַעֲשה בְרֵאשִׁית:"},{"he":"אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ רְצֵה בִמְנוּחָתֵנוּ. קַדְּשֵׁנוּ בְּמִצְותֶיךָ וְתֵן חֶלְקֵנוּ בְּתורָתֶךָ. שבְּעֵנוּ מִטּוּבֶךָ וְשמְּחֵנוּ בִּישׁוּעָתֶךָ וְטַהֵר לִבֵּנוּ לְעָבְדְּךָ בֶּאֱמֶת. וְהַנְחִילֵנוּ ה' אֱלהֵינוּ בְּאַהֲבָה וּבְרָצון שַׁבַּת קָדְשֶׁךָ. וְיָנוּחוּ בו יִשרָאֵל מְקַדְּשֵׁי שְׁמֶךָ: בָּרוּךְ אַתָּה ה' מְקַדֵּשׁ הַשַּׁבָּת:"}]},{"id":"amidah-temple-service","heading":"Temple Service","group":"Amidah","lines":[{"he":"רְצֵה ה' אֱלהֵינוּ בְּעַמְּךָ יִשרָאֵל וּבִתְפִלָּתָם וְהָשֵׁב אֶת הָעֲבודָה לִדְבִיר בֵּיתֶךָ. וְאִשֵּׁי יִשרָאֵל וּתְפִלָּתָם. בְּאַהֲבָה תְקַבֵּל בְּרָצון. וּתְהִי לְרָצון תָּמִיד עֲבודַת יִשרָאֵל עַמֶּךָ:"},{"he":"בראש חודש ובחול המועד אומרים זה: אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ. יַעֲלֶה וְיָבוא וְיַגִּיעַ. וְיֵרָאֶה וְיֵרָצֶה וְיִשָּׁמַע. וְיִפָּקֵד וְיִזָּכֵר זִכְרונֵנוּ וּפִקְדונֵנוּ וְזִכְרון אֲבותֵינוּ. וְזִכְרון מָשִׁיחַ בֶּן דָּוִד עַבְדֶּךָ. וְזִכְרון יְרוּשָׁלַיִם עִיר קָדְשֶׁךָ. וְזִכְרון כָּל עַמְּךָ בֵּית יִשרָאֵל. לְפָנֶיךָ. לִפְלֵיטָה לְטובָה. לְחֵן וּלְחֶסֶד וּלְרַחֲמִים. לְחַיִּים וּלְשָׁלום בְּיום: בראש חדש - ראשׁ הַחדֶשׁ: בפסח - חַג הַמַּצּות: בסוכות - חַג הַסֻּכּות: הַזֶּה. זָכְרֵנוּ ה' אֱלהֵינוּ בּו לְטובָה. וּפָקְדֵנוּ בו לִבְרָכָה. וְהושִׁיעֵנוּ בו לְחַיִּים. וּבִדְבַר יְשׁוּעָה וְרַחֲמִים חוּס וְחָנֵּנוּ וְרַחֵם עָלֵינוּ וְהושִׁיעֵנוּ. כִּי אֵלֶיךָ עֵינֵינוּ. כִּי אֵל מֶלֶךְ חַנּוּן וְרַחוּם אָתָּה:","note":true},{"he":"וְתֶחֱזֶינָה עֵינֵינוּ בְּשׁוּבְךָ לְצִיּון בְּרַחֲמִים: בָּרוּךְ אַתָּה ה', הַמַּחֲזִיר שְׁכִינָתו לְצִיּון:"}]},{"id":"amidah-thanksgiving","heading":"Thanksgiving","group":"Amidah","lines":[{"he":"מודִים אֲנַחְנוּ לָךְ. שָׁאַתָּה הוּא ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ לְעולָם וָעֶד. צוּר חַיֵּינוּ. מָגֵן יִשְׁעֵנוּ אַתָּה הוּא לְדור וָדור: נודֶה לְּךָ וּנְסַפֵּר תְּהִלָּתֶךָ עַל חַיֵּינוּ הַמְּסוּרִים בְּיָדֶךָ. וְעַל נִשְׁמותֵינוּ הַפְּקוּדות לָךְ. וְעַל נִסֶּיךָ שֶׁבְּכָל יום עִמָּנוּ. וְעַל נִפְלְאותֶיךָ וְטובותֶיךָ שֶׁבְּכָל עֵת. עֶרֶב וָבקֶר וְצָהֳרָיִם: הַטּוב כִּי לא כָלוּ רַחֲמֶיךָ. וְהַמְרַחֵם כִּי לא תַמּוּ חֲסָדֶיךָ. מֵעולָם קִוִּינוּ לָךְ:"},{"he":"מודים דרבנן: מודִים אֲנַחְנוּ לָךְ. שָׁאַתָּה הוּא ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ. אֱלהֵי כָל בָּשר. יוצְרֵנוּ יוצֵר בְּרֵאשִׁית. בְּרָכות וְהודָאות לְשִׁמְךָ הַגָּדול וְהַקָּדושׁ. עַל שֶׁהֶחֱיִיתָנוּ וְקִיַּמְתָּנוּ. כֵּן תְּחַיֵּנוּ וּתְקַיְּמֵנוּ. וְתֶאֱסוף גָּלֻיּותֵינוּ לְחַצְרות קָדְשֶׁךָ. לִשְׁמור חֻקֶּיךָ. וְלַעֲשות רְצונֶךָ. וּלְעָבְדְךָ בְּלֵבָב שָׁלֵם. עַל שֶׁאֲנַחְנוּ מודִים לָךְ. בָּרוּךְ אֵל הַהודָאות:","note":true},{"he":"בחנוכה ופורים אומרים כאן ועל הנסים: עַל הַנִּסִּים וְעַל הַפֻּרְקָן וְעַל הַגְּבוּרות וְעַל הַתְּשׁוּעות וְעַל הַמִּלְחָמות שֶׁעָשיתָ לַאֲבותֵינוּ בַּיָּמִים הָהֵם בִּזְּמַן הַזֶּה:","note":true},{"he":"לחנוכה: בִּימֵי מַתִּתְיָהוּ בֶּן יוחָנָן כּהֵן גָּדול חַשְׁמונַאִי וּבָנָיו. כְּשֶׁעָמְדָה מַלְכוּת יָוָן הָרְשָׁעָה עַל עַמְּךָ יִשרָאֵל לְהַשְׁכִּיחָם תּורָתֶךָ וּלְהַעֲבִירָם מֵחֻקֵּי רְצונֶךָ: וְאַתָּה בְּרַחֲמֶיךָ הָרַבִּים עָמַדְתָּ לָהֶם בְּעֵת צָרָתָם. רַבְתָּ אֶת רִיבָם. דַנְתָּ אֶת דִּינָם. נָקַמְתָּ אֶת נִקְמָתָם. מָסַרְתָּ גִבּורִים בְּיַד חַלָּשִׁים. וְרַבִּים בְּיַד מְעַטִּים. וּטְמֵאִים בְּיַד טְהורִים. וּרְשָׁעִים בְּיַד צַדִּיקִים. וְזֵדִים בְּיַד עוסְקֵי תורָתֶךָ. וּלְךָ עָשיתָ שֵׁם גָּדול וְקָדושׁ בְּעולָמֶךָ. וּלְעַמְּךָ יִשרָאֵל עָשיתָ תְּשׁוּעָה גְדולָה וּפֻרְקָן כְּהַיּום הַזֶּה: וְאַחַר כֵּן בָּאוּ בָנֶיךָ לִדְבִיר בֵּיתֶךָ. וּפִנּוּ אֶת הֵיכָלֶךָ. וְטִהֲרוּ אֶת מִקְדָּשֶׁךָ. וְהִדְלִיקוּ נֵרות בְּחַצְרות קָדְשֶׁךָ. וְקָבְעוּ שְׁמונַת יְמֵי חֲנֻכָּה אֵלּוּ. לְהודות וּלְהַלֵּל לְשִׁמְךָ הַגָּדול:"},{"he":"לפורים: בִּימֵי מָרְדְּכַי וְאֶסְתֵּר בְּשׁוּשַׁן הַבִּירָה. כְּשֶׁעָמַד עֲלֵיהֶם הָמָן הָרָשָׁע. בִּקֵּשׁ לְהַשְׁמִיד לַהֲרוג וּלְאַבֵּד אֶת כָּל הַיְּהוּדִים מִנַּעַר וְעַד זָקֵן טַף וְנָשִׁים בְּיום אֶחָד. בִּשְׁלשָׁה עָשר לְחדֶשׁ שְׁנֵים עָשר. הוּא חדֶשׁ אֲדָר. וּשְׁלָלָם לָבוז: וְאַתָּה בְּרַחֲמֶיךָ הָרַבִּים. הֵפַרְתָּ אֶת עֲצָתו. וְקִלְקַלְתָּ אֶת מַחֲשַׁבְתּו. וַהֲשֵׁבותָ לּו גְּמוּלו בְּראשׁו. וְתָלוּ אותו וְאֶת בָּנָיו עַל הָעֵץ. וְעָשיתָ עִמָּהֶם נֵס וָפֶלֶא וְנודֶה לְשִׁמְךָ הַגָּדול סֶלָה:"},{"he":"וְעַל כֻּלָּם יִתְבָּרַךְ וְיִתְרומַם שִׁמְךָ מַלְכֵּנוּ תָּמִיד לְעולָם וָעֶד:"},{"he":"בעשי\"ת - וּכְתב לְחַיִּים טובִים כָּל בְּנֵי בְרִיתֶךָ:","note":true},{"he":"וְכל הַחַיִּים יודוּךָ סֶּלָה וִיהַלְלוּ אֶת שִׁמְךָ בֶּאֱמֶת. הָאֵל יְשׁוּעָתֵנוּ וְעֶזְרָתֵנוּ סֶלָה. בָּרוּךְ אַתָּה ה', הַטּוב שִׁמְךָ וּלְךָ נָאֶה לְהודות:"}]},{"id":"amidah-birkat-kohanim","heading":"Birkat Kohanim","group":"Amidah","lines":[{"he":"ברכת כהנים בחזרת התפלה אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ. בָּרְכֵנוּ בַּבְּרָכָה הַמְשֻׁלֶּשֶׁת בַּתּורָה הַכְּתוּבָה עַל יְדֵי משֶׁה עַבְדֶּךָ. הָאֲמוּרָה מִפִּי אַהֲרן וּבָנָיו כּהֲנִים עַם קְדושֶׁךָ. כָּאָמוּר:","note":true},{"he":"יְבָרֶכְךָ ה' וְיִשְׁמְרֶךָ: יָאֵר ה' פָּנָיו אֵלֶיךָ וִיחֻנֶּךָּ: יִשּא ה' פָּנָיו אֵלֶיךָ וְיָשם לְךָ שָׁלום:"}]},{"id":"amidah-peace","heading":"Peace","group":"Amidah","lines":[{"he":"שים שָׁלום טובָה וּבְרָכָה. חֵן וָחֶסֶד וְרַחֲמִים עָלֵינוּ וְעַל כָּל יִשרָאֵל עַמֶּךָ. בָּרְכֵנוּ אָבִינוּ כֻּלָּנוּ כְּאֶחָד בְּאור פָּנֶיךָ. כִּי בְאור פָּנֶיךָ נָתַתָּ לָּנוּ ה' אֱלהֵינוּ תּורַת חַיִּים וְאַהֲבַת חֶסֶד. וּצְדָקָה וּבְרָכָה וְרַחֲמִים וְחַיִּים וְשָׁלום. וְטוב בְּעֵינֶיךָ לְבָרֵךְ אֶת כָּל עַמְּךָ יִשרָאֵל בְּכָל עֵת וּבְכָל שָׁעָה בִּשְׁלומֶךָ:"},{"he":"בָּרוּךְ אַתָּה ה', הַמְבָרֵךְ אֶת עַמּו יִשרָאֵל בַּשָּׁלום:"}]},{"id":"amidah-concluding-passage","heading":"Concluding Passage","group":"Amidah","lines":[{"he":"יִהְיוּ לְרָצון אִמְרֵי פִי וְהֶגְיון לִבִּי לְפָנֶיךָ. ה' צוּרִי וְגואֲלִי: אֱלהַי. נְצר לְשׁונִי מֵרָע וּשפָתַי מִדַּבֵּר מִרְמָה. וְלִמְקַלְלַי נַפְשִׁי תִדּם. וְנַפְשִׁי כֶּעָפָר לַכּל תִּהְיֶה. פְּתַח לִבִּי בְּתורָתֶךָ. וּבְמִצְותֶיךָ תִּרְדּף נַפְשִׁי. וְכָל הַחושְׁבִים עָלַי רָעָה. מְהֵרָה הָפֵר עֲצָתָם וְקַלְקֵל מַחֲשַׁבְתָּם: עֲשה לְמַעַן שְׁמֶךָ. עֲשה לְמַעַן יְמִינֶךָ. עֲשה לְמַעַן קְדֻשָּׁתֶךָ. עֲשה לְמַעַן תּורָתֶךָ. לְמַעַן יֵחָלְצוּן יְדִידֶיךָ הושִׁיעָה יְמִינְךָ וַעֲנֵנִי: יִהְיוּ לְרָצון אִמְרֵי פִי וְהֶגְיון לִבִּי לְפָנֶיךָ. ה' צוּרִי וְגואֲלִי: עשה שָׁלום בעשי\"ת - הַשָּׁלום בִּמְרומָיו. הוּא יַעֲשה שָׁלום עָלֵינוּ וְעַל כָּל יִשרָאֵל. וְאִמְרוּ אָמֵן:"},{"he":"יְהִי רָצון מִלְּפָנֶיךָ ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ. שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ בִּמְהֵרָה בְיָמֵינוּ. וְתֵן חֶלְקֵנוּ בְּתורָתֶךָ: וְשָׁם נַעֲבָדְךָ בְּיִרְאָה כִּימֵי עולָם וּכְשָׁנִים קַדְמונִיות: וְעָרְבָה לה' מִנְחַת יְהוּדָה וִירוּשָׁלָיִם. כִּימֵי עולָם וּכְשָׁנִים קַדְמונִיות:"}]},{"id":"amidah-kaddish-shalem","heading":"Kaddish Shalem","group":"Amidah","lines":[{"he":"יִתְגַּדַּל וְיִתְקַדַּשׁ גרסת הגר\"א: יִתְגַּדֵּל וְיִתְקַדֵּשׁ שְׁמֵהּ רַבָּא. ועונים: אמן בְּעָלְמָא דִי בְרָא כִּרְעוּתֵהּ. וְיַמְלִיךְ מַלְכוּתֵהּ, בְּחַיֵיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵי דְּכָל בֵּית יִשְׂרָאֵל, בַּעֲגַלָא וּבִזְמַן קָרִיב וְאִמְרוּ אָמֵן: הקהל עונה: אמן. יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָא: יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָא: יִתְבָּרַךְ וְיִשְׁתַּבַּח וְיִתְפָּאַר וְיִתְרוֹמַם וְיִתְנַשֵּׂא וְיִתְהַדָּר וְיִתְעַלֶּה וְיִתְהַלָּל , שְׁמֵהּ דְּקוּדְשָׁא בְּרִיךְ הוּא ועונים: בְּרִיךְ הוּא לְעֵילָא מִן כָּל בעשרת ימי תשובה במקום לְעֵילָא מִן כָּל: לְעֵילָא וּלְעֵילָא מִכָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחָמָתָא, דַאֲמִירָן בְּעָלְמָא. וְאִמְרוּ אָמֵן: ועונים: אמן קהל: קַבֵּל בְּרַחֲמִים וּבְרָצון אֶת תְּפִלָּתֵנוּ: תִּתְקַבַּל צְלוֹתְהוֹן וּבָעוּתְהוֹן דְּכָל בֵּית יִשְׂרָאֵל קֳדָם אֲבוּהוֹן דִּי בִשְׁמַיָּא , וְאִמְרוּ אָמֵן. ועונים: אמן קהל: יְהִי שֵׁם יְהוָה מְברָךְ מֵעַתָּה וְעַד עולָם: יְהֵא שְׁלָמָא רַבָּא מִן שְׁמַיָא וְחַיִּים עָלֵינו וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן: ועונים: אמן קהל: עֶזְרִי מֵעִם יְהוָה עשֵׂה שָׁמַיִם וָאָרֶץ: עוֹשֶׂה שָׁלוֹם בעשרת ימי תשובה: השלום בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל, וְאִמְרוּ אָמֵן: ועונים: אמן"}]},{"id":"torah-reading-removing-the-torah-from-the-ark-ein-kamocha","heading":"Ein Kamocha","group":"Torah Reading · Removing the Torah from the Ark","lines":[{"he":"קודם פתיחת הארון אומרים: אֵין כָּמוךָ בָאֱלהִים אֲדנָי. וְאֵין כְּמַעֲשיךָ: מַלְכוּתְךָ מַלְכוּת כָּל עולָמִים. וּמֶמְשַׁלְתְּךָ בְּכָל דּור וָדור: ה' מֶלֶךְ. ה' מָלָךְ. ה' יִמְלךְ לְעולָם וָעֶד: ה' עז לְעַמּו יִתֵּן. ה' יְבָרֵךְ אֶת עַמּו בַשָּׁלום:","en":"There is none like You among the gods, Adonai, and nothing like Your works. Your kingship is a kingship of all worlds, and Your reign is with generation upon generation. The Eternal rules. The Eternal has ruled. The Eternal will rule forever and ever. The Eternal will give strength to the Eternal's people. The Eternal will bless the Eternal's people with peace.","note":true},{"he":"אַב הָרַחֲמִים. הֵיטִיבָה בִרְצונְךָ אֶת צִיּון. תִּבְנֶה חומות יְרוּשָׁלָיִם: כִּי בְךָ לְבַד בָּטָחְנוּ. מֶלֶךְ אֵל רָם וְנִשּא אֲדון עולָמִים:","en":"Father of compassion, do well with Your will upon Zion. Build the walls of Jerusalem, for in You alone we have trusted, King, uplifted and exalted Divinity, master of infinitudes."}]},{"id":"torah-reading-removing-the-torah-from-the-ark-vayehi-binsoa","heading":"Vayehi Binsoa","group":"Torah Reading · Removing the Torah from the Ark","lines":[{"he":"כשפותחין ארון הקודש אומרים: וַיְהִי בִּנְסעַ הָאָרן וַיּאמֶר משֶׁה. קוּמָה ה' וְיָפֻצוּ איְבֶיךָ. וְיָנֻסוּ מְשנְאֶיךָ מִפָּנֶיךָ: כִּי מִצִּיּון תֵּצֵא תורָה. וּדְבַר ה' מִירוּשָׁלָיִם: בָּרוּךְ שֶׁנָּתַן תּורָה לְעַמּו יִשרָאֵל בִּקְדֻשָּׁתו:","en":"It happened upon the journeying of the Ark, Moses said, “Rise, Eternal,” and Your enemies were dispersed, and Your foes were put to flight from before You. For the Torah will come forth from Zion, and the word of the Eternal from Jerusalem. Blessed is the one who gave Torah to [the] people of Israel in holiness.","note":true},{"he":"ביו\"ט כשחל בחול, ויום כפור, ובהושענא רבה אומרים: ה' ה'. אֵל רַחוּם וְחַנּוּן. אֶרֶךְ אַפַּיִם וְרַב חֶסֶד וֶאֱמֶת: נצֵר חֶסֶד לָאֲלָפִים. נשא עָון וָפֶשַׁע וְחַטָּאָה וְנַקֵּה. ג”פ:","note":true},{"he":"לשלוש רגלים ולשמיני עצרת: רִבּונו שֶׁל עולָם מַלֵּא מִשְׁאֲלות לִבִּי לְטובָה וְהָפֵק רְצונִי וְתֵן שְׁאֵלָתִי. וְזַכֵּה לִי פב\"פ וְאִשְׁתִּי וּבָנַי וּבְנותַי וְכָל בְּנֵי בֵיתִי לַעֲשות רְצונְךָ בְּלֵבָב שָׁלֵם. וּמַלְּטֵנוּ מִיֵּצֶר הָרָע וְתֵן חֶלְקֵנוּ בְּתורָתֶךָ. וְזַכֵּנוּ שֶׁתִּשְׁרֶה שְׁכִינָתְךָ עָלֵינוּ. וְהופַע עָלֵינוּ רוּחַ חָכְמָה וּבִינָה. וְיִתְקַיֵּם בָּנוּ מִקְרָא שֶׁכָּתוּב וְנָחָה עָלָיו רוּחַ ה' רוּחַ חָכְמָה וּבִינָה רוּחַ עֵצָה וּגְבוּרָה רוּחַ דַּעַת וְיִרְאַת ה':"},{"he":"וּבְכֵן יְהִי רָצון מִלְּפָנֶיךָ ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ. שֶׁתְּזַכֵּנוּ לַעֲשות מַעֲשים טובִים בְּעֵינֶיךָ וְלָלֶכֶת בְּדַרְכֵי יְשָׁרִים לְפָנֶיךָ. וְקַדְּשֵׁנוּ בִּקְדֻשָׁתֶךָ כְּדֵי שֶׁנִּזְכֶּה לְחַיִּים טובִים וַאֲרוּכִּים וּלְחַיֵּי הָעולָם הַבָּא. וְתִשְׁמְרֵנוּ מִמַּעֲשּים רָעִים וּמִשָׁעות רָעות הַמִתְרַגְשׁות לָבא לְעולָם. וְהַבּוטֵחַ בה' חֶסֶד יְסובְבֶנְּהוּ אָמֵן:"},{"he":"וַאֲנִי תְפִלָּתִי לְךָ ה' עֵת רָצון אֱלהִים בְּרָב חַסְדֶּךָ עֲנֵנִי בֶּאֱמֶת יִשְׁעֶךָ. ג”פ:"}]},{"id":"torah-reading-removing-the-torah-from-the-ark-berich-shmei","heading":"Berich Shmei","group":"Torah Reading · Removing the Torah from the Ark","lines":[{"he":"בְּרִיךְ שְׁמֵהּ דְּמָרֵא עָלְמָא. בְּרִיךְ כִּתְרַךְ וְאַתְּרָךְ. יְהֵא רְעוּתָךְ עִם עַמָּךְ יִשְׂרָאֵל לְעָלַם. וּפוּרְקָן יְמִינָךְ אַחֲזֵי לְעַמָּךְ בְּבֵית מַקְדְּשָׁךְ. וּלְאַמְטוֹיֵי לַנָא מִטּוּב נְהוֹרָךְ וּלְקַבֵּל צְלוֹתַנָא בְּרָחֲמִין. יְהֵא רַעֲוָא קָדָמָךְ דְּתוֹרִיךְ לָן חַיִּין בְּטִיְּבוּ. וְלֶהֱוֵי אֲנָא פְּקִידָא בְּגוֹ צַדִּיקַיָּא. לְמִרְחַם עָלַי וּלְמִנְּטַר יָתִי וְיָת כָּל דִּי לִי וְדִי לְעַמָּךְ יִשְׂרָאֵל. אַנְתְּ הוּא זָן לְכַלָּא וּמְפַרְנֵס לְכַלָּא. אַנְתְּ הוּא שַׁלִּיט עַל כַּלָּא. אַנְתְּ הוּא דְּשַׁלִּיט עַל מַלְכַיָּא. וּמַלְכוּתָא דִּילָךְ הִיא. אֲנָא עַבְדָּא דְּקֻדְשָׁא בְּרִיךְ הוּא דְּסַגִּידְנָא קַמֵּהּ וּמִקַּמֵּי דִּיקָר אוֹרָיְתֵהּ בְּכָל עִדָּן וְעִדָּן. לָא עַל אֱנָשׁ רָחִיצְנָא וְלָא עַל בַּר אֱלָהִין סַמִּיכְנָא. אֶלָּא בֶּאֱלָהָא דִּשְׁמַיָּא. דְּהוּא אֱלָהָא קְשׁוֹט וְאוֹרָיְתֵהּ קְשׁוֹט וּנְבִיאוֹהִי קְשׁוֹט. וּמַסְגֵּא לְמֶעְבַּד טָבְוָן וּקְשׁוֹט. בֵּהּ אֲנָא רָחִיץ. וְלִשְׁמֵהּ קַדִּישָׁא יַקִּירָא אֲנָא אֵמַר תֻּשְׁבְּחָן. יְהֵא רַעֲוָא קָדָמָךְ דְּתִפְתַּח לִבָּאִי בְּאוֹרָיְתָא. וְתַשְׁלִים מִשְׁאָלִין דְּלִבָּאִי וְלִבָּא דְּכָל עַמָּךְ יִשְׂרָאֵל. לְטָב וּלְחַיִּין וְלִשְׁלַם:"}]},{"id":"torah-reading-removing-the-torah-from-the-ark-shema-yisrael-gadlu","heading":"Shema Yisrael (Gadlu)","group":"Torah Reading · Removing the Torah from the Ark","lines":[{"he":"חו”ק שְׁמַע יִשרָאֵל ה' אֱלהֵינוּ ה' אֶחָד:","note":true},{"he":"חו”ק אֶחָד אֱלהֵינוּ. גָּדול אֲדונֵינוּ. קָדושׁ בראש השנה ויו\"כ ובהו”ר: וְנורָא שְׁמו:","note":true},{"he":"חזן: גַּדְּלוּ לה' אִתִּי. וּנְרומְמָה שְׁמו יַחְדָּו:","note":true}]},{"id":"torah-reading-removing-the-torah-from-the-ark-lecha-hashem","heading":"Lecha Hashem","group":"Torah Reading · Removing the Torah from the Ark","lines":[{"he":"קהל: לְךָ ה' הַגְּדֻלָּה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְהַנֵּצַח וְהַהוד כִּי כל בַּשָּׁמַיִם וּבָאָרֶץ: לְךָ ה' הַמַּמְלָכָה וְהַמִּתְנַשּא לְכל לְראשׁ: רומְמוּ ה' אֱלהֵינוּ וְהִשְׁתַּחֲווּ לַהֲדם רַגְלָיו קָדושׁ הוּא: רומְמוּ ה' אֱלהֵינוּ וְהִשְׁתַּחֲווּ לְהַר קָדְשׁו כִּי קָדושׁ ה' אֱלהֵינוּ:","note":true}]},{"id":"torah-reading-removing-the-torah-from-the-ark-veyazor-veyagen","heading":"Veyazor Veyagen","group":"Torah Reading · Removing the Torah from the Ark","lines":[{"he":"החזן מניח את ספר התורה על הבימה ואומר: וְיַעֲזר וְיָגֵן וְיושִׁיעַ לְכָל הַחוסִים בּו וְנאמַר אָמֵן. הַכּל הָבוּ גדֶל לֵאלהֵינוּ וּתְנוּ כָבוד לַתּורָה. כּהֵן קְרָב. יַעֲמד פלוני בן פלוני הַכּהֵן. בָּרוּךְ שֶׁנָּתַן תּורָה לְעַמּו יִשרָאֵל בִּקְדֻשָּׁתו:","note":true}]},{"id":"torah-reading-reading-from-sefer-birkat-hatorah","heading":"Birkat HaTorah","group":"Torah Reading · Reading from Sefer","lines":[{"he":"העולה מברך: בָּרְכוּ אֶת ה' הַמְברָךְ:","note":true},{"he":"והקהל עונין: בָּרוּךְ ה' הַמְברָךְ לְעולָם וָעֶד:","note":true},{"he":"והעולה חוזר ואומר: בָּרוּךְ ה' הַמְברָךְ לְעולָם וָעֶד:","note":true},{"he":"ואח\"כ מברך: בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם אֲשֶׁר בָּחַר בָּנוּ מִכָּל הָעַמִּים וְנָתַן לָנוּ אֶת תּורָתו. בָּרוּךְ אַתָּה ה' נותֵן הַתּורָה:","note":true},{"he":"אחר קריאת התורה מברך העולה: בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם אֲשֶׁר נָתַן לָנוּ תּורַת אֱמֶת וְחַיֵּי עולָם נָטַע בְּתוכֵנוּ. בָּרוּךְ אַתָּה ה' נותֵן הַתּורָה:","note":true}]},{"id":"torah-reading-reading-from-sefer-birkat-hagomel","heading":"Birkat Hagomel","group":"Torah Reading · Reading from Sefer","lines":[{"he":"ברכת הגומל: בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. הַגּומֵל לְחַיָּבִים טובות. שֶׁגְּמָלַנִי כָּל טוב:","note":true},{"he":"הקהל עונה אמן. ואומרים: מִי שֶׁגְּמָלְךָ טוב. הוּא יִגְמָלְךָ כָּל טוב סֶלָה:","note":true}]},{"id":"torah-reading-reading-from-sefer-mi-sheberach-for-an-oleh","heading":"For an Oleh","group":"Torah Reading · Reading from Sefer · Mi Sheberach","lines":[{"he":"מִי שֶׁבֵּרַךְ אֲבותֵינוּ אַבְרָהָם יִצְחָק וְיַעֲקב הוּא יְבָרֵךְ אֶת פב\"פ בַּעֲבוּר שֶׁעָלָה לַתּורָה לִכְבוד הַמָּקום לִכְבוד הַתּורָה וְלִכְבוד הַשַּׁבָּת ליו\"ט וְלִכְבוד הַרֶגֶל. לר\"ה ויו\"כ וְלִכְבוד יום הַדִּין, בִשכַר זֶה הַקָּדושׁ בָּרוּךְ הוּא יִשְׁמְרֵהוּ וְיַצִּילֵהוּ מִכָּל צָרָה וְצוּקָה וּמִכָּל נֶגַע וּמַחֲלָה וְיִשְׁלַח בְּרָכָה וְהַצְלָחָה בְּכָל מַעֲשה יָדָיו ליו\"ט וְיִזְכֶּה לַעֲלות לָרֶגֶל לר\"ה ויו\"כ וִיִכְתְּבֵהוּ וְיַחְתְּמֵהוּ לְחַיִּים טובִים בְּיום הַדִּין הַזֶּה עִם כָּל יִשרָאֵל אֶחָיו וְנאמַר אָמֵן:"}]},{"id":"torah-reading-reading-from-sefer-mi-sheberach-for-sickness-includes-man-and-woman","heading":"For Sickness (includes man and woman)","group":"Torah Reading · Reading from Sefer · Mi Sheberach","lines":[{"he":"לזכר: מִי שֶׁבֵּרַךְ אֲבותֵינוּ אַבְרָהָם יִצְחָק וְיַעֲקב משֶׁה וְאַהֲרן דָּוִד וּשְׁלמה הוּא יְבָרֵךְ אֶת הַחולֶה פב\"פ בַּעֲבוּר שפב\"פ נודֵר צְדָקָה בַּעֲבוּרו, בִּשכַר זֶה הַקָּדושׁ בָּרוּךְ הוּא יִמָלֵא רַחֲמִים עָלָיו לְהַחֲלִימו וּלְרַפְּאתו וּלְהַחֲזִיקו וּלְהַחֲיותו, וְיִשְׁלַח לו מְהֵרָה רְפוּאָה שְׁלֵמָה מִן הַשָּׁמַיִם לִרְמַ\"ח אֵבָרָיו וּשְׁסָ\"ה גִּידָיו בְּתוךְ שְׁאָר חולֵי יִשרָאֵל, רְפוּאַת הַנֶּפֶשׁ וּרְפוּאַת הַגּוּף בשבת: שַׁבָּת הִיא מִלִזְּעוק וּרְפוּאָה קְרובָה לָבוא. ביו\"ט: יום טוב הוא מִלְזּעוק וּרְפוּאָה קְרובָה לָבוא, הַשְׁתָּא בַּעֲגָלָא וּבִזְמַן קָרִיב. וְנאמַר אָמֵן:","en":"For a male: May the one who blessed our ancestors - Abraham, Isaac, and Jacob, Moses, and Aaron, David, and Solomon - may God bless the sick on behalf of a vow of tzedakah on their behalf, with this reward may the Holy Blessed One be filled with compassion for him to have pity on him and to heal him and to strengthen him and to give him life, to send speedily complete healing from the heavens to the 248 organs and 365 ligaments among all the sick of Israel, a healing of spirit and a healing of body (on Shabbat: Shabbat prevents from crying out, may healing come near soon; on Yom Tov: Yom Tov prevents calls out, may healing come near soon), now and speedily, and in a time soon, and let us say, Amen.","note":true},{"he":"לנקבה: מִי שֶׁבֵּרַךְ אֲבותֵינוּ אַבְרָהָם יִצְחָק וְיַעֲקב משֶׁה וְאַהֲרן דָּוִד וּשְׁלמה הוּא יְבָרֵךְ אֶת הַחולָה פב\"פ בַּעֲבוּר שפב\"פ נודֵר צְדָקָה בַּעֲבוּרָהּ, בִּשכַר זֶה הַקָּדושׁ בָּרוּךְ הוּא יִמָלֵא רַחֲמִים עָלֶיהָ לְהַחֲלִימָהּ וּלְרַפְּאתָהּ וּלְהַחֲזִיקָהּ וּלְהַחֲיותָהּ, וְיִשְׁלַח לָהּ מְהֵרָה רְפוּאָה שְׁלֵמָה מִן הַשָּׁמַיִם לְכָל אֵבָרֶיהּ וּלְכָל גִּידֶיהָ בְּתוךְ שְׁאָר חולֵי יִשרָאֵל, רְפוּאַת הַנֶּפֶשׁ וּרְפוּאַת הַגּוּף בשבת: שַׁבָּת הִיא מִלִזְּעוק וּרְפוּאָה קְרובָה לָבוא. ביו\"ט: יום טוב הוא מִלְזּעוק וּרְפוּאָה קְרובָה לָבוא, הַשְׁתָּא בַּעֲגָלָא וּבִזְמַן קָרִיב. וְנאמַר אָמֵן:","en":"For a female: May the one who blessed our ancestors - Abraham, Isaac, and Jacob, Moses, and Aaron, David, and Solomon - may God bless the sick on behalf of a vow of tzedakah on their behalf, with this reward may the Holy Blessed One be filled with compassion for her to have pity on her and to heal her and to strengthen her and to give her life, to send speedily complete healing from the heavens to the 248 organs and 365 ligaments among all the sick of Israel, a healing of spirit and a healing of body (on Shabbat: Shabbat prevents from crying out, may healing come near soon; on Yom Tov: Yom Tov prevents from calling out, may healing come near soon), now and speedily, and in a time soon, and let us say, Amen.","note":true}]},{"id":"torah-reading-reading-from-sefer-mi-sheberach-for-birth-birth-of-a-son","heading":"Birth of a Son","group":"Torah Reading · Reading from Sefer · Mi Sheberach · For Birth","lines":[{"he":"ליולדת זכר: מִי שֶׁבֵּרַךְ אֲבותֵינוּ אַבְרָהָם יִצְחָק וְיַעֲקב משֶׁה וְאַהֲרן דָּוִד וּשְׁלמה, שרָה רִבְקָה רָחֵל וְלֵאָה, הוּא יְבָרֵךְ אֶת הָאִשָּׁה הַיּולֶדֶת פב”פ וְאֶת בְּנָהּ שֶֶׁנולַד לָהּ לְמַזָּל טוב, בַּעֲבוּר שֶׁבַּעְלָהּ וְאָבִיו נודֵר צְדָקָה בַּעֲדָם, בִּשכַר זֶה יִזְכּוּ אָבִיו וְאִמו לְהַכְנִיסו בִּבְרִיתו שֶׁל אַבְרָהָם אָבִינוּ וּלְגַדְּלו לְתורָה וּלְחֻפָּה וּלְמַעֲשים טובִים. וְנאמַר אָמֵן:","note":true}]},{"id":"torah-reading-reading-from-sefer-mi-sheberach-for-birth-birth-of-daughter","heading":"Birth of Daughter","group":"Torah Reading · Reading from Sefer · Mi Sheberach · For Birth","lines":[{"he":"ליולדת נקבה: מִי שֶׁבֵּרַךְ אֲבותֵינוּ אַבְרָהָם יִצְחָק וְיַעֲקב משֶׁה וְאַהֲרן דָּוִד וּשְׁלמה, שרָה רִבְקָה רָחֵל וְלֵאָה, הוּא יְבָרֵךְ אֶת הָאִשָּׁה הַיּולֶדֶת פב\"פ וְאֶת בִּתָּהּ שֶׁנּולְדָה לָהּ לְמַזָּל טוב, וְיִקָּרֵא שְׁמָהּ בְּיִשרָאֵל פב\"פ, בַּעֲבוּר שֶׁבַּעְלָהּ וְאָבִיהָ נודֵר צְדָקָה בַּעֲדָן, בִּשכַר זֶה יִזְכּוּ אָבִיהָ וְאִמָהּ לְגַדְּלָה לְתורָה וּלְחֻפָּה וּלְמַעֲשים טובִים. וְנאמַר אָמֵן:","note":true}]},{"id":"torah-reading-reading-from-sefer-mi-sheberach-bar-mitzvah","heading":"Bar Mitzvah","group":"Torah Reading · Reading from Sefer · Mi Sheberach","lines":[{"he":"מִי שֶׁבֵּרַךְ אֲבותֵינוּ אַבְרָהָם יִצְחָק וְיַעֲקב הוּא יְבָרֵךְ אֶת פב\"פ שֶׁמָּלְאוּ לו שְׁלשׁ עֶשרֵה שָׁנָה וְהִגִּיעַ לְמִצְות, וְעָלָה לַתּורָה, לָתֵת שֶׁבַח וְהודָיָה לְה' יִתְבָּרַךְ עַל כָּל הַטּובָה שֶׁגָּמַל אִתּו. יִשְׁמְרֵהוּ הַקָּדושׁ בָּרוּךְ הוּא וִיחַיֵּהוּ, וִיכונֵן אֶת לבּו לִהְיות שָׁלֵם עִם ה' וְלָלֶכֶת בִּדְרָכָיו וְלִשְׁמר מִצְותָיו כָּל הַיָּמִים, וְנאמַר אָמֵן:"},{"he":"אם קראו לספר תורה נער שנעשה בר מצווה, אחר שבירך ברכה אחרונה, אביו יאמר: בָּרוּךְ שֶׁפְּטָרַנִי מֵעָנְשׁו שֶׁלָזֶה:","note":true}]},{"id":"torah-reading-reading-from-sefer-half-kaddish","heading":"Half Kaddish","group":"Torah Reading · Reading from Sefer","lines":[{"he":"חזן: יִתְגַּדַּל וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. [קהל: אמן] בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵהּ בְּחַיֵּיכון וּבְיומֵיכון וּבְחַיֵּי דְכָל בֵּית יִשרָאֵל בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן: [קהל: אמן] קהל וחזן: יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא: יִתְבָּרַךְ וְיִשְׁתַּבַּח וְיִתְפָּאַר וְיִתְרומַם וְיִתְנַשּא וְיִתְהַדָּר וְיִתְעַלֶּה וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא. בְּרִיךְ הוּא. [קהל: בריך הוא:] לְעֵלָּא בעשי\"ת לְעֵלָּא לְעֵלָּא מִכָּל מִן כָּל בִּרְכָתָא וְשִׁירָתָא תֻּשְׁבְּחָתָא וְנֶחֱמָתָא דַּאֲמִירָן בְּעָלְמָא. וְאִמְרוּ אָמֵן: [קהל: אמן]","note":true}]},{"id":"torah-reading-reading-from-sefer-raising-the-torah","heading":"Raising the Torah","group":"Torah Reading · Reading from Sefer","lines":[{"he":"כשמגביהים ס\"ת מביטים על הכתב של הספר ואומרים: וְזאת הַתּורָה אֲשֶׁר שם משֶׁה לִפְנֵי בְּנֵי יִשרָאֵל: עַל פִּי ה' בְּיַד משֶׁה:","note":true}]},{"id":"torah-reading-reading-from-sefer-haftarah","heading":"Haftarah","group":"Torah Reading · Reading from Sefer","lines":[{"he":"קודם קריאת ההפטרה יברך המפטיר ברכה זו: בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. אֲשֶׁר בָּחַר בִּנְבִיאִים טובִים. וְרָצָה בְדִבְרֵיהֶם הַנֶּאֱמָרִים בֶּאֱמֶת. בָּרוּךְ אַתָּה ה'. הַבּוחֵר בַּתּורָה וּבְמשֶׁה עַבְדּו. וּבְיִשרָאֵל עַמּו. וּבִנְבִיאֵי הָאֱמֶת וְהַצֶּדֶק:","en":"(Before reading the haftarah, the reader recites this blessing:) Blessed are You, Eternal, our Divinity, King of the universe, who chose good prophets and favored their spoken words with truth. Blessed are You, Eternal, the Choosing of Torah, [the] servant Moses, [the] people Israel, and prophets of truth and justice.","note":true},{"he":"אחרי קריאת ההפטרה אומר המפטיר ברכות אלו: בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם. צוּר כָּל הָעולָמִים. צַדִּיק בְּכָל הַדּורות. הָאֵל הַנֶּאֱמָן הָאומֵר וְעושה. הַמְדַבֵּר וּמְקַיֵּם שֶׁכָּל דְּבָרָיו אֱמֶת וָצֶדֶק:","en":"(After reading the haftarah, the reader says these blessings:) Blessed are You, Eternal, our Divinity, King of the universe, Rock of all infinitudes, righteous in all generations, Faithful Divinity who says and does, speaks and fulfills all words of truth and justice.","note":true},{"he":"נֶאֱמָן אַתָּה הוּא ה' אֱלהֵינוּ וְנֶאֱמָנִים דְּבָרֶיךָ. וְדָבָר אֶחָד מִדְּבָרֶיךָ אָחור לא יָשׁוּב רֵיקָם. כִּי אֵל מֶלֶךְ נֶאֱמָן וְרַחֲמָן אָתָּה: בָּרוּךְ אַתָּה ה'. הָאֵל הַנֶּאֱמָן בְּכָל דְּבָרָיו:","en":"You are faithful, Eternal, our Divinity, and Your words are faithful. And not one of your earliest words will return empty. For You are a faithful and compassionate Divinity, King. Blessed are You, Eternal, the faithful Divinity in all generations."},{"he":"רַחֵם עַל צִיּון כִּי הִיא בֵּית חַיֵּינוּ. וְלַעֲלוּבַת נֶפֶשׁ תּושִׁיעַ בִּמְהֵרָה בְיָמֵינוּ:","en":"Have compassion upon Zion, for it is the house of our lives. And save the poor of spirit swiftly in our days."},{"he":"בָּרוּךְ אַתָּה ה'. מְשמֵּחַ צִיּון בְּבָנֶיהָ:","en":"Blessed are You, Eternal, who causes Zion to rejoice with her [children]."},{"he":"שמְּחֵנוּ ה' אֱלהֵינוּ בְּאֵלִיָּהוּ הַנָּבִיא עַבְדֶּךָ וּבְמַלְכוּת בֵּית דָּוִד מְשִׁיחֶךָ. בִּמְהֵרָה יָבוא וְיָגֵל לִבֵּנוּ. עַל כִּסְאו לא יֵשֵׁב זָר וְלא יִנְחֲלוּ עוד אֲחֵרִים אֶת כְּבודו. כִּי בְשֵׁם קָדְשְׁךָ נִשְׁבַּעְתָּ לו שֶׁלּא יִכְבֶּה נֵרו לְעולָם וָעֶד: בָּרוּךְ אַתָּה ה'. מָגֵן דָּוִד: עד כאן אומרים בתענית ציבור ובמנחה יום כיפור","en":"Gladden us, Eternal, our Divinity, with Your servant Elijah the prophet, and with the reign of the house of David, Your anointed one. May he quickly come and gladden our hearts. Upon his throne there shall not sit a stranger, nor shall others again possess his glory. For in Your holy name, You promised him that his light would not be extinguished for eternity. Blessed are You, Eternal, shield of David. (Say the blessings until this point on communal fasts and Yom Kippur mincha.)"},{"he":"בשבת, ובשבת חול המועד פסח אומרים: עַל הַתּורָה וְעַל הָעֲבודָה וְעַל הַנְּבִיאִים וְעַל יום הַשַּׁבָּת הַזֶּה שֶׁנָּתַתָּ לָנוּ ה' אֱלהֵינוּ לִקְדֻשָּׁה וְלִמְנוּחָה לְכָבוד וּלְתִפְאָרֶת: עַל הַכּל. ה' אֱלהֵינוּ אֲנַחְנוּ מודִים לָךְ וּמְבָרְכִים אותָךְ. יִתְבָּרַךְ שִׁמְךָ בְּפִי כָּל חַי תָּמִיד לְעולָם וָעֶד: בָּרוּךְ אַתָּה ה'. מְקַדֵּשׁ הַשַּׁבָּת:","en":"(Say on Shabbat and Shabbat during Pesach:) For the Torah, service, prophets, and this day of Shabbat that You have given us, Eternal, our Divinity, for holiness and comfort, for honor and glory. For everything, Eternal, our Divinity, we thank You and bless You. May Your name be blessed in the mouth of all life always, forever and ever. Blessed are You, Eternal, the one who sanctifies Shabbat.","note":true},{"he":"בשלוש רגלים ובשבת חוה\"מ סוכות אומרים: עַל הַתּורָה וְעַל הָעֲבודָה וְעַל הַנְּבִיאִים לשבת וְעַל יום הַשַּׁבָּת הַזֶּה, וְעַל יום: לפסח: חַג הַמַּצּות לשבועות: חַג הַשָׁבוּעות סוכות: - חַג הַסֻּכּות לשמ\"ע ולש”ת: הַשְׁמִינִי חַג הָעֲצֶרֶת הַזֶּה שֶׁנָּתַתָּ לָנוּ ה' אֱלהֵינוּ לשבת: לִקְדֻשָּׁה וְלִמְנוּחָה לְששון וּלְשמְחָה, לְכָבוד וּלְתִפְאָרֶת, עַל הַכּל. ה' אֱלהֵינוּ אֲנַחְנוּ מודִים לָךְ וּמְבָרְכִים אותָךְ. יִתְבָּרַךְ שִׁמְךָ בְּפִי כָּל חַי תָּמִיד לְעולָם וָעֶד: בָּרוּךְ אַתָּה ה'. מְקַדֵּשׁ הַשַּׁבָּת וְ יִשרָאֵל וְהַזְמַנִים:","en":"(Say on the Three Pilgrimage Festivals -- Passover, Shavuot, and Sukkot -- and on the Shabbat during Sukkot:)","note":true},{"he":"בראש השנה: עַל הַתּורָה וְעַל הָעֲבודָה וְעַל הַנְּבִיאִים לשבת: וְעַל יום הַשַּׁבָּת הַזֶּה וְעַל יום הַזִכָּרון הַזֶּה, שֶׁנָּתַתָּ לָנוּ ה' אֱלהֵינוּ לשבת: לִקְדֻשָּׁה וְלִמְנוּחָה לְכָבוד וּלְתִפְאָרֶת: עַל הַכּל. ה' אֱלהֵינוּ אֲנַחְנוּ מודִים לָךְ וּמְבָרְכִים אותָךְ. יִתְבָּרַךְ שִׁמְךָ בְּפִי כָּל חַי תָּמִיד לְעולָם וָעֶד: בָּרוּךְ אַתָּה ה'. מְקַדֵּשׁ הַשַּׁבָּת וְ יִשרָאֵל וְיום הַזִּכָּרון:","note":true}]},{"id":"communal-prayers-yekum-purkan","heading":"Yekum Purkan","group":"Communal Prayers","lines":[{"he":"אחר ברכות ההפטרה אומרים: יְקוּם פּוּרְקָן מִן שְׁמַיָּא חִנָּא וְחִסְדָּא וְרַחֲמֵי וְחַיֵּי אֲרִיכֵי וּמְזוֹנֵי רְוִיחֵי וְסִיַּעְתָּא דִשְׁמַיָּא וּבַרְיוּת גּוּפָא וּנְהוֹרָא מַעַלְיָא. זַרְעָא חַיָּא וְקַיָּמָא זַרְעָא דִּי לָא יִפְסוֹק וְדִי לָא יִבְטוֹל מִפִּתְגָּמֵי אוֹרַיְתָא. לְמָרָנָן וְרַבָּנָן חֲבוּרָתָא קַדִּישָׁתָא דִּי בְאַרְעָא דְיִשְׂרָאֵל וְדִי בְּבָבֶל לְרֵישֵׁי כַלָּה וּלְרֵישֵׁי גַּלְוָתָא וּלְרֵישֵׁי מְתִיבָתָא וּלְדַיָּנֵי דִי בָבָא. לְכָל תַּלְמִידֵיהוֹן וּלְכָל תַּלְמִידֵי תַּלְמִידֵיהוֹן וּלְכָל מַאן דְּעָסְקִין בְּאוֹרַיְתָא. מַלְכָּא דְעָלְמָא יְבָרֵךְ יַתְהוֹן יַפִּישׁ חַיֵּיהוֹן וְיַסְגֵּא יוֹמֵיהוֹן וְיִתֵּן אַרְכָא לִשְׁנֵיהוֹן. וְיִתְפָּרְקוּן וְיִשְׁתֵּזְבוּן מִן כָּל עָקָא וּמִן כָּל מַרְעִין בִּישִׁין. מָרָן דִּי בִשְׁמַיָּא יְהֵא בְסַעְדְּהוֹן כָּל זְמַן וְעִדָּן. וְנֹאמַר אָמֵן:","note":true},{"he":"יחיד המתפלל בביתו אינו אומר יקום פורקן זה ולא מי שברך: יְקוּם פּוּרְקָן מִן שְׁמַיָּא חִנָּא וְחִסְדָּא וְרַחֲמֵי וְחַיֵּי אֲרִיכֵי וּמְזוֹנֵי רְוִיחֵי וְסִיַּעְתָּא דִשְׁמַיָּא וּבַרְיוּת גּוּפָא וּנְהוֹרָא מַעַלְיָא. זַרְעָא חַיָּא וְקַיָּמָא זַרְעָא דִּי לָא יִפְסוֹק וְדִי לָא יִבְטוֹל מִפִּתְגָּמֵי אוֹרַיְתָא. לְכָל קְהָלָא קַדִּישָׁא הָדֵין רַבְרְבַיָּא עִם זְעֵרַיָּא טַפְלָא וּנְשַׁיָּא. מַלְכָּא דְעָלְמָא יְבָרֵךְ יַתְכוֹן יַפִּישׁ חַיֵּיכוֹן וְיַסְגֵּי יוֹמֵיכוֹן וְיִתֵּן אַרְכָא לִשְׁנֵיכוֹן וְתִתְפָּרְקוּן וְתִשְׁתֵּזְבוּן מִן כָּל עָקָא וּמִן כָּל מַרְעִין בִּישִׁין. מָרָן דִּי בִשְׁמַיָּא יְהֵא בְּסַעְדְּכוֹן כָּל זְמַן וְעִדָּן וְנֹאמַר אָמֵן:","note":true},{"he":"ברכה לקהל: מִי שֶׁבֵּרַךְ אֲבוֹתֵינוּ אַבְרָהָם יִצְחָק וְיַעֲקֹב. הוּא יְבָרֵךְ אֶת כָּל הַקָּהָל הַקָּדוֹשׁ הַזֶּה עִם כָּל קְהִלּוֹת הַקֹּדֶשׁ. הֵם וּנְשֵׁיהֶם וּבְנֵיהֶם וּבְנוֹתֵיהֶם וְכָל אֲשֶׁר לָהֶם. וּמִי שֶׁמְּיַחֲדִים בָּתֵּי כְנֵסִיּוֹת לִתְפִלָּה. וּמִי שֶׁבָּאִים בְּתוֹכָם לְהִתְפַּלֵּל. וּמִי שֶׁנּוֹתְנִים נֵר לַמָּאוֹר וְיַיִן לְקִדּוּשׁ וּלְהַבְדָּלָה וּפַת לְאוֹרְחִים וּצְדָקָה לָעֲנִיִּים. וְכָל מִי שֶׁעוֹסְקִים בְּצָרְכֵי צִבּוּר בֶּאֱמוּנָה. הַקָּדוֹשׁ בָּרוּךְ הוּא יְשַׁלֵּם שְׂכָרָם וְיָסִיר מֵהֶם כָּל מַחֲלָה וְיִרְפָּא לְכָל גּוּפָם וְיִסְלַח לְכָל עֲוֹנָם. וְיִשְׁלַח בְּרָכָה וְהַצְלָחָה בְּכָל מַעֲשֵׂה יְדֵיהֶם עִם כָּל יִשְׂרָאֵל אֲחֵיהֶם. וְנֹאמַר אָמֵן:","en":"וְכָל מִי שֶׁעוסְקִים בְּצָרְכֵי צִבּוּר בֶּאֱמוּנָה. הַקָּדושׁ בָּרוּךְ הוּא יְשַׁלֵּם שכָרָם וְיָסִיר מֵהֶם כָּל מַחֲלָה וְיִרְפָּא לְכָל גּוּפָם וְיִסְלַח לְכָל עֲונָם. וְיִשְׁלַח בְּרָכָה וְהַצְלָחָה בְּכָל מַעֲשה יְדֵיהֶם עִם כָּל יִשרָאֵל אֲחֵיהֶם.","note":true}]},{"id":"communal-prayers-prayer-of-the-state-of-israel","heading":"Prayer of the State of Israel","group":"Communal Prayers","lines":[{"he":"אָבִינוּ שֶׁבַּשָּׁמַיִם,","en":"Our Father in Heaven,"},{"he":"צוּר יִשְׂרָאֵל וְגוֹאֲלוֹ,","en":"the Rock and Redeemer of Israel,"},{"he":"בָּרֵךְ אֶת מְדִינַת יִשְׂרָאֵל,","en":"Bless the State of Israel,"},{"he":"רֵאשִׁית צְמִיחַת גְּאֻלָּתֵנוּ.","en":"the first sprouting of our redemption."},{"he":"הָגֵן עָלֶיהָ בְּאֶבְרַת חַסְדֶּךָ,","en":"Protect it with Your great kindness,"},{"he":"וּפְרֹשׂ עָלֶיהָ סֻכַּת שְׁלוֹמֶךָ,","en":"spread over it the shelter of Your peace,"},{"he":"וּשְׁלַח אוֹרְךָ וַאֲמִתְּךָ לְרָאשֶׁיהָ, שָׂרֶיהָ וְיוֹעֲצֶיהָ,","en":"grant Your light and truth to its leaders, ministers, and advisors,"},{"he":"וְתַקְּנֵם בְּעֵצָה טוֹבָה מִלְּפָנֶיךָ.","en":"and provide them with Your good counsel."},{"he":"חַזֵּק אֶת יְדֵי מְגִנֵּי אֶרֶץ קׇדְשֵׁנוּ,","en":"Strengthen the hands of the defenders of our Holy Land,"},{"he":"וְהַנְחִילֵם אֱלֹהֵינוּ יְשׁוּעָה","en":"bequeath deliverance to them, our God,"},{"he":"וַעֲטֶרֶת נִצָּחוֹן תְּעַטְּרֵם,","en":"crown them with the crown of victory,"},{"he":"וְנָתַתָּ שָׁלוֹם בָּאָרֶץ,","en":"and give peace to the land"},{"he":"וְשִׂמְחַת עוֹלָם לְיוֹשְׁבֶיהָ.","en":"and everlasting joy to its inhabitants."},{"he":"וְאֶת אַחֵינוּ כָּל בֵּית יִשְׂרָאֵל,","en":"And remember all our brethren of the House of Israel,"},{"he":"פְּקׇד נָא בְּכָל אַרְצוֹת פְּזוּרֵיהֶם,","en":"in all the lands of their dispersion,"},{"he":"וְתוֹלִיכֵם מְהֵרָה קוֹמְמִיּוּת לְצִיּוֹן עִירֶךָ","en":"and bring them quickly to Zion, Your city,"},{"he":"וְלִירוּשָׁלַיִם מִשְׁכַּן שְׁמֶךָ,","en":"and to Jerusalem, the domicile of Your name,"},{"he":"כַּכָּתוּב בְּתוֹרַת מֹשֶׁה עַבְדֶּךְ (דברים ל,ד-ו):","en":"as it is written in the Torah of Moses, Your servant:"},{"he":"\"אִם יִהְיֶה נִדַּחֲךָ בִּקְצֵה הַשָּׁמָיִם,","en":"Even if your outcasts are at the end of the heavens"},{"he":"מִשָּׁם יְקַבֶּצְךָ יְיָ אֱלֹהֶיךָ וּמִשָּׁם יִקָּחֶךָ.","en":"the Lord, your God, will gather you and take you from there."},{"he":"וֶהֱבִיאֲךָ יְיָ אֱלֹהֶיךָ אֶל הָאָרֶץ אֲשֶׁר יָרְשׁוּ אֲבֹתֶיךָ וִירִשְׁתָּהּ,","en":"And the Lord, your God, will bring you to the land that Your forefathers inherited, and you shall inherit it,"},{"he":"וְהֵיטִבְךָ וְהִרְבְּךָ מֵאֲבֹתֶיךָ.","en":"and He shall benefit you and make your numbers greater than your fathers."},{"he":"וּמָל יְיָ אֱלֹהֶיךָ אֶת לְבָבְךָ וְאֶת לְבַב זַרְעֶךָ,","en":"Then the Lord, your God, will circumcise your hearts and the hearts of your offspring,"},{"he":"לְאַהֲבָה אֶת יְיָ אֱלֹהֶיךָ בְּכׇל לְבָבְךָ וּבְכׇל נַפְשְׁךָ,","en":"to love the Lord, your God, with all your heart and with all your soul,"},{"he":"לְמַעַן חַיֶּיךָ\".","en":"in order that you may live (Deuteronomy 30:4-6)."},{"he":"וְיַחֵד לְבָבֵנוּ לְאַהֲבָה וּלְיִרְאָה אֶת שְׁמֶךָ,","en":"Unify our hearts to love and be awed by Your name,"},{"he":"וְלִשְׁמֹר אֶת כׇּל דִּבְרֵי תּוֹרָתֶךָ,","en":"and to keep all the words of Your Torah,"},{"he":"וּשְׁלַח לָנוּ מְהֵרָה בֶּן דָּוִד מְשִׁיחַ צִדְקֶךָ,","en":"and may You dispatch the son of David, Your righteous Messiah, to us,"},{"he":"לִפְדּוֹת מְחַכֵּי קֵץ יְשׁוּעָתֶךָ.","en":"to redeem those awaiting Your final salvation."},{"he":"הוֹפַע בַּהֲדַר גְּאוֹן עֻזֶּךָ","en":"Appear with the glory and pride of Your strength"},{"he":"עַל כׇּל יוֹשְׁבֵי תֵּבֵל אַרְצֶךָ,","en":"before all the inhabitants of Your world,"},{"he":"וְיֹאמַר כֹּל אֲשֶׁר נְשָׁמָה בְּאַפּוֹ:","en":"and may all who have breath in them say,"},{"he":"\"יְיָ אֱלֹהֵי יִשְׂרָאֵל מֶלֶךְ,","en":"\"The Lord, God of Israel, is the King,"},{"he":"וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה!\"","en":"and His kingdom is over everything.\""},{"he":"אָמֵן סֶלָה.","en":"Amen, selah."}]},{"id":"communal-prayers-prayer-for-israeli-soldiers","heading":"Prayer for Israeli Soldiers","group":"Communal Prayers","lines":[{"he":"מִי שֶׁבֵּרַךְ אֲבוֹתֵינוּ אַבְרָהָם יִצְחָק וְיַעֲקֹב","en":"May He who blessed our fathers, Abraham, Isaac, and Jacob"},{"he":"הוּא יְבָרֵךְ אֶת חַיָּלֵי צְבָא הֲגַנָּה לְיִשְׂרָאֵל","en":"bless the soldiers of the Israel Defense Forces,"},{"he":"הָעוֹמְדִים עַל מִשְׁמַר אַרְצֵנוּ וְעָרֵי אֱלֹהֵינוּ","en":"who are standing guard over our land and over the cities of our God,"},{"he":"מִגְּבוּל הַלְּבָנוֹן וְעַד מִדְבַּר מִצְרַיִם","en":"from the border of Lebanon to the Wilderness of Egypt,"},{"he":"וּמִן הַיָּם הַגָּדוֹל עַד לְבוֹא הָעֲרָבָה בַּיַּבָּשָׁה בָּאֲוִיר וּבַיָּם","en":"and from the Great Sea to the Approach of the Aravah — on land, in the air, and in the sea."},{"he":"יִתֵּן ה' אֶת אוֹיְבֵינוּ הַקָּמִים עָלֵינוּ נִגָּפִים לִפְנֵיהֶם","en":"May the Lord give plagues before our enemies who arise against us."},{"he":"הַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׁמֹר וְיַצִּיל אֶת חַיָלֵינוּ מִכָּל צָרָה וְצוּקָה וּמִכָּל נֶגַע וּמַחֲלָה","en":"May the Holy One, blessed be He, guard and rescue our soldiers from all trouble and distress, and from all affliction and illness;"},{"he":"וְיִשְׁלַח בְּרָכָה וְהַצְלָחָה בְּכָל מַעֲשֵׂה יְדֵיהֶם","en":"and may He grant blessing and success to all the acts of their hands."},{"he":"יַדְבֵּר שׂוֹנְאֵינוּ תַּחְתֵּיהֶם וִיעַטְרֵם בְּכֶתֶר יְשׁוּעָה וּבְעֲטֶרֶת נִצָּחוֹן","en":"May He crush beneath them those who hate us and crown our soldiers with the crown of salvation and with the crown of victory."},{"he":"וִיקֻיַּם בָּהֶם הַכָּתוּב:","en":"And may the verse be fulfilled through them:"},{"he":"כִּי ה' אֱלֹהֵיכֶם הַהֹלֵךְ עִמָּכֶם לְהִלָּחֵם לָכֶם עִם אֹיְבֵיכֶם לְהוֹשִׁיעַ אֶתְכֶם","en":"For it is the Lord, your God, who walks with you to fight for you against your enemies to save you (Deuteronomy 20:4)."},{"he":"וְנֹאמַר אָמֵן","en":"And let us say, Amen."}]},{"id":"communal-prayers-prayer-for-those-being-held-in-captivity","heading":"Prayer for Those Being Held in Captivity","group":"Communal Prayers","lines":[{"he":"מִי שֶׁבֵּרַךְ אֲבוֹתֵינוּ אַבְרָהָם יִצְחָק וְיַעֲקֹב יוֹסֵף מֹשֶׁה וְאַהֲרֹן דָּוִד וּשְׁלֹמֹה, הוּא יְבָרֵךְ וְיִשְׁמֹר וְיִנְצֹר אֶת כָּל הַחֲטוּפִים, הַשְּׁבוּיִים וְהַנֶּעֱדָרִים בְּתוֹךְ שְׁאָר אֲחֵינוּ בֵּית יִשְֹרָאֵל הַנְּתוּנִים בְּצָרָה וּבְשִׁבְיָה. בַּעֲבוּר שֶׁהַקָּהָל מִתְפַּלֵּל בַּעֲבוּרָם, הַקָּדוֹשׁ בָּרוּךְ הוּא יִמָּלֵא רַחֲמִים עֲלֵיהֶם, וְיוֹצִיאֵם מֵחֹשֶׁךְ וְצַלְמָוֶת, וּמוֹסְרוֹתֵיהֶם יְנַתֵּק, וּמִמְּצוּקוֹתֵיהֶם יוֹשִׁיעֵם, וִישִׁיבֵם מְהֵרָה לְחֵיק מִשְׁפְּחוֹתֵיהֶם. יוֹדוּ לַה' חַסְדּוֹ וְנִפְלְאוֹתָיו לִבְנֵי אָדָם. וִיקֻיַּם בָּהֶם מִקְרָא שֶׁכָּתוּב: וּפְדוּיֵי ה' יְשׁוּבוּן וּבָאוּ צִיּוֹן בְּרִנָּה וְשִׂמְחַת עוֹלָם עַל רֹאשָׁם. שָׂשׂוֹן וְשִׂמְחָה יַשִּׂיגוּ וְנָסוּ יָגוֹן וַאֲנָחָה. וְנֹאמַר אָמֵן.","en":"May the One who blessed Abraham, Isaac, Jacob, Joseph, Moses, Aaron, David and Solomon bless, watch and guard those missing from the Israel Defense Forces and the captives, among others of our brethren of the House of Israel that are situated in distress and in captivity. On account of the congregation's praying for them, may the Holy One, blessed be He, grant mercy upon them, take them out from darkness and gloom, break their chains, redeem them from their ordeals and return them quickly to the comfort of their families. \"Let them praise the Lord for His kindness, and His wondrous deeds for the children of man\" (Psalms 107:8). And through them, let the verse (Isaiah 35:10) be fulfilled, \"And the Lord’s ransomed shall return, and come with shouting to Zion, crowned with joy everlasting; they shall attain joy and gladness, while sorrow and sighing flee.\" And let us say, Amen!"}]},{"id":"communal-prayers-birkat-hachodesh","heading":"Birkat Hachodesh","group":"Communal Prayers","lines":[{"he":"הש\"ץ לוקח הספר תורה בידו ואומר:"},{"he":"יְהִי רָצון מִלְּפָנֶיךָ ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ. שֶׁתְּחַדֵּשׁ עָלֵינוּ אֶת הַחדֶשׁ הַזֶּה לְטובָה וְלִבְרָכָה. וְתִתֶּן לָנוּ חַיִּים אֲרוּכִּים. חַיִּים שֶׁל שָׁלום. חַיִּים שֶׁל טובָה. חַיִּים שֶׁל בְּרָכָה. חַיִּים שֶׁל פַּרְנָסָה. חַיִּים שֶׁל חִלּוּץ עֲצָמות. חַיִּים שֶׁיֵשׁ בָּהֶם יִרְאַת שָׁמַיִם וְיִרְאַת חֵטְא. חַיִּים שֶׁאֵין בָּהֶם בּוּשָׁה וּכְלִמָּה. חַיִּים שֶׁל עשֶׁר וְכָבוד. חַיִּים שֶׁתְּהֵא בָנוּ אַהֲבַת תּורָה וְיִרְאַת שָׁמַיִם. חַיִּים שֶׁיִּמָלְאוּ מִשְׁאֲלות לִבֵּנוּ לְטובָה אָמֵן סֶלָה:"},{"he":"מִי שֶׁעָשה נִסִּים לַאֲבותֵינוּ וְגָאַל אותָם מֵעַבְדוּת לְחֵרוּת. הוּא יִגְאַל אותָנוּ בְּקָרוב וִיקַבֵּץ נִדָּחֵינוּ מֵאַרְבַּע כַּנְפות הָאָרֶץ. חֲבֵרִים כָּל יִשרָאֵל וְנאמַר אָמֵן:"},{"he":"ראשׁ חדֶשׁ פלוני יִהְיֶה בְּיום פלוני הַבָּא עָלֵינוּ וְעַל כָּל יִשרָאֵל לְטובָה:"},{"he":"יְחַדְּשֵׁהוּ הַקָּדושׁ בָּרוּךְ הוּא עָלֵינוּ וְעַל כָּל עַמּו בֵּית יִשרָאֵל בְּכָל מָקום שֶׁהֵם. לְטובָה וְלִבְרָכָה. לְששון וּלְשמְחָה. לִישׁוּעָה וּלְנֶחָמָה. לְפַרְנָסָה טובָה וּלְכַלְכָּלָה. לְחַיִּים וּלְשָׁלום. לִשְׁמוּעות טובות. וְלִבְשורות טובות. בחורף - וְלִגְשָׁמִים בְּעִתָּם. וְלִרְפוּאָה שְׁלֵמָה. וְלִגְאוּלָה קְרובָה וְנאמַר אָמֵן:"}]},{"id":"communal-prayers-av-harachamim","heading":"Av HaRachamim","group":"Communal Prayers","lines":[{"he":"אין אומרים \"אב הרחמים\" בשבת שאם היה חל ביום חול לא היו אומרים תחנון, ולא בשבת של ארבע הפרשיות, ולא בשבת שמברכין החודש. אבל כשמברכים את החודשים אייר סיון ואב, אומרים אב הרחמים אפילו אם יש ברית מילה או חתן:","note":true},{"he":"אַב הָרַחֲמִים שׁוכֵן מְרומִים. בְּרַחֲמָיו הָעֲצוּמִים הוּא יִפְקד בְּרַחֲמִים הַחֲסִידִים וְהַיְשָׁרִים וְהַתְּמִימִים. קְהִלּות הַקּדֶשׁ שֶׁמָּסְרוּ נַפְשָׁם עַל קְדֻשַּׁת הַשֵּׁם. הַנֶּאֱהָבִים וְהַנְּעִימִים בְּחַיֵּיהֶם וּבְמותָם לא נִפְרָדוּ. מִנְּשָׁרִים קַלּוּ מֵאֲרָיות גָּבֵרוּ לַעֲשות רְצון קונָם וְחֵפֶץ צוּרָם. יִזְכְּרֵם אֱלהֵינוּ לְטובָה עִם שְׁאָר צַדִּיקֵי עולָם. וְיִקום נִקְמַת דַּם עֲבָדָיו הַשָּׁפוּךְ. כַּכָּתוּב בְּתורַת משֶׁה אִישׁ הָאֱלהִים. הַרְנִינוּ גויִם עַמּו כִּי דַם עֲבָדָיו יִקּום וְנָקָם יָשִׁיב לְצָרָיו וְכִפֶּר אַדְמָתו עַמּו: וְעַל יְדֵי עֲבָדֶיךָ הַנְּבִיאִים כָּתוּב לֵאמר. וְנִקֵּיתִי דָּמָם לא נִקֵּיתִי וה' שׁכֵן בְּצִיּון: וּבְכִתְבֵי הַקּדֶשׁ נֶאֱמַר לָמָּה יאמְרוּ הַגּויִם אַיֵּה אֱלהֵיהֶם. יִוָּדַע בַּגּויִם לְעֵינֵינוּ נִקְמַת דַּם עֲבָדֶיךָ הַשָּׁפוּךְ: וְאומֵר, כִּי דרֵשׁ דָּמִים אותָם זָכָר לא שָׁכַח צַעֲקַת עֲנָוִים: וְאומֵר, יָדִין בַּגּויִם מָלֵא גְוִיּות מָחַץ ראשׁ עַל אֶרֶץ רַבָּה. מִנַּחַל בַּדֶּרֶךְ יִשְׁתֶּה עַל כֵּן יָרִים ראשׁ:","en":"The merciful father who dwells upon high will mercifully judge the pious and the upright and pure, the holy congregations who gave up their lives in holy martyrship, who were loved and valued in their lives, and who in their deaths are not abandoned. [They were] lighter than eagles and mightier than lions in doing the will of their creator and the desire of their maker. Remember them for good, O our god, among all the world's righteous, and avenge the spilled blood of your servant, as it is said in the Torah of Moses, man-of-God, \"Acclaim O nations his people, for the blood of his servants he will avenge, and vengeance will be repaid upon his enemies, and his army will cleanse his land.\" And upon the hands of his servants the Prophets it is written, \"And I will avenge their blood which I have not avenged; and the LORD dwells in Zion.\" And in the holy Writings it is said, \"Why do the nations say, 'Where are their gods?' We will see the avengement of your servants' spilled blood made apparent to the nations.\" And it is said, \"For the pursuer of blood will remember them; he will not forget the cries of the oppressed.\" And it is said, \"He judges among the corpse-filled nations, head bowed over the great land. From a stream by the road he drinks -- only then does he lift his head!\""}]},{"id":"ashrei","heading":"Ashrei","lines":[{"he":"אַשְׁרֵי יושְׁבֵי בֵיתֶךָ. עוד יְהַלְלוּךָ סֶּלָה: אַשְׁרֵי הָעָם שֶׁכָּכָה לּו. אַשְׁרֵי הָעָם שה' אֱלהָיו: תְּהִלָּה לְדָוִד. אֲרומִמְךָ אֱלוהַי הַמֶּלֶךְ. וַאֲבָרְכָה שִׁמְךָ לְעולָם וָעֶד: בְּכָל יום אֲבָרְכֶךָּ. וַאֲהַלְלָה שִׁמְךָ לְעולָם וָעֶד: גָּדול ה' וּמְהֻלָּל מְאד. וְלִגְדֻלָּתו אֵין חֵקֶר: דּור לְדור יְשַׁבַּח מַעֲשיךָ. וּגְבוּרתֶיךָ יַגִּידוּ: הֲדַר כְּבוד הודֶךָ. וְדִבְרֵי נִפְלְאתֶיךָ אָשיחָה: וֶעֱזוּז נורְאתֶיךָ יאמֵרוּ. וּגְדֻלָּתְךָ אֲסַפְּרֶנָּה: זֵכֶר רַב טוּבְךָ יַבִּיעוּ. וְצִדְקָתְךָ יְרַנֵּנוּ: חַנּוּן וְרַחוּם ה'. אֶרֶךְ אַפַּיִם וּגְדָל חָסֶד: טוב ה' לַכּל. וְרַחֲמָיו עַל כָּל מַעֲשיו: יודוּךָ ה' כָּל מַעֲשיךָ. וַחֲסִידֶיךָ יְבָרְכוּכָה: כְּבוד מַלְכוּתְךָ יאמֵרוּ. וּגְבוּרָתְךָ יְדַבֵּרוּ: לְהודִיעַ לִבְנֵי הָאָדָם גְּבוּרתָיו. וּכְבוד הֲדַר מַלְכוּתו: מַלְכוּתְךָ מַלְכוּת כָּל עולָמִים. וּמֶמְשַׁלְתְּךָ בְּכָל דּור וָדר: סומֵךְ ה' לְכָל הַנּפְלִים. וְזוקֵף לְכָל הַכְּפוּפִים: עֵינֵי כל אֵלֶיךָ יְשבֵּרוּ. וְאַתָּה נותֵן לָהֶם אֶת אָכְלָם בְּעִתּו: פּותֵחַ אֶת יָדֶךָ. וּמַשבִּיעַ לְכָל חַי רָצון: צַדִּיק ה' בְּכָל דְּרָכָיו. וְחָסִיד בְּכָל מַעֲשיו: קָרוב ה' לְכָל קרְאָיו. לְכל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת: רְצון יְרֵאָיו יַעֲשה. וְאֶת שַׁוְעָתָם יִשְׁמַע וְיושִׁיעֵם: שׁומֵר ה' אֶת כָּל אהֲבָיו. וְאֵת כָּל הָרְשָׁעִים יַשְׁמִיד: תְּהִלַּת ה' יְדַבֶּר פִּי. וִיבָרֵךְ כָּל בָּשר שֵׁם קָדְשׁו לְעולָם וָעֶד: וַאֲנַחְנוּ נְבָרֵךְ יָהּ מֵעַתָּה וְעַד עולָם. הַלְלוּיָהּ:"}]},{"id":"returning-sefer-to-aron","heading":"Returning Sefer to Aron","lines":[{"he":"כשמחזירין הספר תורה להיכל אומרים:","note":true},{"he":"חזן: יְהַלְלוּ אֶת שֵׁם ה' כִּי נִשגָּב שְׁמו לְבַדּו:","note":true},{"he":"קהל: הודו עַל אֶרֶץ וְשָׁמָיִם: וַיָּרֶם קֶרֶן לְעַמּו תְּהִלָּה לְכָל חֲסִידָיו לִבְנֵי יִשרָאֵל עַם קְרבו הַלְלוּיָהּ:","note":true},{"he":"בשבת: מִזְמור לְדָוִד. הָבוּ לה' בְּנֵי אֵלִים. הָבוּ לה' כָּבוד וָעז: הָבוּ לה' כְּבוד שְׁמו. הִשְׁתַּחֲווּ לה' בְּהַדְרַת קדֶשׁ: קול ה' עַל הַמָּיִם. אֵל הַכָּבוד הִרְעִים ה' עַל מַיִם רַבִּים: קול ה' בַּכּחַ. קול ה' בֶּהָדָר: קול ה' שׁבֵר אֲרָזִים. וַיְשַׁבֵּר ה' אֶת אַרְזֵי הַלְּבָנון: וַיַּרְקִידֵם כְּמו עֵגֶל. לְבָנון וְשרְיון כְּמו בֶן רְאֵמִים: קול ה' חצֵב לַהֲבות אֵשׁ: קול ה' יָחִיל מִדְבָּר. יָחִיל ה' מִדְבַּר קָדֵשׁ: קול ה' יְחולֵל אַיָּלות. וַיֶּחֱשף יְעָרות וּבְהֵיכָלו כֻּלּו אמֵר כָּבוד: ה' לַמַּבּוּל יָשָׁב. וַיֵּשֶׁב ה' מֶלֶךְ לְעולָם: ה' עז לְעַמּו יִתֵּן. ה' יְבָרֵךְ אֶת עַמּו בַשָׁלום:","note":true},{"he":"ביו\"ט כשחל בחול: לְדָוִד מִזְמור. לה' הָאָרֶץ וּמְלואָהּ. תֵּבֵל וְישְׁבֵי בָהּ: כִּי הוּא עַל יַמִּים יְסָדָהּ. וְעַל נְהָרות יְכונְנֶהָ: מִי יַעֲלֶה בְהַר ה'. וּמִי יָקוּם בִּמְקום קָדְשׁו: נְקִי כַפַּיִם וּבַר לֵבָב. אֲשֶׁר לא נָשא לַשָּׁוְא נַפְשִׁי וְלא נִשְׁבַּע לְמִרְמָה: יִשּא בְרָכָה מֵאֵת ה'. וּצְדָקָה מֵאֱלהֵי יִשְׁעו: זֶה דּור דּרְשָׁיו. מְבַקְשֵׁי פָנֶיךָ יַעֲקב סֶלָה: שאוּ שְׁעָרִים רָאשֵׁיכֶם וְהִנָּשאוּ פִּתְחֵי עולָם. וְיָבוא מֶלֶךְ הַכָּבוד: מִי זֶה מֶלֶךְ הַכָּבוד. ה' עִזּוּז וְגִבּור. ה' גִּבּור מִלְחָמָה: שאוּ שְׁעָרִים רָאשֵׁיכֶם וּשאוּ פִּתְחֵי עולָם. וְיָבא מֶלֶךְ הַכָּבוד: מִי הוּא זֶה מֶלֶךְ הַכָּבוד. ה' צְבָאות הוּא מֶלֶךְ הַכָּבוד סֶלָה:","note":true},{"he":"כשמכניסים ס\"ת להיכל אומרים: וּבְנֻחה יאמַר. שׁוּבָה ה' רִבְבות אַלְפֵי יִשרָאֵל: קוּמָה ה' לִמְנוּחָתֶךָ. אַתָּה וַאֲרון עֻזֶּךָ: כּהֲנֶיךָ יִלְבְּשׁוּ צֶדֶק. וַחֲסִידֶיךָ יְרַנֵּנוּ: בַּעֲבוּר דָּוִד עַבְדֶּךָ אַל תָּשֵׁב פְּנֵי מְשִׁיחֶךָ: כִּי לֶקַח טוב נָתַתִּי לָכֶם. תּורָתִי אַל תַּעֲזבוּ: עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. וְתמְכֶיהָ מְאֻשָּׁר: דְּרָכֶיהָ דַרְכֵי נעַם וְכָל נְתִיבתֶיהָ שָׁלום: הֲשִׁיבֵנוּ ה' אֵלֶיךָ וְנָשׁוּבָה. חַדֵּשׁ יָמֵינוּ כְּקֶדֶם:","note":true}]},{"id":"half-kaddish","heading":"Half Kaddish","lines":[{"he":"חזן: יִתְגַּדַּל וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. [קהל: אמן] בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵהּ בְּחַיֵּיכון וּבְיומֵיכון וּבְחַיֵּי דְכָל בֵּית יִשרָאֵל בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן: [קהל: אמן] קהל וחזן: יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא: יִתְבָּרַךְ וְיִשְׁתַּבַּח וְיִתְפָּאַר וְיִתְרומַם וְיִתְנַשּא וְיִתְהַדָּר וְיִתְעַלֶּה וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא. בְּרִיךְ הוּא. [קהל: בריך הוא:] לְעֵלָּא בעשי\"ת לְעֵלָּא לְעֵלָּא מִכָּל מִן כָּל בִּרְכָתָא וְשִׁירָתָא תֻּשְׁבְּחָתָא וְנֶחֱמָתָא דַּאֲמִירָן בְּעָלְמָא. וְאִמְרוּ אָמֵן: [קהל: אמן]","note":true}]}];

